    'هر کجای کشور امارات که ملکی برای فروش دارید می تونید با چند کلیک ساده ملکتان را به صورت رایگان در کفو آگهی و در سریع ترین زمان ممکن معامله کنید' => 'هر كجاي كشور امارات كه ملكي براي بيع داريد مي تونيد با جند كليك ساده ملكتان را به صورت رايكان در كفو آكهي و در سريع ترين الوقت ممكن معامله كنيد',
    'هر-کجای-کشور-امارات-که-ملکی-برای-فروش-دارید-می-تونید-با-چند-کلیک-ساده-ملکتان-را-به-صورت-رایگان-در-کفو-آگهی-و-در-سریع-ترین-زمان-ممکن-معامله-کنید' => 'هر-كجاي-كشور-امارات-كه-ملكي-براي-بيع-داريد-مي-تونيد-با-جند-كليك-ساده-ملكتان-را-به-صورت-رايكان-در-كفو-آكهي-و-در-سريع-ترين-الوقت-ممكن-معامله-كنيد',
    'گروه مشاورین املاک کفو با سال‌ها تجربه ارزشمند در حوزه خرید، فروش و سرمایه‌گذاری ملکی در دبی، مفتخر است همراه و مشاور مطمئن شما در این مسیر باشد. تیمی از کارشناسان باتجربه و آگاه به بازار املاک امارات، آماده‌اند تا با ارائه راهکارهای تخصصی، شما را در حفظ و افزایش سرمایه‌تان یاری رسانند.' => 'كروه مستشارين املاك كفو با سال ها تجربه ارزشمند در حوزه شراء، بيع و سرمايه كذاري ملكي در دبي، مفتخر است همراه و مستشار مطمئن شما در اين مسير باشد. تيمي از خبيران باتجربه و آكاه به بازار املاك امارات، آماده اند تا با ارائه راهكارهاي تخصصي، شما را در حفظ و افزايش سرمايه تان ياري رسانند.',
    'گروه-مشاورین-املاک-کفو-با-سال‌ها-تجربه-ارزشمند-در-حوزه-خرید،-فروش-و-سرمایه‌گذاری-ملکی-در-دبی،-مفتخر-است-همراه-و-مشاور-مطمئن-شما-در-این-مسیر-باشد.-تیمی-از-کارشناسان-باتجربه-و-آگاه-به-بازار-املاک-امارات،-آماده‌اند-تا-با-ارائه-راهکارهای-تخصصی،-شما-را-در-حفظ-و-افزایش-سرمایه‌تان-یاری-رسانند.' => 'كروه-مستشارين-املاك-كفو-با-سال ها-تجربه-ارزشمند-در-حوزه-شراء،-بيع-و-سرمايه كذاري-ملكي-در-دبي،-مفتخر-است-همراه-و-مستشار-مطمئن-شما-در-اين-مسير-باشد.-تيمي-از-خبيران-باتجربه-و-آكاه-به-بازار-املاك-امارات،-آماده اند-تا-با-ارائه-راهكارهاي-تخصصي،-شما-را-در-حفظ-و-افزايش-سرمايه تان-ياري-رسانند.',
