    'برای سرعت بخشیدن به فرایند رزرو, ثبت درخواست رزرو توسط میهمان یا قطعی شدن رزرو با بهره گیری از سامانه اس ام اس متنی  به اطلاع میزبان می‌رسد تا در اسرع وقت از وضعیت رزرو آگاهی یافته و اقدامات لازم را به انجام برساند. در مواقع ضروری تیم پشتیبانی گیلندملک نیز با دو طرف رزرو تماس خواهند گرفت. هرگونه تغییری در وضعیت رزرو, به همین روشها به اطلاع دو طرف خواهد رسید.' => 'براي سرعت بخشيدن به فرايند رزرو, إرسال درخواست رزرو توسط ميهمان يا قطعي شدن رزرو با بهره كيري از سامانه اس ام اس متني به اطلاع ميزبان مي رسد تا در اسرع وقت از الحالة رزرو آكاهي يافته و اقدامات لازم را به انجام برساند. در مواقع ضروري تيم الدعم الفني كيلندملك نيز با دو طرف رزرو تماس خواهند كرفت. هركونه تغييري در الحالة رزرو, به همين روشها به اطلاع دو طرف خواهد رسيد.',
    'برای-سرعت-بخشیدن-به-فرایند-رزرو,-ثبت-درخواست-رزرو-توسط-میهمان-یا-قطعی-شدن-رزرو-با-بهره-گیری-از-سامانه-اس-ام-اس-متنی--به-اطلاع-میزبان-می‌رسد-تا-در-اسرع-وقت-از-وضعیت-رزرو-آگاهی-یافته-و-اقدامات-لازم-را-به-انجام-برساند.-در-مواقع-ضروری-تیم-پشتیبانی-گیلندملک-نیز-با-دو-طرف-رزرو-تماس-خواهند-گرفت.-هرگونه-تغییری-در-وضعیت-رزرو,-به-همین-روشها-به-اطلاع-دو-طرف-خواهد-رسید.' => 'براي-سرعت-بخشيدن-به-فرايند-رزرو,-إرسال-درخواست-رزرو-توسط-ميهمان-يا-قطعي-شدن-رزرو-با-بهره-كيري-از-سامانه-اس-ام-اس-متني--به-اطلاع-ميزبان-مي رسد-تا-در-اسرع-وقت-از-الحالة-رزرو-آكاهي-يافته-و-اقدامات-لازم-را-به-انجام-برساند.-در-مواقع-ضروري-تيم-الدعم الفني-كيلندملك-نيز-با-دو-طرف-رزرو-تماس-خواهند-كرفت.-هركونه-تغييري-در-الحالة-رزرو,-به-همين-روشها-به-اطلاع-دو-طرف-خواهد-رسيد.',
