    'طرح‌نما یا لورم ایپسوم به نوشتاری آزمایشی و بی‌معنی در صنعت چاپ، صفحه‌آرایی و طراحی گرافیک گفته می‌شود. طراح گرافیک از این نوشتار به‌عنوان عنصری از ترکیب‌بندی برای پُر کردن صفحه و ارائهٔ اولیهٔ شکل ظاهری و کلیِ طرح سفارش‌گرفته‌شده‌استفاده می‌کند، تا ازنظر گرافیکی نشانگر چگونگی نوع و اندازهٔ قلم و ظاهرِ متن باشد.' => 'طرح نما يا لورم ايبسوم به نوشتاري آزمايشي و بي معني در صنعت جاب، صفحه آرايي و طراحي كرافيك كفته مي شود. طراح كرافيك از اين نوشتار به العنوان عنصري از تركيب بندي براي بُر كرفضن صفحه و ارائهٔ اوليهٔ شكل ظاهري و كليِ طرح سفارش كرفته شده استفاده مي كند، تا ازنظر كرافيكي نشانكر جكونكي نوع و اندازهٔ قلم و ظاهرِ متن باشد.',
    'طرح‌نما-یا-لورم-ایپسوم-به-نوشتاری-آزمایشی-و-بی‌معنی-در-صنعت-چاپ،-صفحه‌آرایی-و-طراحی-گرافیک-گفته-می‌شود.-طراح-گرافیک-از-این-نوشتار-به‌عنوان-عنصری-از-ترکیب‌بندی-برای-پُر-کردن-صفحه-و-ارائهٔ-اولیهٔ-شکل-ظاهری-و-کلیِ-طرح-سفارش‌گرفته‌شده‌استفاده-می‌کند،-تا-ازنظر-گرافیکی-نشانگر-چگونگی-نوع-و-اندازهٔ-قلم-و-ظاهرِ-متن-باشد.' => 'طرح نما-يا-لورم-ايبسوم-به-نوشتاري-آزمايشي-و-بي معني-در-صنعت-جاب،-صفحه آرايي-و-طراحي-كرافيك-كفته-مي شود.-طراح-كرافيك-از-اين-نوشتار-به العنوان-عنصري-از-تركيب بندي-براي-بُر-كرفضن-صفحه-و-ارائهٔ-اوليهٔ-شكل-ظاهري-و-كليِ-طرح-سفارش كرفته شده استفاده-مي كند،-تا-ازنظر-كرافيكي-نشانكر-جكونكي-نوع-و-اندازهٔ-قلم-و-ظاهرِ-متن-باشد.',
    'لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ و با استفاده از طراحان گرافیک است. چاپگرها و متون بلکه روزنامه و مجله در ستون و سطرآنچنان که لازم است و برای شرایط فعلی تکنولوژی مورد نیاز و کاربردهای متنوع با هدف بهبود ابزارهای کاربردی می باشد.' => 'لورم ايبسوم متن ساختكي با توليد سادكي الاسمفهوم از صنعت جاب و با استفاده از طراحان كرافيك است. جابكرها و متون بلكه روزالاسمه و مجله در ستون و سطرآنجنان كه لازم است و براي شرايط فعلي تكنولوزي مورفض نياز و كاربرفضهاي متنوع با هدف بهبود ابزارهاي كاربرفضي مي باشد.',
    'لورم-ایپسوم-متن-ساختگی-با-تولید-سادگی-نامفهوم-از-صنعت-چاپ-و-با-استفاده-از-طراحان-گرافیک-است.-چاپگرها-و-متون-بلکه-روزنامه-و-مجله-در-ستون-و-سطرآنچنان-که-لازم-است-و-برای-شرایط-فعلی-تکنولوژی-مورد-نیاز-و-کاربردهای-متنوع-با-هدف-بهبود-ابزارهای-کاربردی-می-باشد.' => 'لورم-ايبسوم-متن-ساختكي-با-توليد-سادكي-الاسمفهوم-از-صنعت-جاب-و-با-استفاده-از-طراحان-كرافيك-است.-جابكرها-و-متون-بلكه-روزالاسمه-و-مجله-در-ستون-و-سطرآنجنان-كه-لازم-است-و-براي-شرايط-فعلي-تكنولوزي-مورفض-نياز-و-كاربرفضهاي-متنوع-با-هدف-بهبود-ابزارهاي-كاربرفضي-مي-باشد.',
