    'مکان' => 'مكان',
    'خانه رؤیایی خود را با تجربه‌ای بی‌نظیر از تصاویر واقعی و گسترده‌ترین مجموعه آگهی‌ها پیدا کنید، شامل املاکی که در هیچ جای دیگر نخواهید یافت.' => 'خانه رؤيايي خود را با تجربه اي بي نظير از تصاوير واقعي و كسترفضه ترين مجموعه آكهي ها بيدا كنيد، شامل املاكي كه در هيج جاي ديكر نخواهيد يافت.',
    'خانه-رؤیایی-خود-را-با-تجربه‌ای-بی‌نظیر-از-تصاویر-واقعی-و-گسترده‌ترین-مجموعه-آگهی‌ها-پیدا-کنید،-شامل-املاکی-که-در-هیچ-جای-دیگر-نخواهید-یافت.' => 'خانه-رؤيايي-خود-را-با-تجربه اي-بي نظير-از-تصاوير-واقعي-و-كسترفضه ترين-مجموعه-آكهي ها-بيدا-كنيد،-شامل-املاكي-كه-در-هيج-جاي-ديكر-نخواهيد-يافت.',
