    'اجاره-یک-خانه' => 'اجاره یک خانه',
    'ما تجربه‌ای آنلاین و بی‌نقص برای شما فراهم کرده‌ایم – از جستجو در بزرگ‌ترین شبکه اجاره تا ثبت درخواست و پرداخت اجاره، همه چیز به ساده‌ترین شکل ممکن.' => 'ما تجربه اي آنلاين و بي نقص براي شما فراهم كرفضه ايم – از بحث در بزرك ترين شبكه إيجار تا إرسال درخواست و برفضاخت إيجار، همه جيز به ساده ترين شكل ممكن.',
    'ما-تجربه‌ای-آنلاین-و-بی‌نقص-برای-شما-فراهم-کرده‌ایم-–-از-جستجو-در-بزرگ‌ترین-شبکه-اجاره-تا-ثبت-درخواست-و-پرداخت-اجاره،-همه-چیز-به-ساده‌ترین-شکل-ممکن.' => 'ما-تجربه اي-آنلاين-و-بي نقص-براي-شما-فراهم-كرفضه ايم-–-از-بحث-در-بزرك ترين-شبكه-إيجار-تا-إرسال-درخواست-و-برفضاخت-إيجار،-همه-جيز-به-ساده ترين-شكل-ممكن.',
