    'چنانچه قصد دارید از قیمت دقیق ملک خود مطلع شوید، فرم زیر را پر کنید تا همکاران ما با شما تماس بگیرند.' => 'جنانجه قصد داريد از السعر دقيق ملك خود مطلع شويد، فرم زير را بر كنيد تا همكاران ما با شما تماس بكيرند.',
    'چنانچه-قصد-دارید-از-قیمت-دقیق-ملک-خود-مطلع-شوید،-فرم-زیر-را-پر-کنید-تا-همکاران-ما-با-شما-تماس-بگیرند.' => 'جنانجه-قصد-داريد-از-السعر-دقيق-ملك-خود-مطلع-شويد،-فرم-زير-را-بر-كنيد-تا-همكاران-ما-با-شما-تماس-بكيرند.',
    'اطلاعات با موفقیت ذخیره گردید. به زودی همکاران ما با شما تماس میگیرند.' => 'المعلومات با نجاح حفظ كرفضيد. به زودي همكاران ما با شما تماس ميكيرند.',
    'اطلاعات-با-موفقیت-ذخیره-گردید.-به-زودی-همکاران-ما-با-شما-تماس-میگیرند.' => 'المعلومات-با-نجاح-حفظ-كرفضيد.-به-زودي-همكاران-ما-با-شما-تماس-ميكيرند.',
    'محاسبه آنلاین حق کمیسیون املاک' => 'محاسبه آنلاين حق كميسيون املاك',
    'محاسبه-آنلاین-حق-کمیسیون-املاک' => 'محاسبه آنلاین حق کمیسیون املاک',
    'محاسبه' => 'محاسبه',
    'حق کمیسیون مشاورین املاک به کارمزدی گفته می‌شود که مشاورین به‌عنوان دستمزد دریافت می‌کنند و در قدیم بنا به اختیار خریدار و فروشنده به آژانس املاک پرداخت می‌شد، اما از سال ۱۳۷۹ بر اساس قانون فرمول خاصی برای محاسبه حق کمیسیون برای انواع فعالیت های تجاری در زمینه مسکن مانند خرید، فروش، رهن و اجاره ی انواع املاک تجاری، مسکونی و اداری دریافت میشود. پرداخت کمیسیون یکی از مفاد و قوانین معاملاتی در کشور است و طرفین معامله ملزم به پرداخت آن هستند."کمیسیون املاک" توسط فروشنده و خریدار یا مؤجر و مستأجر به مشاوران املاک پرداخت می‌شود. با توجه به بازار املاک، این مبلغ بر اساس مصوبه صنف شهر مورد نظر برای هر معامله بر اساس فاکتورهای خاصی محاسبه می‌شود. مشاورین املاک موظفند، بر اساس تعرفه‌ای که هر سال از سوی' => 'حق كميسيون مستشارين املاك به كارمزدي كفته مي شود كه مستشارين به العنوان دستمزد استلام مي كنند و در قديم بنا به اختيار شراءار و بيعنده به آزانس املاك برفضاخت مي شد، اما از سال ۱۳۷۹ بر اساس قانون فرمول خاصي براي محاسبه حق كميسيون براي انواع نشطيت هاي تجاري در أرضه مسكن مانند شراء، بيع، رهن / تأمين و إيجار ي انواع املاك تجاري، سكني و إداري استلام ميشود. برفضاخت كميسيون يكي از مفاد و قوانين معاملاتي در كشور است و طرفين معامله ملزم به برفضاخت آن هستند."كميسيون املاك" توسط بيعنده و شراءار يا مؤجر و مستأجر به مستشاران املاك برفضاخت مي شود. با توجه به بازار املاك، اين مبلغ بر اساس مصوبه صنف المدينة مورفض نظر براي هر معامله بر اساس فاكتورهاي خاصي محاسبه مي شود. مستشارين املاك موظفند، بر اساس تعرفه اي كه هر سال از سوي',
    'حق-کمیسیون-مشاورین-املاک-به-کارمزدی-گفته-می‌شود-که-مشاورین-به‌عنوان-دستمزد-دریافت-می‌کنند-و-در-قدیم-بنا-به-اختیار-خریدار-و-فروشنده-به-آژانس-املاک-پرداخت-می‌شد،-اما-از-سال-۱۳۷۹-بر-اساس-قانون-فرمول-خاصی-برای-محاسبه-حق-کمیسیون-برای-انواع-فعالیت-های-تجاری-در-زمینه-مسکن-مانند-خرید،-فروش،-رهن-و-اجاره-ی-انواع-املاک-تجاری،-مسکونی-و-اداری-دریافت-میشود.-پرداخت-کمیسیون-یکی-از-مفاد-و-قوانین-معاملاتی-در-کشور-است-و-طرفین-معامله-ملزم-به-پرداخت-آن-هستند."کمیسیون-املاک"-توسط-فروشنده-و-خریدار-یا-مؤجر-و-مستأجر-به-مشاوران-املاک-پرداخت-می‌شود.-با-توجه-به-بازار-املاک،-این-مبلغ-بر-اساس-مصوبه-صنف-شهر-مورد-نظر-برای-هر-معامله-بر-اساس-فاکتورهای-خاصی-محاسبه-می‌شود.-مشاورین-املاک-موظفند،-بر-اساس-تعرفه‌ای-که-هر-سال-از-سوی' => 'حق-كميسيون-مستشارين-املاك-به-كارمزدي-كفته-مي شود-كه-مستشارين-به العنوان-دستمزد-استلام-مي كنند-و-در-قديم-بنا-به-اختيار-شراءار-و-بيعنده-به-آزانس-املاك-برفضاخت-مي شد،-اما-از-سال-۱۳۷۹-بر-اساس-قانون-فرمول-خاصي-براي-محاسبه-حق-كميسيون-براي-انواع-نشطيت-هاي-تجاري-در-أرضه-مسكن-مانند-شراء،-بيع،-رهن / تأمين-و-إيجار-ي-انواع-املاك-تجاري،-سكني-و-إداري-استلام-ميشود.-برفضاخت-كميسيون-يكي-از-مفاد-و-قوانين-معاملاتي-در-كشور-است-و-طرفين-معامله-ملزم-به-برفضاخت-آن-هستند."كميسيون-املاك"-توسط-بيعنده-و-شراءار-يا-مؤجر-و-مستأجر-به-مستشاران-املاك-برفضاخت-مي شود.-با-توجه-به-بازار-املاك،-اين-مبلغ-بر-اساس-مصوبه-صنف-المدينة-مورفض-نظر-براي-هر-معامله-بر-اساس-فاكتورهاي-خاصي-محاسبه-مي شود.-مستشارين-املاك-موظفند،-بر-اساس-تعرفه اي-كه-هر-سال-از-سوي',
    ': این فرمول کشوری است و ملاک هر شهرستان، نامه اتحادیه مشاورین املاک آن شهرستان است که ممکن است با فرمول کشوری کمی تفاوت داشته باشد.' => ': این فرمول کشوری است و ملاک هر المدينةستان، الاسمه اتحادیه مستشارین املاک آن المدينةستان است که ممکن است با فرمول کشوری کمی تفاوت داشته باشد.',
    ':-این-فرمول-کشوری-است-و-ملاک-هر-شهرستان،-نامه-اتحادیه-مشاورین-املاک-آن-شهرستان-است-که-ممکن-است-با-فرمول-کشوری-کمی-تفاوت-داشته-باشد.' => ': این فرمول کشوری است و ملاک هر شهرستان، نامه اتحادیه مشاورین املاک آن شهرستان است که ممکن است با فرمول کشوری کمی تفاوت داشته باشد.',
    'همانطور که می دانید در ایران، خرید و یا فروش یک ملک یا اجاره کردن آن می‌تواند یک سرمایه‌گذاری مطمئن برای خانواده باشد، چرا که هم نرخ مسکن دائما رو به افزایش است و هم با خرید یک منزل می‌توان آن را به منبعی برای کسب درآمد تبدیل کرد. بنابراین هیچ‌کس دوست ندارد در این زمینه بی‌گدار به آب زده و پس‌انداز و سرمایه خود را در خانه‌ای با مشکلات حقوقی و فنی فراوان هدر دهد. در عین حال هیچ انسانی مایل نیست بخش اعظمی از حقوق ماهیانه خود را صرف پرداخت اجاره ملکی کند که قیمت آن از استانداردهای روز بازار بالاتر است یا مطلوبیتی برای اهالی خانه ندارد.' => 'همانطور كه مي دانيد در ايران، شراء و يا بيع يك ملك يا إيجار كرفضن آن مي تواند يك سرمايه كذاري مطمئن براي خانواده باشد، جرا كه هم نرخ مسكن دائما رو به افزايش است و هم با شراء يك منزل مي توان آن را به منبعي براي كسب درآمد تبديل كرفض. بنابراين هيج كس دوست ندارفض در اين أرضه بي كدار به آب زده و بس انداز و سرمايه خود را در خانه اي با مشكلات حقوقي و فني فراوان هدر دهد. در عين حال هيج انساني مايل نيست بخش اعظمي از حقوق ماهيانه خود را صرف برفضاخت إيجار ملكي كند كه السعر آن از الإمارةدارفضهاي روز بازار بالاتر است يا مطلوبيتي براي اهالي خانه ندارفض.',
    'همانطور-که-می-دانید-در-ایران،-خرید-و-یا-فروش-یک-ملک-یا-اجاره-کردن-آن-می‌تواند-یک-سرمایه‌گذاری-مطمئن-برای-خانواده-باشد،-چرا-که-هم-نرخ-مسکن-دائما-رو-به-افزایش-است-و-هم-با-خرید-یک-منزل-می‌توان-آن-را-به-منبعی-برای-کسب-درآمد-تبدیل-کرد.-بنابراین-هیچ‌کس-دوست-ندارد-در-این-زمینه-بی‌گدار-به-آب-زده-و-پس‌انداز-و-سرمایه-خود-را-در-خانه‌ای-با-مشکلات-حقوقی-و-فنی-فراوان-هدر-دهد.-در-عین-حال-هیچ-انسانی-مایل-نیست-بخش-اعظمی-از-حقوق-ماهیانه-خود-را-صرف-پرداخت-اجاره-ملکی-کند-که-قیمت-آن-از-استانداردهای-روز-بازار-بالاتر-است-یا-مطلوبیتی-برای-اهالی-خانه-ندارد.' => 'همانطور-كه-مي-دانيد-در-ايران،-شراء-و-يا-بيع-يك-ملك-يا-إيجار-كرفضن-آن-مي تواند-يك-سرمايه كذاري-مطمئن-براي-خانواده-باشد،-جرا-كه-هم-نرخ-مسكن-دائما-رو-به-افزايش-است-و-هم-با-شراء-يك-منزل-مي توان-آن-را-به-منبعي-براي-كسب-درآمد-تبديل-كرفض.-بنابراين-هيج كس-دوست-ندارفض-در-اين-أرضه-بي كدار-به-آب-زده-و-بس انداز-و-سرمايه-خود-را-در-خانه اي-با-مشكلات-حقوقي-و-فني-فراوان-هدر-دهد.-در-عين-حال-هيج-انساني-مايل-نيست-بخش-اعظمي-از-حقوق-ماهيانه-خود-را-صرف-برفضاخت-إيجار-ملكي-كند-كه-السعر-آن-از-الإمارةدارفضهاي-روز-بازار-بالاتر-است-يا-مطلوبيتي-براي-اهالي-خانه-ندارفض.',
    'مجموعه این حساسیت‌ها باعث شده تا پیدا کردن ملکی که از نظر موقعیت جغرافیایی، مصالح ساخت ملک، اصول مهندسی و سایر فاکتورها بهترین بازار باشد، به امری پیچیده و دشوار و نیازمند تخصص تبدیل شود. شاید بتوان به جرات گفت پیدا کردن چنین ملکی خود یک کار تمام‌ وقت است که به تمام انرژی، تمرکز و صبر شما احتیاج دارد. به همین دلیل است که در بسیاری از کشورهای دنیا شغل مهمی با عنوان “مشاورین املاک” شکل گرفته. این افراد در ازای دریافت حق العمل، خدماتی را در حوزه ملک و مسکن به شما ارائه می‌دهند و با توجه به گستردگی و پیچیدگی های این کار بهتر است به یک دپارتمان املاک معتبر، مراجعه کنید. که در این امر دپارتمان املاک کومه با دارا بودن مشاورین متخصص در زمینه های مختلف ملکی می تواند همچون نیاز های ملکی شما را آسان، سریع و مطمئن مرتفع نماید.' => 'مجموعه اين حساسيت ها باعث شده تا بيدا كرفضن ملكي كه از نظر موقعيت جغرافيايي، مصالح ساخت ملك، اصول مهندسي و ساير فاكتورها بهترين بازار باشد، به امري بيجيده و دشوار و نيازمند تخصص تبديل شود. شايد بتوان به جرات كفت بيدا كرفضن جنين ملكي خود يك كار تمام وقت است كه به تمام انرزي، تمركز و صبر شما احتياج دارفض. به همين دليل است كه در بسياري از كشورهاي دنيا شغل مهمي با العنوان “مستشارين املاك” شكل كرفته. اين افراد در ازاي استلام حق العمل، خدماتي را در حوزه ملك و مسكن به شما ارائه مي دهند و با توجه به كسترفضكي و بيجيدكي هاي اين كار بهتر است به يك دبارتمان املاك معتبر، مراجعه كنيد. كه در اين امر دبارتمان املاك كومه با دارا بودن مستشارين متخصص در أرضه هاي مختلف ملكي مي تواند همجون نياز هاي ملكي شما را آسان، سريع و مطمئن مرتفع نمايد.',
    'مجموعه-این-حساسیت‌ها-باعث-شده-تا-پیدا-کردن-ملکی-که-از-نظر-موقعیت-جغرافیایی،-مصالح-ساخت-ملک،-اصول-مهندسی-و-سایر-فاکتورها-بهترین-بازار-باشد،-به-امری-پیچیده-و-دشوار-و-نیازمند-تخصص-تبدیل-شود.-شاید-بتوان-به-جرات-گفت-پیدا-کردن-چنین-ملکی-خود-یک-کار-تمام‌-وقت-است-که-به-تمام-انرژی،-تمرکز-و-صبر-شما-احتیاج-دارد.-به-همین-دلیل-است-که-در-بسیاری-از-کشورهای-دنیا-شغل-مهمی-با-عنوان-“مشاورین-املاک”-شکل-گرفته.-این-افراد-در-ازای-دریافت-حق-العمل،-خدماتی-را-در-حوزه-ملک-و-مسکن-به-شما-ارائه-می‌دهند-و-با-توجه-به-گستردگی-و-پیچیدگی-های-این-کار-بهتر-است-به-یک-دپارتمان-املاک-معتبر،-مراجعه-کنید.-که-در-این-امر-دپارتمان-املاک-کومه-با-دارا-بودن-مشاورین-متخصص-در-زمینه-های-مختلف-ملکی-می-تواند-همچون-نیاز-های-ملکی-شما-را-آسان،-سریع-و-مطمئن-مرتفع-نماید.' => 'مجموعه-اين-حساسيت ها-باعث-شده-تا-بيدا-كرفضن-ملكي-كه-از-نظر-موقعيت-جغرافيايي،-مصالح-ساخت-ملك،-اصول-مهندسي-و-ساير-فاكتورها-بهترين-بازار-باشد،-به-امري-بيجيده-و-دشوار-و-نيازمند-تخصص-تبديل-شود.-شايد-بتوان-به-جرات-كفت-بيدا-كرفضن-جنين-ملكي-خود-يك-كار-تمام -وقت-است-كه-به-تمام-انرزي،-تمركز-و-صبر-شما-احتياج-دارفض.-به-همين-دليل-است-كه-در-بسياري-از-كشورهاي-دنيا-شغل-مهمي-با-العنوان-“مستشارين-املاك”-شكل-كرفته.-اين-افراد-در-ازاي-استلام-حق-العمل،-خدماتي-را-در-حوزه-ملك-و-مسكن-به-شما-ارائه-مي دهند-و-با-توجه-به-كسترفضكي-و-بيجيدكي-هاي-اين-كار-بهتر-است-به-يك-دبارتمان-املاك-معتبر،-مراجعه-كنيد.-كه-در-اين-امر-دبارتمان-املاك-كومه-با-دارا-بودن-مستشارين-متخصص-در-أرضه-هاي-مختلف-ملكي-مي-تواند-همجون-نياز-هاي-ملكي-شما-را-آسان،-سريع-و-مطمئن-مرتفع-نمايد.',
    'در این مقاله قصد داریم همه‌ی آن چیزی که نیاز دارید درمورد حق کمیسیون املاک بدانید برای شما توضیح دهیم. اگر قصد خرید یا فروش و یا اجاره املاک را دارید لازم است این مقاله را تا انتها دنبال کنید.' => 'در اين مقاله قصد داريم همه ي آن جيزي كه نياز داريد درمورفض حق كميسيون املاك بدانيد براي شما توضيح دهيم. اكر قصد شراء يا بيع و يا إيجار املاك را داريد لازم است اين مقاله را تا انتها دنبال كنيد.',
    'در-این-مقاله-قصد-داریم-همه‌ی-آن-چیزی-که-نیاز-دارید-درمورد-حق-کمیسیون-املاک-بدانید-برای-شما-توضیح-دهیم.-اگر-قصد-خرید-یا-فروش-و-یا-اجاره-املاک-را-دارید-لازم-است-این-مقاله-را-تا-انتها-دنبال-کنید.' => 'در-اين-مقاله-قصد-داريم-همه ي-آن-جيزي-كه-نياز-داريد-درمورفض-حق-كميسيون-املاك-بدانيد-براي-شما-توضيح-دهيم.-اكر-قصد-شراء-يا-بيع-و-يا-إيجار-املاك-را-داريد-لازم-است-اين-مقاله-را-تا-انتها-دنبال-كنيد.',
    'در هر معامله‌ای امکان فسخ وجود دارد؛ اما آیا در صورت فسخ قرارداد خرید یا اجاره، کمیسیون املاک پرداخت می‌شود؟ همانطور که در بالا به طور کامل حق کمیسیون را تعریف کردیم، حق کمیسیون مشاورین املاک در ازای خدماتی است که آن‌ها برای پیشبرد معامله و عقد قرارداد انجام داده‌اند، این افراد پس از فسخ معامله نیز می‌توانند حق کمیسیون خود را طلب کنند. البته لازم به ذکر است که فسخ قراردادهای خرید و اجاره بر اساس مفاد قانونی، در شرایط خاصی امکان‌پذیر است و طرفین باید در خصوص فسخ قرارداد با یکدیگر اتفاق نظر داشته باشند. در چنین شرایطی، تمامی حق کمیسیون مشاورین املاک ۱۴۰3 (حتی سهم طرف دوم) را طرف فسخ‌کننده باید پرداخت کند.' => 'در هر معامله اي امكان فسخ وجود دارفض؛ اما آيا در صورت فسخ قرارفضاد شراء يا إيجار، كميسيون املاك برفضاخت مي شود؟ همانطور كه در بالا به طور كامل حق كميسيون را تعريف كرفضيم، حق كميسيون مستشارين املاك در ازاي خدماتي است كه آن ها براي بيشبرفض معامله و عقد قرارفضاد انجام داده اند، اين افراد بس از فسخ معامله نيز مي توانند حق كميسيون خود را طلب كنند. البته لازم به ذكر است كه فسخ قرارفضادهاي شراء و إيجار بر اساس مفاد قانوني، در شرايط خاصي امكان بذير است و طرفين بايد در خصوص فسخ قرارفضاد با يكديكر اتفاق نظر داشته باشند. در جنين شرايطي، تمامي حق كميسيون مستشارين املاك ۱۴۰3 (حتي سهم طرف دوم) را طرف فسخ كننده بايد برفضاخت كند.',
    'در-هر-معامله‌ای-امکان-فسخ-وجود-دارد؛-اما-آیا-در-صورت-فسخ-قرارداد-خرید-یا-اجاره،-کمیسیون-املاک-پرداخت-می‌شود؟-همانطور-که-در-بالا-به-طور-کامل-حق-کمیسیون-را-تعریف-کردیم،-حق-کمیسیون-مشاورین-املاک-در-ازای-خدماتی-است-که-آن‌ها-برای-پیشبرد-معامله-و-عقد-قرارداد-انجام-داده‌اند،-این-افراد-پس-از-فسخ-معامله-نیز-می‌توانند-حق-کمیسیون-خود-را-طلب-کنند.-البته-لازم-به-ذکر-است-که-فسخ-قراردادهای-خرید-و-اجاره-بر-اساس-مفاد-قانونی،-در-شرایط-خاصی-امکان‌پذیر-است-و-طرفین-باید-در-خصوص-فسخ-قرارداد-با-یکدیگر-اتفاق-نظر-داشته-باشند.-در-چنین-شرایطی،-تمامی-حق-کمیسیون-مشاورین-املاک-۱۴۰3-(حتی-سهم-طرف-دوم)-را-طرف-فسخ‌کننده-باید-پرداخت-کند.' => 'در-هر-معامله اي-امكان-فسخ-وجود-دارفض؛-اما-آيا-در-صورت-فسخ-قرارفضاد-شراء-يا-إيجار،-كميسيون-املاك-برفضاخت-مي شود؟-همانطور-كه-در-بالا-به-طور-كامل-حق-كميسيون-را-تعريف-كرفضيم،-حق-كميسيون-مستشارين-املاك-در-ازاي-خدماتي-است-كه-آن ها-براي-بيشبرفض-معامله-و-عقد-قرارفضاد-انجام-داده اند،-اين-افراد-بس-از-فسخ-معامله-نيز-مي توانند-حق-كميسيون-خود-را-طلب-كنند.-البته-لازم-به-ذكر-است-كه-فسخ-قرارفضادهاي-شراء-و-إيجار-بر-اساس-مفاد-قانوني،-در-شرايط-خاصي-امكان بذير-است-و-طرفين-بايد-در-خصوص-فسخ-قرارفضاد-با-يكديكر-اتفاق-نظر-داشته-باشند.-در-جنين-شرايطي،-تمامي-حق-كميسيون-مستشارين-املاك-۱۴۰3-(حتي-سهم-طرف-دوم)-را-طرف-فسخ كننده-بايد-برفضاخت-كند.',
    'حق کمیسیون املاک در سال ۱۴۰۳ تفاوتی با سال ۱۴۰۲ نداشته و تا اعلام رسمی از سمت کمیسیون نظارت هر شهر، با همان نرخ سال گذشته محاسبه می‌گردد.' => 'حق كميسيون املاك در سال ۱۴۰۳ تفاوتي با سال ۱۴۰۲ نداشته و تا اعلام رسمي از سمت كميسيون نظارت هر المدينة، با همان نرخ سال كذشته محاسبه مي كرفضد.',
    'حق-کمیسیون-املاک-در-سال-۱۴۰۳-تفاوتی-با-سال-۱۴۰۲-نداشته-و-تا-اعلام-رسمی-از-سمت-کمیسیون-نظارت-هر-شهر،-با-همان-نرخ-سال-گذشته-محاسبه-می‌گردد.' => 'حق-كميسيون-املاك-در-سال-۱۴۰۳-تفاوتي-با-سال-۱۴۰۲-نداشته-و-تا-اعلام-رسمي-از-سمت-كميسيون-نظارت-هر-المدينة،-با-همان-نرخ-سال-كذشته-محاسبه-مي كرفضد.',
    'نرخ محاسبه کمیسیون در هر شهر توسط کمیسیون نظارت آن شهر مشخص می گردد و نحوه محاسبه و درصد آن در هر شهر متفاوت است اما عموما نحوه محاسبه به دو صورت انجام می شود.' => 'نرخ محاسبه كميسيون در هر المدينة توسط كميسيون نظارت آن المدينة مشخص مي كرفضد و نحوه محاسبه و درصد آن در هر المدينة متفاوت است اما عموما نحوه محاسبه به دو صورت انجام مي شود.',
    'نرخ-محاسبه-کمیسیون-در-هر-شهر-توسط-کمیسیون-نظارت-آن-شهر-مشخص-می-گردد-و-نحوه-محاسبه-و-درصد-آن-در-هر-شهر-متفاوت-است-اما-عموما-نحوه-محاسبه-به-دو-صورت-انجام-می-شود.' => 'نرخ-محاسبه-كميسيون-در-هر-المدينة-توسط-كميسيون-نظارت-آن-المدينة-مشخص-مي-كرفضد-و-نحوه-محاسبه-و-درصد-آن-در-هر-المدينة-متفاوت-است-اما-عموما-نحوه-محاسبه-به-دو-صورت-انجام-مي-شود.',
    'در این روش درصد محاسبه میزان ثابتی دارد و افزایش قیمت تاثیری در درصد محاسبه ندارد، با توجه افزایش قیمت ها، شهرهایی مثل تهران- قم از روش ثابت استفاده می‌کنند و مبلغ به صورت درصدی از ارزش کل معامله تعیین می شود.' => 'در این روش درصد محاسبه میزان ثابتی دارفض و افزایش السعر تاثیری در درصد محاسبه ندارفض، با توجه افزایش السعر ها، المدينةهایی مثل تهران- قم از روش ثابت استفاده می‌کنند و مبلغ به صورت درصدی از ارزش کل معامله تعیین می شود.',
    'در-این-روش-درصد-محاسبه-میزان-ثابتی-دارد-و-افزایش-قیمت-تاثیری-در-درصد-محاسبه-ندارد،-با-توجه-افزایش-قیمت-ها،-شهرهایی-مثل-تهران--قم-از-روش-ثابت-استفاده-می‌کنند-و-مبلغ-به-صورت-درصدی-از-ارزش-کل-معامله-تعیین-می-شود.' => 'در این روش درصد محاسبه میزان ثابتی دارد و افزایش قیمت تاثیری در درصد محاسبه ندارد، با توجه افزایش قیمت ها، شهرهایی مثل تهران- قم از روش ثابت استفاده می‌کنند و مبلغ به صورت درصدی از ارزش کل معامله تعیین می شود.',
    'در بسیاری موارد مشاورین متخلف جهت دریافت کمیسیون بیشتر با فروشنده توافق میکنند که قیمت ملک را بالاتر برده و مازاد قیمت را به عنوان دستمزد دریافت کرده و همزمان درصد مصوب را از خریدار دریافت میکنند.' => 'در بسیاری موارفض مستشارین متخلف جهت استلام کمیسیون بیشتر با بيعنده توافق میکنند که السعر ملک را بالاتر برفضه و مازاد السعر را به العنوان دستمزد استلام کرفضه و همالوقت درصد مصوب را از شراءار استلام میکنند.',
    'در-بسیاری-موارد-مشاورین-متخلف-جهت-دریافت-کمیسیون-بیشتر-با-فروشنده-توافق-میکنند-که-قیمت-ملک-را-بالاتر-برده-و-مازاد-قیمت-را-به-عنوان-دستمزد-دریافت-کرده-و-همزمان-درصد-مصوب-را-از-خریدار-دریافت-میکنند.' => 'در بسیاری موارد مشاورین متخلف جهت دریافت کمیسیون بیشتر با فروشنده توافق میکنند که قیمت ملک را بالاتر برده و مازاد قیمت را به عنوان دستمزد دریافت کرده و همزمان درصد مصوب را از خریدار دریافت میکنند.',
    'در این روش مبلغ کل ملک در میزان درصد محاسبه تاثیر گذار است، به این صورت که اگر مبلغ بیشتر از مقداری مشخصی باشد درصد محاسبه تا پله تایین شده به یک میزان و مازاد قیمت از پله تایین شده با درصد پایین تری محاسبه می‌شود.' => 'در اين روش مبلغ كل ملك در ميزان درصد محاسبه تاثير كذار است، به اين صورت كه اكر مبلغ بيشتر از مقداري مشخصي باشد درصد محاسبه تا بله تايين شده به يك ميزان و مازاد السعر از بله تايين شده با درصد بايين تري محاسبه مي شود.',
    'در-این-روش-مبلغ-کل-ملک-در-میزان-درصد-محاسبه-تاثیر-گذار-است،-به-این-صورت-که-اگر-مبلغ-بیشتر-از-مقداری-مشخصی-باشد-درصد-محاسبه-تا-پله-تایین-شده-به-یک-میزان-و-مازاد-قیمت-از-پله-تایین-شده-با-درصد-پایین-تری-محاسبه-می‌شود.' => 'در-اين-روش-مبلغ-كل-ملك-در-ميزان-درصد-محاسبه-تاثير-كذار-است،-به-اين-صورت-كه-اكر-مبلغ-بيشتر-از-مقداري-مشخصي-باشد-درصد-محاسبه-تا-بله-تايين-شده-به-يك-ميزان-و-مازاد-السعر-از-بله-تايين-شده-با-درصد-بايين-تري-محاسبه-مي شود.',
    'طبق مصوبه اتحادیه املاک تهران کمیسیون خرید و فروش ملک به صورت ثابت انجام می‌شود و هر کدام از طرفین معامله موظف به پرداخت ۲۵ صدم درصد قیمت ملک به علاوه 10 درصد مالیات ارزش افزوده می‌باشند.' => 'طبق مصوبه اتحاديه املاك تهران كميسيون شراء و بيع ملك به صورت ثابت انجام مي شود و هر كدام از طرفين معامله موظف به برفضاخت ۲۵ صدم درصد السعر ملك به علاوه 10 درصد ماليات ارزش افزوده مي باشند.',
    'طبق-مصوبه-اتحادیه-املاک-تهران-کمیسیون-خرید-و-فروش-ملک-به-صورت-ثابت-انجام-می‌شود-و-هر-کدام-از-طرفین-معامله-موظف-به-پرداخت-۲۵-صدم-درصد-قیمت-ملک-به-علاوه-10-درصد-مالیات-ارزش-افزوده-می‌باشند.' => 'طبق-مصوبه-اتحاديه-املاك-تهران-كميسيون-شراء-و-بيع-ملك-به-صورت-ثابت-انجام-مي شود-و-هر-كدام-از-طرفين-معامله-موظف-به-برفضاخت-۲۵-صدم-درصد-السعر-ملك-به-علاوه-10-درصد-ماليات-ارزش-افزوده-مي باشند.',
    'طرفین ۰.۲۵ درصد از قیمت کل ملک + 10 درصد مالیات ارزش افزوده' => 'طرفین ۰.۲۵ درصد از السعر کل ملک + 10 درصد مالیات ارزش افزوده',
    'طرفین-۰.۲۵-درصد-از-قیمت-کل-ملک-+-10-درصد-مالیات-ارزش-افزوده' => 'طرفین ۰.۲۵ درصد از قیمت کل ملک + 10 درصد مالیات ارزش افزوده',
    'تبدیل مبلغ رهن به اجاره و جمع این مبلغ با اجاره‌ بهای ماهانه' => 'تبدیل مبلغ رهن / تأمين به إيجار و جمع این مبلغ با إيجار‌ بهای ماهانه',
    'تبدیل-مبلغ-رهن-به-اجاره-و-جمع-این-مبلغ-با-اجاره‌-بهای-ماهانه' => 'تبدیل مبلغ رهن به اجاره و جمع این مبلغ با اجاره‌ بهای ماهانه',
    'تعیین 30 درصد از این مبلغ به عنوان حق کمیسیون مشاور' => 'تعیین 30 درصد از این مبلغ به العنوان حق کمیسیون مستشار',
    'تعیین-30-درصد-از-این-مبلغ-به-عنوان-حق-کمیسیون-مشاور' => 'تعیین 30 درصد از این مبلغ به عنوان حق کمیسیون مشاور',
    'محاسبه 10 درصد از حق کمیسیون به عنوان مالیات بر ارزش افزوده و پرداخت آن به مشاور املاک' => 'محاسبه 10 درصد از حق كميسيون به العنوان ماليات بر ارزش افزوده و برفضاخت آن به مستشار املاك',
    'محاسبه-10-درصد-از-حق-کمیسیون-به-عنوان-مالیات-بر-ارزش-افزوده-و-پرداخت-آن-به-مشاور-املاک' => 'محاسبه-10-درصد-از-حق-كميسيون-به-العنوان-ماليات-بر-ارزش-افزوده-و-برفضاخت-آن-به-مستشار-املاك',
    'کمیسیون تمدید اجاره ملک نیز برابر است با یک دهم مبلغ کمیسیون قرارداد اجاره بدین صورت که ابتدا مبلغ کمیسیون را محاسبه و مبلغ را تقسیم به ده می‌کنند.' => 'کمیسیون تمدید إيجار ملک نیز برابر است با یک دهم مبلغ کمیسیون قرارفضاد إيجار بدین صورت که ابتدا مبلغ کمیسیون را محاسبه و مبلغ را تقسیم به ده می‌کنند.',
