    'کمیسیون-تمدید-اجاره-ملک-در-شهر-تبریز-نیز-برابر-است-با-یک-دهم-مبلغ-کمیسیون-قرارداد-اجاره-به-علاوه-۹-درصد-مالیت-ارزش-افزوده-بدین-صورت-که-ابتدا-مبلغ-کمیسیون-را-محاسبه-و-مبلغ-را-تقسیم-به-ده-می‌کنند.' => 'کمیسیون تمدید اجاره ملک در شهر تبریز نیز برابر است با یک دهم مبلغ کمیسیون قرارداد اجاره به علاوه ۹ درصد مالیت ارزش افزوده بدین صورت که ابتدا مبلغ کمیسیون را محاسبه و مبلغ را تقسیم به ده می‌کنند.',
    'function addFavorite(id){ $.get("/estates/favorite/" + id, function (data, status) { if (data.result == 1) { toast({ type: \'success\', text: \'ملک مورد نظر به لیست نشان شده های شما افزوده شد.\' }); $(".itemFavorite-" + id).addClass("favorited"); } else { toast({ type: \'error\', text: \'ملک مورد نظر از لیست نشان شده های شما حذف شد.\' }); $(".itemFavorite-" + id).removeClass("favorited"); } }); }' => 'function addFavorite(id){ $.get("/estates/favorite/" + id, function (data, status) { if (data.result == 1) { toast({ type: \'success\', text: \'ملک مورفض نظر به قائمة نشان شده های شما افزوده شد.\' }); $(".itemFavorite-" + id).addClass("favorited"); } else { toast({ type: \'error\', text: \'ملک مورفض نظر از قائمة نشان شده های شما حذف شد.\' }); $(".itemFavorite-" + id).removeClass("favorited"); } }); }',
    'function-addFavorite(id){-$.get("/estates/favorite/"-+-id,-function-(data,-status)-{-if-(data.result-==-1)-{-toast({-type:-\'success\',-text:-\'ملک-مورد-نظر-به-لیست-نشان-شده-های-شما-افزوده-شد.\'-});-$(".itemFavorite-"-+-id).addClass("favorited");-}-else-{-toast({-type:-\'error\',-text:-\'ملک-مورد-نظر-از-لیست-نشان-شده-های-شما-حذف-شد.\'-});-$(".itemFavorite-"-+-id).removeClass("favorited");-}-});-}' => 'function addFavorite(id){ $.get("/estates/favorite/" + id, function (data, status) { if (data.result == 1) { toast({ type: \'success\', text: \'ملک مورد نظر به لیست نشان شده های شما افزوده شد.\' }); $(".itemFavorite-" + id).addClass("favorited"); } else { toast({ type: \'error\', text: \'ملک مورد نظر از لیست نشان شده های شما حذف شد.\' }); $(".itemFavorite-" + id).removeClass("favorited"); } }); }',
    'در صورتیکه تمایل دارید به عنوان مشاور اصلی این ملک باشید, لطفا تمامی فیلدها با بکگراند رنگی را پر نمایید' => 'در صورتيكه تمايل داريد به العنوان مستشار اصلي اين ملك باشيد, لطفا تمامي فيلدها با بككراند رنكي را بر نماييد',
