    'عکس‌هایی از فضای داخل و بیرون ملک اضافه کنید. آگهی‌های دارای عکس تا «۳ برابر» بیشتر توسط کاربران دیده می‌شوند. حداقل اندازه تصویر 600x600 و حداکثر میزان حجم هر تصویر 10 مگابایت می باشد' => 'صورة هايي از فضاي داخل و بيرون ملك اضافه كنيد. آكهي هاي داراي صورة تا «۳ برابر» بيشتر توسط كاربران ديده مي شوند. حداقل اندازه صورة 600x600 و حداكثر ميزان حجم هر صورة 10 مكابايت مي باشد',
