    '$(function-()-{-$(\'#sortable-images\').sortable({-items:-\'.image-item\',-update:-function-()-{-$(\'#sortable-images-.image-item\').each(function-(index)-{-const-id-=-$(this).data(\'id\');-//-مقدار-hidden-را-به‌روزرسانی-می‌کنیم:-مثلا-"3:1"-$(this).find(\'input[type="hidden"]\').val(id-+-\':\'-+-(index-+-1));-});-}-});-});' => '$(function () { $(\'#sortable-images\').sortable({ items: \'.image-item\', update: function () { $(\'#sortable-images .image-item\').each(function (index) { const id = $(this).data(\'id\'); // مقدار hidden را به‌روزرسانی می‌کنیم: مثلا "3:1" $(this).find(\'input[type="hidden"]\').val(id + \':\' + (index + 1)); }); } }); });',
