    '\')-uploadedDocumentMap[file.name]-=-response.name-},-removedfile:-function-(file)-{-file.previewElement.remove()-var-name-=-\'\'-if-(typeof-file.file_name-!==-\'undefined\')-{-name-=-file.file_name-}-else-{-name-=-uploadedDocumentMap[file.name]-}-$(\'form#add\').find(\'input[name="document[]"][value="\'-+-name-+-\'"]\').remove()-},-init:-function()-{-//-check-file-size-this.on("maxfilesexceeded",-function(file){-this.removeFile(file);-alert("حداکثر-تعداد-تصاویر-10-عدد-میباشد!");-});-//-check-dimensions-this.on("thumbnail",-function-(file)-{-if-(file.height' => '\') uploadedDocumentMap[file.name] = response.name }, removedfile: function (file) { file.previewElement.remove() var name = \'\' if (typeof file.file_name !== \'undefined\') { name = file.file_name } else { name = uploadedDocumentMap[file.name] } $(\'form#add\').find(\'input[name="document[]"][value="\' + name + \'"]\').remove() }, init: function() { // check file size this.on("maxfilesexceeded", function(file){ this.removeFile(file); alert("حداکثر تعداد تصاویر 10 عدد میباشد!"); }); // check dimensions this.on("thumbnail", function (file) { if (file.height',
    'لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ، و با استفاده از طراحان گرافیک است، چاپگرها و متون بلکه روزنامه و مجله در ستون و سطرآنچنان که لازم است، و برای شرایط فعلی تکنولوژی مورد نیاز، و کاربردهای متنوع با هدف بهبود ابزارهای کاربردی می باشد، کتابهای زیادی در شصت و سه درصد گذشته حال و آینده، شناخت فراوان جامعه و متخصصان را می طلبد، تا با نرم افزارها شناخت بیشتری را برای طراحان رایانه ای علی الخصوص طراحان خلاقی، و فرهنگ پیشرو در زبان فارسی ایجاد کرد، در این صورت می توان امید داشت که تمام و دشواری موجود در ارائه راهکارها، و شرایط سخت تایپ به پایان رسد و زمان مورد نیاز شامل حروفچینی دستاوردهای اصلی، و جوابگوی سوالات پیوسته اهل دنیای موجود طراحی اساسا مورد استفاده قرار گیرد.لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ، و با استفاده از طراحان گرافیک است، چاپگرها و متون بلکه روزنامه و مجله در ستون و سطرآنچنان که لازم است، و برای شرایط فعلی تکنولوژی مورد نیاز، و کاربردهای متنوع با هدف بهبود ابزارهای کاربردی می باشد، کتابهای زیادی در شصت و سه درصد گذشته حال و آینده، شناخت فراوان جامعه و متخصصان را می طلبد، تا با نرم افزارها شناخت بیشتری را برای طراحان رایانه ای علی الخصوص طراحان خلاقی، و فرهنگ پیشرو در زبان فارسی ایجاد کرد، در این صورت می توان امید داشت که تمام و دشواری موجود در ارائه راهکارها، و شرایط سخت تایپ به پایان رسد و زمان مورد نیاز شامل حروفچینی دستاوردهای اصلی، و جوابگوی سوالات پیوسته اهل دنیای موجود طراحی اساسا مورد استفاده قرار گیرد.لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ، و با استفاده از طراحان گرافیک است، چاپگرها و متون بلکه روزنامه و مجله در ستون و سطرآنچنان که لازم است، و برای شرایط فعلی تکنولوژی مورد نیاز، و کاربردهای متنوع با هدف بهبود ابزارهای کاربردی می باشد، کتابهای زیادی در شصت و سه درصد گذشته حال و آینده، شناخت فراوان جامعه و متخصصان را می طلبد، تا با نرم افزارها شناخت بیشتری را برای طراحان رایانه ای علی الخصوص طراحان خلاقی، و فرهنگ پیشرو در زبان فارسی ایجاد کرد، در این صورت می توان امید داشت که تمام و دشواری موجود در ارائه راهکارها، و شرایط سخت تایپ به پایان رسد و زمان مورد نیاز شامل حروفچینی دستاوردهای اصلی، و جوابگوی سوالات پیوسته اهل دنیای موجود طراحی اساسا مورد استفاده قرار گیرد.' => 'لورم ايبسوم متن ساختكي با توليد سادكي الاسمفهوم از صنعت جاب، و با استفاده از طراحان كرافيك است، جابكرها و متون بلكه روزالاسمه و مجله در ستون و سطرآنجنان كه لازم است، و براي شرايط فعلي تكنولوزي مورفض نياز، و كاربرفضهاي متنوع با هدف بهبود ابزارهاي كاربرفضي مي باشد، كتابهاي زيادي در شصت و سه درصد كذشته حال و آينده، شناخت فراوان جامعه و متخصصان را مي طلبد، تا با نرم افزارها شناخت بيشتري را براي طراحان رايانه اي علي الخصوص طراحان خلاقي، و فرهن / تأمينك بيشرو در زبان فارسي إنشاء كرفض، در اين صورت مي توان اميد داشت كه تمام و دشواري موجود در ارائه راهكارها، و شرايط سخت تايب به بايان رسد و الوقت مورفض نياز شامل حروفجيني دستاورفضهاي اصلي، و جوابكوي سوالات بيوسته اهل دنياي موجود طراحي اساسا مورفض استفاده قرار كيرفض.لورم ايبسوم متن ساختكي با توليد سادكي الاسمفهوم از صنعت جاب، و با استفاده از طراحان كرافيك است، جابكرها و متون بلكه روزالاسمه و مجله در ستون و سطرآنجنان كه لازم است، و براي شرايط فعلي تكنولوزي مورفض نياز، و كاربرفضهاي متنوع با هدف بهبود ابزارهاي كاربرفضي مي باشد، كتابهاي زيادي در شصت و سه درصد كذشته حال و آينده، شناخت فراوان جامعه و متخصصان را مي طلبد، تا با نرم افزارها شناخت بيشتري را براي طراحان رايانه اي علي الخصوص طراحان خلاقي، و فرهن / تأمينك بيشرو در زبان فارسي إنشاء كرفض، در اين صورت مي توان اميد داشت كه تمام و دشواري موجود در ارائه راهكارها، و شرايط سخت تايب به بايان رسد و الوقت مورفض نياز شامل حروفجيني دستاورفضهاي اصلي، و جوابكوي سوالات بيوسته اهل دنياي موجود طراحي اساسا مورفض استفاده قرار كيرفض.لورم ايبسوم متن ساختكي با توليد سادكي الاسمفهوم از صنعت جاب، و با استفاده از طراحان كرافيك است، جابكرها و متون بلكه روزالاسمه و مجله در ستون و سطرآنجنان كه لازم است، و براي شرايط فعلي تكنولوزي مورفض نياز، و كاربرفضهاي متنوع با هدف بهبود ابزارهاي كاربرفضي مي باشد، كتابهاي زيادي در شصت و سه درصد كذشته حال و آينده، شناخت فراوان جامعه و متخصصان را مي طلبد، تا با نرم افزارها شناخت بيشتري را براي طراحان رايانه اي علي الخصوص طراحان خلاقي، و فرهن / تأمينك بيشرو در زبان فارسي إنشاء كرفض، در اين صورت مي توان اميد داشت كه تمام و دشواري موجود در ارائه راهكارها، و شرايط سخت تايب به بايان رسد و الوقت مورفض نياز شامل حروفجيني دستاورفضهاي اصلي، و جوابكوي سوالات بيوسته اهل دنياي موجود طراحي اساسا مورفض استفاده قرار كيرفض.',
