    'بله. ما در کفو خدماتی مانند مدیریت ملک، اجاره دادن، نظارت بر تعمیرات و تمدید اقامت را نیز به مشتریان عزیز ارائه می‌دهیم.' => 'بله. ما در کفو خدماتی مانند مدیریت ملک، إيجار دادن، نظارت بر تعمیرات و تمدید اقامت را نیز به العميلان عزیز ارائه می‌دهیم.',
    'بله.-ما-در-کفو-خدماتی-مانند-مدیریت-ملک،-اجاره-دادن،-نظارت-بر-تعمیرات-و-تمدید-اقامت-را-نیز-به-مشتریان-عزیز-ارائه-می‌دهیم.' => 'بله. ما در کفو خدماتی مانند مدیریت ملک، اجاره دادن، نظارت بر تعمیرات و تمدید اقامت را نیز به مشتریان عزیز ارائه می‌دهیم.',
