    '18.-کفو-چه-نوع-املاکی-را-ارائه-می‌دهد؟' => '18.-كفو-جه-نوع-املاكي-را-ارائه-مي دهد؟',
    'کفو در زمینه فروش آپارتمان‌، ویلا، واحدهای لوکس، املاک تجاری، پیش‌فروش و پروژه‌های در حال ساخت در مناطق مختلف دبی فعالیت دارد.' => 'كفو در أرضه بيع شقة ، فيلا، واحدهاي لوكس، املاك تجاري، بيش بيع و مشروع هاي در حال ساخت در مناطق مختلف دبي نشطيت دارفض.',
    'کفو-در-زمینه-فروش-آپارتمان‌،-ویلا،-واحدهای-لوکس،-املاک-تجاری،-پیش‌فروش-و-پروژه‌های-در-حال-ساخت-در-مناطق-مختلف-دبی-فعالیت-دارد.' => 'كفو-در-أرضه-بيع-شقة ،-فيلا،-واحدهاي-لوكس،-املاك-تجاري،-بيش بيع-و-مشروع هاي-در-حال-ساخت-در-مناطق-مختلف-دبي-نشطيت-دارفض.',
    'AOS.init({ disable: \'mobile\' // غیرفعال کردن انیمیشن‌ها در موبایل });' => 'AOS.init({ disable: \'mobile\' // غیرنشط کرفضن انیمیشن‌ها در الجوال });',
    'AOS.init({-disable:-\'mobile\'-//-غیرفعال-کردن-انیمیشن‌ها-در-موبایل-});' => 'AOS.init({ disable: \'mobile\' // غیرفعال کردن انیمیشن‌ها در موبایل });',
    'ورود با حساب گوگل' => 'تسجيل الدخول با حساب كوكل',
    'ورود-با-حساب-گوگل' => 'تسجيل الدخول-با-حساب-كوكل',
