    '\' }); const currency = getCookie(\'currency_unit\'); // مثلا "dirham" const area = getCookie(\'area_unit\'); // مثلا "feet" if (currency) { let currencyRadio = document.querySelector(`input[name="currency"][value="${currency}"]`); if (currencyRadio) currencyRadio.checked = true; } if (area) { let areaRadio = document.querySelector(`input[name="area"][value="${area}"]`); if (areaRadio) areaRadio.checked = true; } changevahed(currency , area); });' => '\' }); const currency = getCookie(\'currency_unit\'); // مثلا "dirham" const area = getCookie(\'area_unit\'); // مثلا "feet" if (currency) { let currencyRadio = document.querySelector(`input[name="currency"][value="${currency}"]`); if (currencyRadio) currencyRadio.checked = true; } if (area) { let areaRadio = document.querySelector(`input[name="area"][value="${area}"]`); if (areaRadio) areaRadio.checked = true; } changevahed(currency , area); });',
    '\'-});-const-currency-=-getCookie(\'currency_unit\');-//-مثلا-"dirham"-const-area-=-getCookie(\'area_unit\');-//-مثلا-"feet"-if-(currency)-{-let-currencyRadio-=-document.querySelector(`input[name="currency"][value="${currency}"]`);-if-(currencyRadio)-currencyRadio.checked-=-true;-}-if-(area)-{-let-areaRadio-=-document.querySelector(`input[name="area"][value="${area}"]`);-if-(areaRadio)-areaRadio.checked-=-true;-}-changevahed(currency-,-area);-});' => '\' }); const currency = getCookie(\'currency_unit\'); // مثلا "dirham" const area = getCookie(\'area_unit\'); // مثلا "feet" if (currency) { let currencyRadio = document.querySelector(`input[name="currency"][value="${currency}"]`); if (currencyRadio) currencyRadio.checked = true; } if (area) { let areaRadio = document.querySelector(`input[name="area"][value="${area}"]`); if (areaRadio) areaRadio.checked = true; } changevahed(currency , area); });',
    'حداکثر عمر بنا:' => 'حداکثر عمر المبنى:',
