    'مشتریان منتظر حذف یا ویرایش' => 'العميلان منتظر حذف یا تعديل',
    'مشتریان-منتظر-حذف-یا-ویرایش' => 'مشتریان منتظر حذف یا ویرایش',
    'چنانچه قصد دارید با گیلند ملک همکاری کنید لطفا فرم زیر را پر کنید تا همکاران ما با شما تماس بگیرند.' => 'جنانجه قصد داريد با كيلند ملك همكاري كنيد لطفا فرم زير را بر كنيد تا همكاران ما با شما تماس بكيرند.',
    'چنانچه-قصد-دارید-با-گیلند-ملک-همکاری-کنید-لطفا-فرم-زیر-را-پر-کنید-تا-همکاران-ما-با-شما-تماس-بگیرند.' => 'جنانجه-قصد-داريد-با-كيلند-ملك-همكاري-كنيد-لطفا-فرم-زير-را-بر-كنيد-تا-همكاران-ما-با-شما-تماس-بكيرند.',
    'نکات زیر را مطالعه کنید تا با اطلاعات کافی در گیلند ملک میزبان شوید و با خیال آسوده کسب درآمد کنید.' => 'نكات زير را مطالعه كنيد تا با المعلومات كافي در كيلند ملك ميزبان شويد و با خيال آسوده كسب درآمد كنيد.',
    'نکات-زیر-را-مطالعه-کنید-تا-با-اطلاعات-کافی-در-گیلند-ملک-میزبان-شوید-و-با-خیال-آسوده-کسب-درآمد-کنید.' => 'نكات-زير-را-مطالعه-كنيد-تا-با-المعلومات-كافي-در-كيلند-ملك-ميزبان-شويد-و-با-خيال-آسوده-كسب-درآمد-كنيد.',
    '1- اقامتگاه خودر را ثبت کنید' => '1- اقامتكاه خودر را إرسال كنيد',
    '1--اقامتگاه-خودر-را-ثبت-کنید' => '1--اقامتكاه-خودر-را-إرسال-كنيد',
    'حال می بایست برای معرفی اقامتگاه خود به گردشگران, یک نمایه (پروفایل) برای اقامتگاه خود ایجاد کنید‎.‎' => 'حال مي بايست براي معرفي اقامتكاه خود به كرفضشكران, يك نمايه (بروملف) براي اقامتكاه خود إنشاء كنيد‎.‎',
    'حال-می-بایست-برای-معرفی-اقامتگاه-خود-به-گردشگران,-یک-نمایه-(پروفایل)-برای-اقامتگاه-خود-ایجاد-کنید‎.‎' => 'حال-مي-بايست-براي-معرفي-اقامتكاه-خود-به-كرفضشكران,-يك-نمايه-(بروملف)-براي-اقامتكاه-خود-إنشاء-كنيد‎.‎',
    'در ‎نمایه اقامتگاه‎, شما می بایست مشخصات دقیق منزل و امکانات قابل استفاده توسط میهمانان را مشخص کنید. ‎عکسهایی واضح و جدید‎ ‏از اقامتگاه خود فراهم نموده و‎ Upload ‎کنید, همچنین ‎نرخ اجاره بها و تقویم اجاره‎ منزل خود را نیز تنظیم کنید . در آخر مقرراتی که می باید توسط میهمانان رعایت شود را نیز مشخص کنید. ‎نمایه اقامتگاه شما درواقع بیانگر مشخصات و ویژگیهای واقعی ‏منزل شما برای گردشگران علاقه مند خواهد بود‎.‎' => 'در ‎نمايه اقامتكاه‎, شما مي بايست مشخصات دقيق منزل و امكانات قابل استفاده توسط ميهمانان را مشخص كنيد. ‎صورةهايي واضح و جديد‎ ‏از اقامتكاه خود فراهم نموده و‎ Upload ‎كنيد, همجنين ‎نرخ إيجار بها و تقويم إيجار‎ منزل خود را نيز تنظيم كنيد . در آخر مقرراتي كه مي بايد توسط ميهمانان رعايت شود را نيز مشخص كنيد. ‎نمايه اقامتكاه شما درواقع بيانكر مشخصات و ويزكيهاي واقعي ‏منزل شما براي كرفضشكران علاقه مند خواهد بود‎.‎',
    'در-‎نمایه-اقامتگاه‎,-شما-می-بایست-مشخصات-دقیق-منزل-و-امکانات-قابل-استفاده-توسط-میهمانان-را-مشخص-کنید.-‎عکسهایی-واضح-و-جدید‎-‏از-اقامتگاه-خود-فراهم-نموده-و‎-Upload-‎کنید,-همچنین-‎نرخ-اجاره-بها-و-تقویم-اجاره‎-منزل-خود-را-نیز-تنظیم-کنید-.-در-آخر-مقرراتی-که-می-باید-توسط-میهمانان-رعایت-شود-را-نیز-مشخص-کنید.-‎نمایه-اقامتگاه-شما-درواقع-بیانگر-مشخصات-و-ویژگیهای-واقعی-‏منزل-شما-برای-گردشگران-علاقه-مند-خواهد-بود‎.‎' => 'در-‎نمايه-اقامتكاه‎,-شما-مي-بايست-مشخصات-دقيق-منزل-و-امكانات-قابل-استفاده-توسط-ميهمانان-را-مشخص-كنيد.-‎صورةهايي-واضح-و-جديد‎-‏از-اقامتكاه-خود-فراهم-نموده-و‎-Upload-‎كنيد,-همجنين-‎نرخ-إيجار-بها-و-تقويم-إيجار‎-منزل-خود-را-نيز-تنظيم-كنيد-.-در-آخر-مقرراتي-كه-مي-بايد-توسط-ميهمانان-رعايت-شود-را-نيز-مشخص-كنيد.-‎نمايه-اقامتكاه-شما-درواقع-بيانكر-مشخصات-و-ويزكيهاي-واقعي-‏منزل-شما-براي-كرفضشكران-علاقه-مند-خواهد-بود‎.‎',
    'شما در کنار ثبت مشخصات و امکانات اقامتگاه خود, مواردی همچون ‎ اجاره بها و مقررات منزل‎ را نیز تعیین می کنید. سپس نمایه اقامتگاه شما در وبسایت ‎منتشر‎ می شود و برای مسافرین و گردشگران به نمایش درمی آید. گردشگران با جستجو در وبسایت, در صورتی که مشخصات اقامتگاه شما را مناسب نیاز خود بیابند درصورت قبول مقررات منزل, برای اجاره اقامتگاه در بازه زمانی ‏مد نظر با گیلندملک تماس میگیرند.‏ درصورت تایید شما و پرداخت صورتحساب توسط مهمان، رزرو قطعی می شود.' => 'شما در كنار إرسال مشخصات و امكانات اقامتكاه خود, موارفضي همجون ‎ إيجار بها و مقررات منزل‎ را نيز تعيين مي كنيد. سبس نمايه اقامتكاه شما در وبسايت ‎منتشر‎ مي شود و براي مسافرين و كرفضشكران به عرض درمي آيد. كرفضشكران با بحث در وبسايت, در صورتي كه مشخصات اقامتكاه شما را مناسب نياز خود بيابند درصورت قبول مقررات منزل, براي إيجار اقامتكاه در بازه الوقتي ‏مد نظر با كيلندملك تماس ميكيرند.‏ درصورت تأكيد شما و برفضاخت صورتحساب توسط مهمان، رزرو قطعي مي شود.',
    'شما-در-کنار-ثبت-مشخصات-و-امکانات-اقامتگاه-خود,-مواردی-همچون-‎-اجاره-بها-و-مقررات-منزل‎-را-نیز-تعیین-می-کنید.-سپس-نمایه-اقامتگاه-شما-در-وبسایت-‎منتشر‎-می-شود-و-برای-مسافرین-و-گردشگران-به-نمایش-درمی-آید.-گردشگران-با-جستجو-در-وبسایت,-در-صورتی-که-مشخصات-اقامتگاه-شما-را-مناسب-نیاز-خود-بیابند-درصورت-قبول-مقررات-منزل,-برای-اجاره-اقامتگاه-در-بازه-زمانی-‏مد-نظر-با-گیلندملک-تماس-میگیرند.‏-درصورت-تایید-شما-و-پرداخت-صورتحساب-توسط-مهمان،-رزرو-قطعی-می-شود.' => 'شما-در-كنار-إرسال-مشخصات-و-امكانات-اقامتكاه-خود,-موارفضي-همجون-‎-إيجار-بها-و-مقررات-منزل‎-را-نيز-تعيين-مي-كنيد.-سبس-نمايه-اقامتكاه-شما-در-وبسايت-‎منتشر‎-مي-شود-و-براي-مسافرين-و-كرفضشكران-به-عرض-درمي-آيد.-كرفضشكران-با-بحث-در-وبسايت,-در-صورتي-كه-مشخصات-اقامتكاه-شما-را-مناسب-نياز-خود-بيابند-درصورت-قبول-مقررات-منزل,-براي-إيجار-اقامتكاه-در-بازه-الوقتي-‏مد-نظر-با-كيلندملك-تماس-ميكيرند.‏-درصورت-تأكيد-شما-و-برفضاخت-صورتحساب-توسط-مهمان،-رزرو-قطعي-مي-شود.',
    'امکانات تعبیه شده در سایت بگونه ای ست تا پس از صرف وقت کافی برای ثبت و انتشار اقامتگاه خود, بتوانید تمام مراحل میزبانی را طی فرایندی ساده و کاربردی و با صرف زمانی اندک, برای شما امکانپذیر نماید. با این وجود, ما از لحظه ثبت‌نام، ثبت اقامتگاه و آغاز میزبانی, در کنارتان هستیم و شما را در این مسیر هیجان انگیز همراهی میکنیم.' => 'امكانات تعبيه شده در سايت بكونه اي ست تا بس از صرف وقت كافي براي إرسال و انتشار اقامتكاه خود, بتوانيد تمام مراحل ميزباني را طي فرايندي ساده و كاربرفضي و با صرف الوقتي اندك, براي شما امكانبذير نمايد. با اين وجود, ما از لحظه إرسال الاسم، إرسال اقامتكاه و آغاز ميزباني, در كنارتان هستيم و شما را در اين مسير هيجان انكيز همراهي ميكنيم.',
    'امکانات-تعبیه-شده-در-سایت-بگونه-ای-ست-تا-پس-از-صرف-وقت-کافی-برای-ثبت-و-انتشار-اقامتگاه-خود,-بتوانید-تمام-مراحل-میزبانی-را-طی-فرایندی-ساده-و-کاربردی-و-با-صرف-زمانی-اندک,-برای-شما-امکانپذیر-نماید.-با-این-وجود,-ما-از-لحظه-ثبت‌نام،-ثبت-اقامتگاه-و-آغاز-میزبانی,-در-کنارتان-هستیم-و-شما-را-در-این-مسیر-هیجان-انگیز-همراهی-میکنیم.' => 'امكانات-تعبيه-شده-در-سايت-بكونه-اي-ست-تا-بس-از-صرف-وقت-كافي-براي-إرسال-و-انتشار-اقامتكاه-خود,-بتوانيد-تمام-مراحل-ميزباني-را-طي-فرايندي-ساده-و-كاربرفضي-و-با-صرف-الوقتي-اندك,-براي-شما-امكانبذير-نمايد.-با-اين-وجود,-ما-از-لحظه-إرسال الاسم،-إرسال-اقامتكاه-و-آغاز-ميزباني,-در-كنارتان-هستيم-و-شما-را-در-اين-مسير-هيجان-انكيز-همراهي-ميكنيم.',
    '2- برای ورود مهمانان آماده شوید' => '2- برای تسجيل الدخول مهمانان آماده شوید',
    '2--برای-ورود-مهمانان-آماده-شوید' => '2- برای ورود مهمانان آماده شوید',
    'میزبان های محبوب, به گرمی از میهمان خود استقبال می کنند. بعضی ورود میهمان را با چای و لبخند خاطره انگیز می کنند. اینکه چگونه محبوب میهمان خود می شوید با شماست.‎' => 'ميزبان هاي محبوب, به كرمي از ميهمان خود استقبال مي كنند. بعضي تسجيل الدخول ميهمان را با جاي و لبخند خاطره انكيز مي كنند. اينكه جكونه محبوب ميهمان خود مي شويد با شماست.‎',
    'میزبان-های-محبوب,-به-گرمی-از-میهمان-خود-استقبال-می-کنند.-بعضی-ورود-میهمان-را-با-چای-و-لبخند-خاطره-انگیز-می-کنند.-اینکه-چگونه-محبوب-میهمان-خود-می-شوید-با-شماست.‎' => 'ميزبان-هاي-محبوب,-به-كرمي-از-ميهمان-خود-استقبال-مي-كنند.-بعضي-تسجيل الدخول-ميهمان-را-با-جاي-و-لبخند-خاطره-انكيز-مي-كنند.-اينكه-جكونه-محبوب-ميهمان-خود-مي-شويد-با-شماست.‎',
    'پس از قطعی شدن رزرو اقامتگاه, سند رزرو قطعی حاوی اطلاعات کامل رزرو , نام و نام خانوادگی, تعداد نفرات, تاریخ و ساعت ورود و خروج, جزییات صورتحساب پرداخت شده, آدرس دقیق اقامتگاه و شماره تماس میهمان و میزبان برای هر دو طرف ارسال می گردد. توصیه می شود میزبان پیش از شروع سفر با میهمان تماس گرفته و هماهنگی های لازم برای نحوه و زمان تحویل اقامتگاه به ایشان را به انجام برساند تا میهمان با خیالی آسوده سفر خود را آغاز نماید.' => 'بس از قطعي شدن رزرو اقامتكاه, صك الملكية رزرو قطعي حاوي المعلومات كامل رزرو , الاسم و الاسم خانوادكي, تعداد نفرات, التاريخ و ساعت تسجيل الدخول و تسجيل الخروج, جزييات صورتحساب برفضاخت شده, الالعنوان دقيق اقامتكاه و شماره تماس ميهمان و ميزبان براي هر دو طرف إرسال مي كرفضد. توصيه مي شود ميزبان بيش از شروع سفر با ميهمان تماس كرفته و هماهنكي هاي لازم براي نحوه و الوقت تحويل اقامتكاه به ايشان را به انجام برساند تا ميهمان با خيالي آسوده سفر خود را آغاز نمايد.',
    'پس-از-قطعی-شدن-رزرو-اقامتگاه,-سند-رزرو-قطعی-حاوی-اطلاعات-کامل-رزرو-,-نام-و-نام-خانوادگی,-تعداد-نفرات,-تاریخ-و-ساعت-ورود-و-خروج,-جزییات-صورتحساب-پرداخت-شده,-آدرس-دقیق-اقامتگاه-و-شماره-تماس-میهمان-و-میزبان-برای-هر-دو-طرف-ارسال-می-گردد.-توصیه-می-شود-میزبان-پیش-از-شروع-سفر-با-میهمان-تماس-گرفته-و-هماهنگی-های-لازم-برای-نحوه-و-زمان-تحویل-اقامتگاه-به-ایشان-را-به-انجام-برساند-تا-میهمان-با-خیالی-آسوده-سفر-خود-را-آغاز-نماید.' => 'بس-از-قطعي-شدن-رزرو-اقامتكاه,-صك الملكية-رزرو-قطعي-حاوي-المعلومات-كامل-رزرو-,-الاسم-و-الاسم-خانوادكي,-تعداد-نفرات,-التاريخ-و-ساعت-تسجيل الدخول-و-تسجيل الخروج,-جزييات-صورتحساب-برفضاخت-شده,-الالعنوان-دقيق-اقامتكاه-و-شماره-تماس-ميهمان-و-ميزبان-براي-هر-دو-طرف-إرسال-مي-كرفضد.-توصيه-مي-شود-ميزبان-بيش-از-شروع-سفر-با-ميهمان-تماس-كرفته-و-هماهنكي-هاي-لازم-براي-نحوه-و-الوقت-تحويل-اقامتكاه-به-ايشان-را-به-انجام-برساند-تا-ميهمان-با-خيالي-آسوده-سفر-خود-را-آغاز-نمايد.',
    'عضویت در گیلندملک, ثبت حساب کاربری, و ثبت و انتشار اقامتگاه شما در وبسایت بصورت کاملا رایگان انجام می پذیرد. تنها پس از به اجاره رفتن اقامتگاه, گیلندملک ۱۰٪ از کل مبلغ اجاره بهای تعیین شده توسط میزبان را بعنوان کارمزد خدمات خود کسر نموده و مابقی مبلغ اجاره بها را به حساب بانکی میزبان واریز می کند. با توجه به الزام اداره امور مالیاتی، 0.9 درصد ارزش افزوده هم به صورتحساب میزبان اضافه می شود. لذا مجموع کسورات از صورتحساب 10.9 درصد می‌باشد.' => 'عضويت در كيلندملك, إرسال حساب كاربري, و إرسال و انتشار اقامتكاه شما در وبسايت بصورت كاملا رايكان انجام مي بذيرفض. تنها بس از به إيجار رفتن اقامتكاه, كيلندملك ۱۰٪ از كل مبلغ إيجار بهاي تعيين شده توسط ميزبان را بالعنوان كارمزد خدمات خود كسر نموده و مابقي مبلغ إيجار بها را به حساب بانكي ميزبان واريز مي كند. با توجه به الزام اداره امور مالياتي، 0.9 درصد ارزش افزوده هم به صورتحساب ميزبان اضافه مي شود. لذا مجموع كسورات از صورتحساب 10.9 درصد مي باشد.',
    'عضویت-در-گیلندملک,-ثبت-حساب-کاربری,-و-ثبت-و-انتشار-اقامتگاه-شما-در-وبسایت-بصورت-کاملا-رایگان-انجام-می-پذیرد.-تنها-پس-از-به-اجاره-رفتن-اقامتگاه,-گیلندملک-۱۰٪-از-کل-مبلغ-اجاره-بهای-تعیین-شده-توسط-میزبان-را-بعنوان-کارمزد-خدمات-خود-کسر-نموده-و-مابقی-مبلغ-اجاره-بها-را-به-حساب-بانکی-میزبان-واریز-می-کند.-با-توجه-به-الزام-اداره-امور-مالیاتی،-0.9-درصد-ارزش-افزوده-هم-به-صورتحساب-میزبان-اضافه-می-شود.-لذا-مجموع-کسورات-از-صورتحساب-10.9-درصد-می‌باشد.' => 'عضويت-در-كيلندملك,-إرسال-حساب-كاربري,-و-إرسال-و-انتشار-اقامتكاه-شما-در-وبسايت-بصورت-كاملا-رايكان-انجام-مي-بذيرفض.-تنها-بس-از-به-إيجار-رفتن-اقامتكاه,-كيلندملك-۱۰٪-از-كل-مبلغ-إيجار-بهاي-تعيين-شده-توسط-ميزبان-را-بالعنوان-كارمزد-خدمات-خود-كسر-نموده-و-مابقي-مبلغ-إيجار-بها-را-به-حساب-بانكي-ميزبان-واريز-مي-كند.-با-توجه-به-الزام-اداره-امور-مالياتي،-0.9-درصد-ارزش-افزوده-هم-به-صورتحساب-ميزبان-اضافه-مي-شود.-لذا-مجموع-كسورات-از-صورتحساب-10.9-درصد-مي باشد.',
    'فضای خواب' => 'فضای غرفة نوم',
    'فضای-خواب' => 'فضای خواب',
    'در صورتی که رزرو، بیش از 5 روز کامل از تاریخ ورود لغو گردد؛ 80 درصد مبلغ صورتحساب به میهمان عودت می‌شود. در غیر اینصورت اجاره شب اول بعلاوه 50 درصد شب‌های باقیمانده کسر می‌گردد.' => 'در صورتي كه رزرو، بيش از 5 روز كامل از التاريخ تسجيل الدخول لغو كرفضد؛ 80 درصد مبلغ صورتحساب به ميهمان عودت مي شود. در غير اينصورت إيجار شب اول بعلاوه 50 درصد شب هاي باقيمانده كسر مي كرفضد.',
    'در-صورتی-که-رزرو،-بیش-از-5-روز-کامل-از-تاریخ-ورود-لغو-گردد؛-80-درصد-مبلغ-صورتحساب-به-میهمان-عودت-می‌شود.-در-غیر-اینصورت-اجاره-شب-اول-بعلاوه-50-درصد-شب‌های-باقیمانده-کسر-می‌گردد.' => 'در-صورتي-كه-رزرو،-بيش-از-5-روز-كامل-از-التاريخ-تسجيل الدخول-لغو-كرفضد؛-80-درصد-مبلغ-صورتحساب-به-ميهمان-عودت-مي شود.-در-غير-اينصورت-إيجار-شب-اول-بعلاوه-50-درصد-شب هاي-باقيمانده-كسر-مي كرفضد.',
    'ضمانت تحویل' => 'ضمانت تحويل',
