    'دوست عزیز، تمامی تلاش ما در نوشتن این متن ، استفاده بهتر شما از خدمات گیلند ملک است. به منظور آشنایی هرچه بیشتر حق و حقوق قانونی خود، لطفا موارد زیر را به‌دقت مطالعه کنید..' => 'دوست عزيز، تمامي تلاش ما در نوشتن اين متن ، استفاده بهتر شما از خدمات كيلند ملك است. به منظور آشنايي هرجه بيشتر حق و حقوق قانوني خود، لطفا موارفض زير را به دقت مطالعه كنيد..',
    'دوست-عزیز،-تمامی-تلاش-ما-در-نوشتن-این-متن-،-استفاده-بهتر-شما-از-خدمات-گیلند-ملک-است.-به-منظور-آشنایی-هرچه-بیشتر-حق-و-حقوق-قانونی-خود،-لطفا-موارد-زیر-را-به‌دقت-مطالعه-کنید..' => 'دوست-عزيز،-تمامي-تلاش-ما-در-نوشتن-اين-متن-،-استفاده-بهتر-شما-از-خدمات-كيلند-ملك-است.-به-منظور-آشنايي-هرجه-بيشتر-حق-و-حقوق-قانوني-خود،-لطفا-موارفض-زير-را-به دقت-مطالعه-كنيد..',
    'به تمامی واحدهای اقامتی ثبت شده در گیلند ملک گفته می‌شود.' => 'به تمامي واحدهاي اقامتي إرسال شده در كيلند ملك كفته مي شود.',
    'به-تمامی-واحدهای-اقامتی-ثبت-شده-در-گیلند-ملک-گفته-می‌شود.' => 'به-تمامي-واحدهاي-اقامتي-إرسال-شده-در-كيلند-ملك-كفته-مي شود.',
    'فرد یا افرادی که قصد اقامت در اقامتگاه را دارند و درخواست اقامت خود را از طریق گیلند ملک ثبت می‌کنند.' => 'فرفض يا افرادي كه قصد اقامت در اقامتكاه را دارند و درخواست اقامت خود را از طريق كيلند ملك إرسال مي كنند.',
    'فرد-یا-افرادی-که-قصد-اقامت-در-اقامتگاه-را-دارند-و-درخواست-اقامت-خود-را-از-طریق-گیلند-ملک-ثبت-می‌کنند.' => 'فرفض-يا-افرادي-كه-قصد-اقامت-در-اقامتكاه-را-دارند-و-درخواست-اقامت-خود-را-از-طريق-كيلند-ملك-إرسال-مي كنند.',
    'شخصیتی حقیقی یا حقوقی است که اقامتگاه را به‌ازای درخواست اقامت مهمان از طریق گیلند ملک ، در اختیار ایشان قرار می‌دهد.' => 'شخصيتي حقيقي يا حقوقي است كه اقامتكاه را به ازاي درخواست اقامت مهمان از طريق كيلند ملك ، در اختيار ايشان قرار مي دهد.',
    'شخصیتی-حقیقی-یا-حقوقی-است-که-اقامتگاه-را-به‌ازای-درخواست-اقامت-مهمان-از-طریق-گیلند-ملک-،-در-اختیار-ایشان-قرار-می‌دهد.' => 'شخصيتي-حقيقي-يا-حقوقي-است-كه-اقامتكاه-را-به ازاي-درخواست-اقامت-مهمان-از-طريق-كيلند-ملك-،-در-اختيار-ايشان-قرار-مي دهد.',
    'شخص حقیقی یا حقوقی که صاحب اقامتگاه است.' => 'شخص حقيقي يا حقوقي كه صاحب اقامتكاه است.',
    'شخص-حقیقی-یا-حقوقی-که-صاحب-اقامتگاه-است.' => 'شخص-حقيقي-يا-حقوقي-كه-صاحب-اقامتكاه-است.',
    'شخص حقیقی یا حقوقی که به‌صورت رسمی اجازه بهره‌برداری (اجاره) از اقامتگاه را داشته باشد و یا نماینده قانونی وی باشد.' => 'شخص حقيقي يا حقوقي كه به صورت رسمي اجازه بهره برفضاري (إيجار) از اقامتكاه را داشته باشد و يا نماينده قانوني وي باشد.',
    'شخص-حقیقی-یا-حقوقی-که-به‌صورت-رسمی-اجازه-بهره‌برداری-(اجاره)-از-اقامتگاه-را-داشته-باشد-و-یا-نماینده-قانونی-وی-باشد.' => 'شخص-حقيقي-يا-حقوقي-كه-به صورت-رسمي-اجازه-بهره برفضاري-(إيجار)-از-اقامتكاه-را-داشته-باشد-و-يا-نماينده-قانوني-وي-باشد.',
    'قابل ذکر است: کاربر، میزبان، مالک و نماینده مالک می‌تواند یک نفر باشد.' => 'قابل ذکر است: کاربر، میزبان، المالك و نماینده المالك می‌تواند یک نفر باشد.',
    'قابل-ذکر-است:-کاربر،-میزبان،-مالک-و-نماینده-مالک-می‌تواند-یک-نفر-باشد.' => 'قابل ذکر است: کاربر، میزبان، مالک و نماینده مالک می‌تواند یک نفر باشد.',
    'حسابی که کاربران برای استفاده از خدمات گیلند ملک در آن ایجاد کرده‌اند.' => 'حسابي كه كاربران براي استفاده از خدمات كيلند ملك در آن إنشاء كرفضه اند.',
    'حسابی-که-کاربران-برای-استفاده-از-خدمات-گیلند-ملک-در-آن-ایجاد-کرده‌اند.' => 'حسابي-كه-كاربران-براي-استفاده-از-خدمات-كيلند-ملك-در-آن-إنشاء-كرفضه اند.',
    'مبلغی که مهمان در حساب کاربری خود جهت استفاده از خدمات گیلند ملک دارد.' => 'مبلغي كه مهمان در حساب كاربري خود جهت استفاده از خدمات كيلند ملك دارفض.',
    'مبلغی-که-مهمان-در-حساب-کاربری-خود-جهت-استفاده-از-خدمات-گیلند-ملک-دارد.' => 'مبلغي-كه-مهمان-در-حساب-كاربري-خود-جهت-استفاده-از-خدمات-كيلند-ملك-دارفض.',
    'به معنای تاییدیه رزرو اقامتگاه است و در واقع رسیدی است که پس از رزرو اقامتگاه از طرف گیلند ملک برای مهمان صادر می‌شود و نشان می‌دهد که مهمان هزینه اقامت خود را به‌صورت کامل پرداخت کرده است. این رسید شامل مشخصات اقامتگاه، تاریخ ورود و خروج، نام و شماره تماس مهمانان است.' => 'به معناي تأكيديه رزرو اقامتكاه است و در واقع رسيدي است كه بس از رزرو اقامتكاه از طرف كيلند ملك براي مهمان صادر مي شود و نشان مي دهد كه مهمان هزينه اقامت خود را به صورت كامل برفضاخت كرفضه است. اين رسيد شامل مشخصات اقامتكاه، التاريخ تسجيل الدخول و تسجيل الخروج، الاسم و شماره تماس مهمانان است.',
    'به-معنای-تاییدیه-رزرو-اقامتگاه-است-و-در-واقع-رسیدی-است-که-پس-از-رزرو-اقامتگاه-از-طرف-گیلند-ملک-برای-مهمان-صادر-می‌شود-و-نشان-می‌دهد-که-مهمان-هزینه-اقامت-خود-را-به‌صورت-کامل-پرداخت-کرده-است.-این-رسید-شامل-مشخصات-اقامتگاه،-تاریخ-ورود-و-خروج،-نام-و-شماره-تماس-مهمانان-است.' => 'به-معناي-تأكيديه-رزرو-اقامتكاه-است-و-در-واقع-رسيدي-است-كه-بس-از-رزرو-اقامتكاه-از-طرف-كيلند-ملك-براي-مهمان-صادر-مي شود-و-نشان-مي دهد-كه-مهمان-هزينه-اقامت-خود-را-به صورت-كامل-برفضاخت-كرفضه-است.-اين-رسيد-شامل-مشخصات-اقامتكاه،-التاريخ-تسجيل الدخول-و-تسجيل الخروج،-الاسم-و-شماره-تماس-مهمانان-است.',
    'همانند واچر می باشد اما برای تجربه به عبارت دیگر تاییده رزرو انجام شده برای تجربه، بلیط است.' => 'همانند واجر مي باشد اما براي تجربه به عبارت ديكر تأكيده رزرو انجام شده براي تجربه، بليط است.',
    'همانند-واچر-می-باشد-اما-برای-تجربه-به-عبارت-دیگر-تاییده-رزرو-انجام-شده-برای-تجربه،-بلیط-است.' => 'همانند-واجر-مي-باشد-اما-براي-تجربه-به-عبارت-ديكر-تأكيده-رزرو-انجام-شده-براي-تجربه،-بليط-است.',
    'کلیه اقامتگاه هایی که به‌طور کامل و دربست در اختیار مهمان قرار می‌گیرد. مانند: ویلا، خانه، آپارتمان، کلبه و' => 'كليه اقامتكاه هايي كه به طور كامل و دربست در اختيار مهمان قرار مي كيرفض. مانند: فيلا، خانه، شقة، كلبه و',
    'کلیه-اقامتگاه-هایی-که-به‌طور-کامل-و-دربست-در-اختیار-مهمان-قرار-می‌گیرد.-مانند:-ویلا،-خانه،-آپارتمان،-کلبه-و' => 'كليه-اقامتكاه-هايي-كه-به طور-كامل-و-دربست-در-اختيار-مهمان-قرار-مي كيرفض.-مانند:-فيلا،-خانه،-شقة،-كلبه-و',
    '«تجربه» فعالیت‌هایی هستند که توسط افراد بومی در هر منطقه برنامه‌ریزی و اجرا می‌شوند. این فعالیت‌ها فراتر از تورها و برنامه‌های معمولی هستند که مهمانان را به دنیای منحصر به فردی می‌برند، دنیایی که مهمان به‌خودی خود نمی‌تواند آن را تجربه کند. «تجربه» فرصتی‌ست تا هرکس علائق، مهارت و یا تخصص خود را بدون وابستگی و بدون محدودیت منابع به اشتراک گذارد.' => '«تجربه» نشطيت هايي هستند كه توسط افراد بومي در هر المنطقة برالاسمه ريزي و اجرا مي شوند. اين نشطيت ها فراتر از تورها و برالاسمه هاي معمولي هستند كه مهمانان را به دنياي منحصر به فرفضي مي برند، دنيايي كه مهمان به خودي خود نمي تواند آن را تجربه كند. «تجربه» فرصتي ست تا هركس علائق، مهارت و يا تخصص خود را بدون وابستكي و بدون محدوديت منابع به اشتراك كذارفض.',
    '«تجربه»-فعالیت‌هایی-هستند-که-توسط-افراد-بومی-در-هر-منطقه-برنامه‌ریزی-و-اجرا-می‌شوند.-این-فعالیت‌ها-فراتر-از-تورها-و-برنامه‌های-معمولی-هستند-که-مهمانان-را-به-دنیای-منحصر-به-فردی-می‌برند،-دنیایی-که-مهمان-به‌خودی-خود-نمی‌تواند-آن-را-تجربه-کند.-«تجربه»-فرصتی‌ست-تا-هرکس-علائق،-مهارت-و-یا-تخصص-خود-را-بدون-وابستگی-و-بدون-محدودیت-منابع-به-اشتراک-گذارد.' => '«تجربه»-نشطيت هايي-هستند-كه-توسط-افراد-بومي-در-هر-المنطقة-برالاسمه ريزي-و-اجرا-مي شوند.-اين-نشطيت ها-فراتر-از-تورها-و-برالاسمه هاي-معمولي-هستند-كه-مهمانان-را-به-دنياي-منحصر-به-فرفضي-مي برند،-دنيايي-كه-مهمان-به خودي-خود-نمي تواند-آن-را-تجربه-كند.-«تجربه»-فرصتي ست-تا-هركس-علائق،-مهارت-و-يا-تخصص-خود-را-بدون-وابستكي-و-بدون-محدوديت-منابع-به-اشتراك-كذارفض.',
    'کاربر با ثبت نام در گیلند ملک می‌پذیرد که قوانین و مقررات گیلند ملک را به صورت کامل مطالعه کرده، به مفاد آن آگاه و تمامی موارد آن را پذیرفته است. در صورتی که در آینده در این قوانین و مقررات تغییراتی ایجاد شود، در همین صفحه به‌روزرسانی و منتشر می‌شود و کاربر توافق می‏‌کند که استفاده مستمر از سایت به‌معنی پذیرش هرگونه تغییر است.' => 'كاربر با إرسال الاسم در كيلند ملك مي بذيرفض كه الشروط والأحكام كيلند ملك را به صورت كامل مطالعه كرفضه، به مفاد آن آكاه و تمامي موارفض آن را بذيرفته است. در صورتي كه در آينده در اين الشروط والأحكام تغييراتي إنشاء شود، در همين صفحه به روزرساني و منتشر مي شود و كاربر توافق مي‏ كند كه استفاده مستمر از سايت به معني بذيرش هركونه تغيير است.',
    'کاربر-با-ثبت-نام-در-گیلند-ملک-می‌پذیرد-که-قوانین-و-مقررات-گیلند-ملک-را-به-صورت-کامل-مطالعه-کرده،-به-مفاد-آن-آگاه-و-تمامی-موارد-آن-را-پذیرفته-است.-در-صورتی-که-در-آینده-در-این-قوانین-و-مقررات-تغییراتی-ایجاد-شود،-در-همین-صفحه-به‌روزرسانی-و-منتشر-می‌شود-و-کاربر-توافق-می‏‌کند-که-استفاده-مستمر-از-سایت-به‌معنی-پذیرش-هرگونه-تغییر-است.' => 'كاربر-با-إرسال-الاسم-در-كيلند-ملك-مي بذيرفض-كه-قوانين-و-مقررات-كيلند-ملك-را-به-صورت-كامل-مطالعه-كرفضه،-به-مفاد-آن-آكاه-و-تمامي-موارفض-آن-را-بذيرفته-است.-در-صورتي-كه-در-آينده-در-اين-قوانين-و-مقررات-تغييراتي-إنشاء-شود،-در-همين-صفحه-به روزرساني-و-منتشر-مي شود-و-كاربر-توافق-مي‏ كند-كه-استفاده-مستمر-از-سايت-به معني-بذيرش-هركونه-تغيير-است.',
    'هر فرد تنها می‌تواند یک حساب کاربری به عنوان مهمان، یک حساب کاربری به عنوان میزبان و یا هردو به صورت همزمان در گیلند ملک داشته باشد.' => 'هر فرفض تنها مي تواند يك حساب كاربري به العنوان مهمان، يك حساب كاربري به العنوان ميزبان و يا هرفضو به صورت همالوقت در كيلند ملك داشته باشد.',
    'هر-فرد-تنها-می‌تواند-یک-حساب-کاربری-به-عنوان-مهمان،-یک-حساب-کاربری-به-عنوان-میزبان-و-یا-هردو-به-صورت-همزمان-در-گیلند-ملک-داشته-باشد.' => 'هر-فرفض-تنها-مي تواند-يك-حساب-كاربري-به-العنوان-مهمان،-يك-حساب-كاربري-به-العنوان-ميزبان-و-يا-هرفضو-به-صورت-همالوقت-در-كيلند-ملك-داشته-باشد.',
    'مسئولیت تمامی فعالیت‌هایی که از طریق حساب کاربری اشخاص در گیلند ملک انجام می‌شود به عهده کاربر است.' => 'مسئوليت تمامي نشطيت هايي كه از طريق حساب كاربري اشخاص در كيلند ملك انجام مي شود به عهده كاربر است.',
    'مسئولیت-تمامی-فعالیت‌هایی-که-از-طریق-حساب-کاربری-اشخاص-در-گیلند-ملک-انجام-می‌شود-به-عهده-کاربر-است.' => 'مسئوليت-تمامي-نشطيت هايي-كه-از-طريق-حساب-كاربري-اشخاص-در-كيلند-ملك-انجام-مي شود-به-عهده-كاربر-است.',
    'مسئولیت حفظ امنیت اطلاعات حساب کاربری از جمله نام کاربری و رمز عبور به عهده کاربر است. در صورت مفقود یا سرقت اطلاعات حساب کاربری، کاربر موظف است در اسرع وقت موضوع را به اطلاع کارشناسان گیلند ملک برساند. بدیهی است تا زمانی که اطلاع‌رسانی به گیلند ملک انجام نشده است مسئولیت همه فعالیت‌هایی که از طریق حساب کاربری مذکور انجام شده و می‌شود به عهده کاربر خواهد بود.' => 'مسئوليت حفظ امنيت المعلومات حساب كاربري از جمله الاسم كاربري و كلمة المرور به عهده كاربر است. در صورت مفقود يا سرقت المعلومات حساب كاربري، كاربر موظف است در اسرع وقت موضوع را به اطلاع خبيران كيلند ملك برساند. بديهي است تا الوقتي كه اطلاع رساني به كيلند ملك انجام نشده است مسئوليت همه نشطيت هايي كه از طريق حساب كاربري مذكور انجام شده و مي شود به عهده كاربر خواهد بود.',
    'مسئولیت-حفظ-امنیت-اطلاعات-حساب-کاربری-از-جمله-نام-کاربری-و-رمز-عبور-به-عهده-کاربر-است.-در-صورت-مفقود-یا-سرقت-اطلاعات-حساب-کاربری،-کاربر-موظف-است-در-اسرع-وقت-موضوع-را-به-اطلاع-کارشناسان-گیلند-ملک-برساند.-بدیهی-است-تا-زمانی-که-اطلاع‌رسانی-به-گیلند-ملک-انجام-نشده-است-مسئولیت-همه-فعالیت‌هایی-که-از-طریق-حساب-کاربری-مذکور-انجام-شده-و-می‌شود-به-عهده-کاربر-خواهد-بود.' => 'مسئوليت-حفظ-امنيت-المعلومات-حساب-كاربري-از-جمله-الاسم-كاربري-و-رمز-عبور-به-عهده-كاربر-است.-در-صورت-مفقود-يا-سرقت-المعلومات-حساب-كاربري،-كاربر-موظف-است-در-اسرع-وقت-موضوع-را-به-اطلاع-خبيران-كيلند-ملك-برساند.-بديهي-است-تا-الوقتي-كه-اطلاع رساني-به-كيلند-ملك-انجام-نشده-است-مسئوليت-همه-نشطيت هايي-كه-از-طريق-حساب-كاربري-مذكور-انجام-شده-و-مي شود-به-عهده-كاربر-خواهد-بود.',
    'در برخی شرایط ممکن است برای استفاده از خدمات، از کاربر درخواست احراز هویت شود، در چنین شرایطی اگر کاربر اطلاعات کافی را در اختیار گیلند ملک قرار ندهد، گیلند ملک می‌تواند حساب کاربری وی را مسدود کرده و از ارایه خدمات به وی خودداری کند.' => 'در برخي شرايط ممكن است براي استفاده از خدمات، از كاربر درخواست احراز هويت شود، در جنين شرايطي اكر كاربر المعلومات كافي را در اختيار كيلند ملك قرار ندهد، كيلند ملك مي تواند حساب كاربري وي را مسدود كرفضه و از ارايه خدمات به وي خودداري كند.',
    'در-برخی-شرایط-ممکن-است-برای-استفاده-از-خدمات،-از-کاربر-درخواست-احراز-هویت-شود،-در-چنین-شرایطی-اگر-کاربر-اطلاعات-کافی-را-در-اختیار-گیلند-ملک-قرار-ندهد،-گیلند-ملک-می‌تواند-حساب-کاربری-وی-را-مسدود-کرده-و-از-ارایه-خدمات-به-وی-خودداری-کند.' => 'در-برخي-شرايط-ممكن-است-براي-استفاده-از-خدمات،-از-كاربر-درخواست-احراز-هويت-شود،-در-جنين-شرايطي-اكر-كاربر-المعلومات-كافي-را-در-اختيار-كيلند-ملك-قرار-ندهد،-كيلند-ملك-مي تواند-حساب-كاربري-وي-را-مسدود-كرفضه-و-از-ارايه-خدمات-به-وي-خودداري-كند.',
    'کاربر می‌پذیرد که گیلند ملک ارایه دهنده خدمات اقامتی نیست و تنها یک بستر نرم‌افزاری برای ارتباط میان میزبانان و مهمانان جهت توافق به انجام یک اقامت است.' => 'كاربر مي بذيرفض كه كيلند ملك ارايه دهنده خدمات اقامتي نيست و تنها يك بستر نرم افزاري براي ارتباط ميان ميزبانان و مهمانان جهت توافق به انجام يك اقامت است.',
    'کاربر-می‌پذیرد-که-گیلند-ملک-ارایه-دهنده-خدمات-اقامتی-نیست-و-تنها-یک-بستر-نرم‌افزاری-برای-ارتباط-میان-میزبانان-و-مهمانان-جهت-توافق-به-انجام-یک-اقامت-است.' => 'كاربر-مي بذيرفض-كه-كيلند-ملك-ارايه-دهنده-خدمات-اقامتي-نيست-و-تنها-يك-بستر-نرم افزاري-براي-ارتباط-ميان-ميزبانان-و-مهمانان-جهت-توافق-به-انجام-يك-اقامت-است.',
    'چنانچه گیلند ملک به هر دلیل به این نتیجه برسد که حضور یک کاربر (میزبان/مهمان) ممکن است برای مجموعه یا سایر کاربران مطلوب نباشد و یا موجب بروز مشکل شود، حق حذف دسترسی کاربر مذکور به گیلند ملک را دارد.' => 'جنانجه كيلند ملك به هر دليل به اين نتيجة برسد كه حضور يك كاربر (ميزبان/مهمان) ممكن است براي مجموعه يا ساير كاربران مطلوب نباشد و يا موجب بروز مشكل شود، حق حذف دسترسي كاربر مذكور به كيلند ملك را دارفض.',
    'چنانچه-گیلند-ملک-به-هر-دلیل-به-این-نتیجه-برسد-که-حضور-یک-کاربر-(میزبان/مهمان)-ممکن-است-برای-مجموعه-یا-سایر-کاربران-مطلوب-نباشد-و-یا-موجب-بروز-مشکل-شود،-حق-حذف-دسترسی-کاربر-مذکور-به-گیلند-ملک-را-دارد.' => 'جنانجه-كيلند-ملك-به-هر-دليل-به-اين-نتيجة-برسد-كه-حضور-يك-كاربر-(ميزبان/مهمان)-ممكن-است-براي-مجموعه-يا-ساير-كاربران-مطلوب-نباشد-و-يا-موجب-بروز-مشكل-شود،-حق-حذف-دسترسي-كاربر-مذكور-به-كيلند-ملك-را-دارفض.',
    'کلیه فرآیند های خرید در وب سایت منطبق با قوانین جمهوری اسلامی ایران، قانون تجارت الکترونیک و قانون حمایت از حقوق مصرف کننده است و متعاقبا کاربر موظف به رعایت قوانین و مقررات وب سایت در هنگام خرید است.' => 'كليه فرآيند هاي شراء در وب سايت منطبق با قوانين جمهوري اسلامي ايران، قانون تجارت الكترونيك و قانون حمايت از حقوق مصرف كننده است و متعاقبا كاربر موظف به رعايت الشروط والأحكام وب سايت در هنكام شراء است.',
    'کلیه-فرآیند-های-خرید-در-وب-سایت-منطبق-با-قوانین-جمهوری-اسلامی-ایران،-قانون-تجارت-الکترونیک-و-قانون-حمایت-از-حقوق-مصرف-کننده-است-و-متعاقبا-کاربر-موظف-به-رعایت-قوانین-و-مقررات-وب-سایت-در-هنگام-خرید-است.' => 'كليه-فرآيند-هاي-شراء-در-وب-سايت-منطبق-با-قوانين-جمهوري-اسلامي-ايران،-قانون-تجارت-الكترونيك-و-قانون-حمايت-از-حقوق-مصرف-كننده-است-و-متعاقبا-كاربر-موظف-به-رعايت-قوانين-و-مقررات-وب-سايت-در-هنكام-شراء-است.',
    'گیلند ملک می تواند در صورت افزودن قابلیت ها و خدمات جدید و یا در جهت بهبود عملکرد، اقدام به به روز رسانی ضوابط و مقررات وب سایت نماید.' => 'كيلند ملك مي تواند در صورت افزودن قابليت ها و خدمات جديد و يا در جهت بهبود عملكرفض، اقدام به به روز رساني ضوابط و مقررات وب سايت نمايد.',
    'گیلند-ملک-می-تواند-در-صورت-افزودن-قابلیت-ها-و-خدمات-جدید-و-یا-در-جهت-بهبود-عملکرد،-اقدام-به-به-روز-رسانی-ضوابط-و-مقررات-وب-سایت-نماید.' => 'كيلند-ملك-مي-تواند-در-صورت-افزودن-قابليت-ها-و-خدمات-جديد-و-يا-در-جهت-بهبود-عملكرفض،-اقدام-به-به-روز-رساني-ضوابط-و-مقررات-وب-سايت-نمايد.',
    'گیلند ملک تنها یک بستر ارتباطی میان میزبان و مهمان است و به عنوان مجری تجربه یا میزبان اقامتگاه و هتل محسوب نمی گردد. در گیلند ملک، میزبان تجربه و یا اقامتگاه خود را معرفی می نماید و مهمان نیز با آگاهی نسبت به فعالیت پلتفرم گیلند ملک اقدام به رزرو هتل، اقامتگاه و تجربه و پرداخت به صورت آنلاین می نماید. گیلند ملک در جهت بهبود ارایه خدمات خود نهایت تلاش خود را می نماید.' => 'كيلند ملك تنها يك بستر ارتباطي ميان ميزبان و مهمان است و به العنوان مجري تجربه يا ميزبان اقامتكاه و هتل محسوب نمي كرفضد. در كيلند ملك، ميزبان تجربه و يا اقامتكاه خود را معرفي مي نمايد و مهمان نيز با آكاهي نسبت به نشطيت بلتفرم كيلند ملك اقدام به رزرو هتل، اقامتكاه و تجربه و برفضاخت به صورت آنلاين مي نمايد. كيلند ملك در جهت بهبود ارايه خدمات خود نهايت تلاش خود را مي نمايد.',
    'گیلند-ملک-تنها-یک-بستر-ارتباطی-میان-میزبان-و-مهمان-است-و-به-عنوان-مجری-تجربه-یا-میزبان-اقامتگاه-و-هتل-محسوب-نمی-گردد.-در-گیلند-ملک،-میزبان-تجربه-و-یا-اقامتگاه-خود-را-معرفی-می-نماید-و-مهمان-نیز-با-آگاهی-نسبت-به-فعالیت-پلتفرم-گیلند-ملک-اقدام-به-رزرو-هتل،-اقامتگاه-و-تجربه-و-پرداخت-به-صورت-آنلاین-می-نماید.-گیلند-ملک-در-جهت-بهبود-ارایه-خدمات-خود-نهایت-تلاش-خود-را-می-نماید.' => 'كيلند-ملك-تنها-يك-بستر-ارتباطي-ميان-ميزبان-و-مهمان-است-و-به-العنوان-مجري-تجربه-يا-ميزبان-اقامتكاه-و-هتل-محسوب-نمي-كرفضد.-در-كيلند-ملك،-ميزبان-تجربه-و-يا-اقامتكاه-خود-را-معرفي-مي-نمايد-و-مهمان-نيز-با-آكاهي-نسبت-به-نشطيت-بلتفرم-كيلند-ملك-اقدام-به-رزرو-هتل،-اقامتكاه-و-تجربه-و-برفضاخت-به-صورت-آنلاين-مي-نمايد.-كيلند-ملك-در-جهت-بهبود-ارايه-خدمات-خود-نهايت-تلاش-خود-را-مي-نمايد.',
    'اطلاعات هتل‌های ارایه شده در گیلند ملک ، به‌صورت مستقیم از منابع رسمی(هتل ها، مراکز اقامتی و …) دریافت شده است و اطلاعات سایر اقامتگاه‌ها توسط مالکان آن در گیلند ملک درج شده است. به‌علت تغییرات دوره‌ای این اطلاعات، تأیید صحت آنها برعهده همان منابع است. گیلند ملک تلاش می‌کند تا این تغییرات را در کمترین زمان ممکن به‌روزرسانی کند.' => 'المعلومات هتل هاي ارايه شده در كيلند ملك ، به صورت مستقيم از منابع رسمي(هتل ها، مراكز اقامتي و …) استلام شده است و المعلومات ساير اقامتكاه ها توسط المالكان آن در كيلند ملك درج شده است. به علت تغييرات دوره اي اين المعلومات، تأييد صحت آنها برعهده همان منابع است. كيلند ملك تلاش مي كند تا اين تغييرات را در كمترين الوقت ممكن به روزرساني كند.',
    'اطلاعات-هتل‌های-ارایه-شده-در-گیلند-ملک-،-به‌صورت-مستقیم-از-منابع-رسمی(هتل-ها،-مراکز-اقامتی-و-…)-دریافت-شده-است-و-اطلاعات-سایر-اقامتگاه‌ها-توسط-مالکان-آن-در-گیلند-ملک-درج-شده-است.-به‌علت-تغییرات-دوره‌ای-این-اطلاعات،-تأیید-صحت-آنها-برعهده-همان-منابع-است.-گیلند-ملک-تلاش-می‌کند-تا-این-تغییرات-را-در-کمترین-زمان-ممکن-به‌روزرسانی-کند.' => 'المعلومات-هتل هاي-ارايه-شده-در-كيلند-ملك-،-به صورت-مستقيم-از-منابع-رسمي(هتل-ها،-مراكز-اقامتي-و-…)-استلام-شده-است-و-المعلومات-ساير-اقامتكاه ها-توسط-المالكان-آن-در-كيلند-ملك-درج-شده-است.-به علت-تغييرات-دوره اي-اين-المعلومات،-تأييد-صحت-آنها-برعهده-همان-منابع-است.-كيلند-ملك-تلاش-مي كند-تا-اين-تغييرات-را-در-كمترين-الوقت-ممكن-به روزرساني-كند.',
    'اگر مالکیت هتل‌ها و سایر اقامتگاه‌ها با گیلند ملک بود، مطمئنا تمامی خدمات اعلام شده از طرف مراکز اقامتی و هتل را از لحاظ کیفیت و صحت تضمین می‌کرد، اما گیلند ملک صرفا به عنوان یک بستر الکترونیک نسبت به اعلام خدمات اقدام می نماید و می کوشد کلیه اطلاعاتی را که توسط میزبان و یا هتل اعلام می گردد، اعتبار سنجی و یا راستی آزمایی نماید. اطلاعات هتل، اقامتگاه در وب سایت گیلند ملک شامل وضعیت ظرفیت اتاق هتل یا اقامتگاه ، نقشه هتل ، قیمتهای به روز شده ، تصاویر هتل ها، عوارض و مالیات، حق سرویس، وعده های غذایی، امکانات هتل و ترانسفر فرودگاهی و… است حال ممکن است هتل ها و سایر اقامتگاه‌ها در مواردی در ارایه خدمات اعلامی کوتاهی کنند و یا کلیه یا برخی از اطلاعات مندرج در صفحه هتل، اقامتگاه یا تجربه گیلند ملک مطابق با اطلاعاتی که در زمان معرفی آن محصولات اعلام شده، نباشد. در این صورت مسئولیت ناشی از هرگونه نقض یا مغایرت ، با مالک هتل، اقامتگاه یا تجربه است در این‌صورت ما از شما می‌خواهیم تا این قبیل مشکلات را با مجموعه گیلند ملک درمیان بگذارید تا ضمن پیگیری، بازخورد آن را در اختیار سایر مسافرین قرار داده و در صورت لزوم، سرویس مذکور را از محصولات گیلند ملک حذف گردد.' => 'اكر المالكيت هتل ها و ساير اقامتكاه ها با كيلند ملك بود، مطمئنا تمامي خدمات اعلام شده از طرف مراكز اقامتي و هتل را از لحاظ كيفيت و صحت تضمين مي كرفض، اما كيلند ملك صرفا به العنوان يك بستر الكترونيك نسبت به اعلام خدمات اقدام مي نمايد و مي كوشد كليه المعلوماتي را كه توسط ميزبان و يا هتل اعلام مي كرفضد، اعتبار سنجي و يا راستي آزمايي نمايد. المعلومات هتل، اقامتكاه در وب سايت كيلند ملك شامل الحالة ظرفيت غرفة هتل يا اقامتكاه ، خريطة هتل ، السعرهاي به روز شده ، تصاوير هتل ها، عوارض و ماليات، حق سرويس، وعده هاي غذايي، امكانات هتل و ترانسفر فرودكاهي و… است حال ممكن است هتل ها و ساير اقامتكاه ها در موارفضي در ارايه خدمات اعلامي كوتاهي كنند و يا كليه يا برخي از المعلومات مندرج در صفحه هتل، اقامتكاه يا تجربه كيلند ملك مطابق با المعلوماتي كه در الوقت معرفي آن محصولات اعلام شده، نباشد. در اين صورت مسئوليت ناشي از هركونه نقض يا مغايرت ، با المالك هتل، اقامتكاه يا تجربه است در اين صورت ما از شما مي خواهيم تا اين قبيل مشكلات را با مجموعه كيلند ملك درميان بكذاريد تا ضمن بيكيري، بازخورفض آن را در اختيار ساير مسافرين قرار داده و در صورت لزوم، سرويس مذكور را از محصولات كيلند ملك حذف كرفضد.',
    'اگر-مالکیت-هتل‌ها-و-سایر-اقامتگاه‌ها-با-گیلند-ملک-بود،-مطمئنا-تمامی-خدمات-اعلام-شده-از-طرف-مراکز-اقامتی-و-هتل-را-از-لحاظ-کیفیت-و-صحت-تضمین-می‌کرد،-اما-گیلند-ملک-صرفا-به-عنوان-یک-بستر-الکترونیک-نسبت-به-اعلام-خدمات-اقدام-می-نماید-و-می-کوشد-کلیه-اطلاعاتی-را-که-توسط-میزبان-و-یا-هتل-اعلام-می-گردد،-اعتبار-سنجی-و-یا-راستی-آزمایی-نماید.-اطلاعات-هتل،-اقامتگاه-در-وب-سایت-گیلند-ملک-شامل-وضعیت-ظرفیت-اتاق-هتل-یا-اقامتگاه-،-نقشه-هتل-،-قیمتهای-به-روز-شده-،-تصاویر-هتل-ها،-عوارض-و-مالیات،-حق-سرویس،-وعده-های-غذایی،-امکانات-هتل-و-ترانسفر-فرودگاهی-و…-است-حال-ممکن-است-هتل-ها-و-سایر-اقامتگاه‌ها-در-مواردی-در-ارایه-خدمات-اعلامی-کوتاهی-کنند-و-یا-کلیه-یا-برخی-از-اطلاعات-مندرج-در-صفحه-هتل،-اقامتگاه-یا-تجربه-گیلند-ملک-مطابق-با-اطلاعاتی-که-در-زمان-معرفی-آن-محصولات-اعلام-شده،-نباشد.-در-این-صورت-مسئولیت-ناشی-از-هرگونه-نقض-یا-مغایرت-،-با-مالک-هتل،-اقامتگاه-یا-تجربه-است-در-این‌صورت-ما-از-شما-می‌خواهیم-تا-این-قبیل-مشکلات-را-با-مجموعه-گیلند-ملک-درمیان-بگذارید-تا-ضمن-پیگیری،-بازخورد-آن-را-در-اختیار-سایر-مسافرین-قرار-داده-و-در-صورت-لزوم،-سرویس-مذکور-را-از-محصولات-گیلند-ملک-حذف-گردد.' => 'اكر-المالكيت-هتل ها-و-ساير-اقامتكاه ها-با-كيلند-ملك-بود،-مطمئنا-تمامي-خدمات-اعلام-شده-از-طرف-مراكز-اقامتي-و-هتل-را-از-لحاظ-كيفيت-و-صحت-تضمين-مي كرفض،-اما-كيلند-ملك-صرفا-به-العنوان-يك-بستر-الكترونيك-نسبت-به-اعلام-خدمات-اقدام-مي-نمايد-و-مي-كوشد-كليه-المعلوماتي-را-كه-توسط-ميزبان-و-يا-هتل-اعلام-مي-كرفضد،-اعتبار-سنجي-و-يا-راستي-آزمايي-نمايد.-المعلومات-هتل،-اقامتكاه-در-وب-سايت-كيلند-ملك-شامل-الحالة-ظرفيت-غرفة-هتل-يا-اقامتكاه-،-خريطة-هتل-،-السعرهاي-به-روز-شده-،-تصاوير-هتل-ها،-عوارض-و-ماليات،-حق-سرويس،-وعده-هاي-غذايي،-امكانات-هتل-و-ترانسفر-فرودكاهي-و…-است-حال-ممكن-است-هتل-ها-و-ساير-اقامتكاه ها-در-موارفضي-در-ارايه-خدمات-اعلامي-كوتاهي-كنند-و-يا-كليه-يا-برخي-از-المعلومات-مندرج-در-صفحه-هتل،-اقامتكاه-يا-تجربه-كيلند-ملك-مطابق-با-المعلوماتي-كه-در-الوقت-معرفي-آن-محصولات-اعلام-شده،-نباشد.-در-اين-صورت-مسئوليت-ناشي-از-هركونه-نقض-يا-مغايرت-،-با-المالك-هتل،-اقامتكاه-يا-تجربه-است-در-اين صورت-ما-از-شما-مي خواهيم-تا-اين-قبيل-مشكلات-را-با-مجموعه-كيلند-ملك-درميان-بكذاريد-تا-ضمن-بيكيري،-بازخورفض-آن-را-در-اختيار-ساير-مسافرين-قرار-داده-و-در-صورت-لزوم،-سرويس-مذكور-را-از-محصولات-كيلند-ملك-حذف-كرفضد.',
    'در روزهای پر مسافرِ سال، هتل ها و سایر اقامتگاه‌ها قوانین خاصی اجرا داشته باشند. از جمله ‎دارند تا بتوانند مدیریت بهتری در پذیرش و خدمات نا محدود به این قوانین می‌توان به عدم پذیرش کنسلی و در برخی هتل ها عدم ارایه سرویس‌های اتاق به‌صورت تخت اضافه اشاره کرد، گیلند ملک در این خصوص مسئولیتی نخواهد داشت.' => 'در روزهاي بر مسافرِ سال، هتل ها و ساير اقامتكاه ها قوانين خاصي اجرا داشته باشند. از جمله ‎دارند تا بتوانند مديريت بهتري در بذيرش و خدمات نا محدود به اين قوانين مي توان به عدم بذيرش كنسلي و در برخي هتل ها عدم ارايه سرويس هاي غرفة به صورت تخت اضافه اشاره كرفض، كيلند ملك در اين خصوص مسئوليتي نخواهد داشت.',
    'در-روزهای-پر-مسافرِ-سال،-هتل-ها-و-سایر-اقامتگاه‌ها-قوانین-خاصی-اجرا-داشته-باشند.-از-جمله-‎دارند-تا-بتوانند-مدیریت-بهتری-در-پذیرش-و-خدمات-نا-محدود-به-این-قوانین-می‌توان-به-عدم-پذیرش-کنسلی-و-در-برخی-هتل-ها-عدم-ارایه-سرویس‌های-اتاق-به‌صورت-تخت-اضافه-اشاره-کرد،-گیلند-ملک-در-این-خصوص-مسئولیتی-نخواهد-داشت.' => 'در-روزهاي-بر-مسافرِ-سال،-هتل-ها-و-ساير-اقامتكاه ها-قوانين-خاصي-اجرا-داشته-باشند.-از-جمله-‎دارند-تا-بتوانند-مديريت-بهتري-در-بذيرش-و-خدمات-نا-محدود-به-اين-قوانين-مي توان-به-عدم-بذيرش-كنسلي-و-در-برخي-هتل-ها-عدم-ارايه-سرويس هاي-غرفة-به صورت-تخت-اضافه-اشاره-كرفض،-كيلند-ملك-در-اين-خصوص-مسئوليتي-نخواهد-داشت.',
    'احراز هویت مهمان و شرایط محرمیت، از سوی اقامتگاه یا هتل و بر اساس ارزش ها و شئونات اسلامی است؛ اقامتگاه‌ها یا هتل ها این اختیار را خواهند داشت در صورت عدم احراز شرایط محرمیت از ورود مسافرین به اقامتگاه ممانعت کرده و مطابق قوانین کنسلی عمل می‌کنند.' => 'احراز هويت مهمان و شرايط محرميت، از سوي اقامتكاه يا هتل و بر اساس ارزش ها و شئونات اسلامي است؛ اقامتكاه ها يا هتل ها اين اختيار را خواهند داشت در صورت عدم احراز شرايط محرميت از تسجيل الدخول مسافرين به اقامتكاه ممانعت كرفضه و مطابق قوانين كنسلي عمل مي كنند.',
    'احراز-هویت-مهمان-و-شرایط-محرمیت،-از-سوی-اقامتگاه-یا-هتل-و-بر-اساس-ارزش-ها-و-شئونات-اسلامی-است؛-اقامتگاه‌ها-یا-هتل-ها-این-اختیار-را-خواهند-داشت-در-صورت-عدم-احراز-شرایط-محرمیت-از-ورود-مسافرین-به-اقامتگاه-ممانعت-کرده-و-مطابق-قوانین-کنسلی-عمل-می‌کنند.' => 'احراز-هويت-مهمان-و-شرايط-محرميت،-از-سوي-اقامتكاه-يا-هتل-و-بر-اساس-ارزش-ها-و-شئونات-اسلامي-است؛-اقامتكاه ها-يا-هتل-ها-اين-اختيار-را-خواهند-داشت-در-صورت-عدم-احراز-شرايط-محرميت-از-تسجيل الدخول-مسافرين-به-اقامتكاه-ممانعت-كرفضه-و-مطابق-قوانين-كنسلي-عمل-مي كنند.',
    'هنگامی که شما رزرو خود را کنسل می‌کنید، این ریسک برای اقامتگاه وجود دارد تا نتواند در زمان باقی مانده، واحد اقامتی خود را به فروش رساند. بنابراین منطقی است تا مبلغی را به‌عنوان جریمه‌ی استرداد از مهمان دریافت کند. سیاست صاحبان اقامتگاه‌ها در میزان این جریمه متفاوت است، از این‌رو قوانین کنسلی هر اقامتگاه، در صفحه آن اقامتگاه درج شده است و ممکن است با اقامتگاه دیگر متفاوت باشد. حتی ممکن است این قوانین در تمام سال یکسان نباشد. اطمینان داشته باشید ما تلاش می‌کنیم در صورت انصراف از رزرو، کمترین هزینه را بپردازید؛ برای همین از شما می‌خواهیم به محض انصراف ، گیلند ملک را از تصمیم خود مطلع کنید تا جریمه کمتری شوید. وجه مسترد شده به شماره حسابی که با آن از گیلند ملک خرید کرده اید، واریز خواهد شد.' => 'هنكامي كه شما رزرو خود را كنسل مي كنيد، اين ريسك براي اقامتكاه وجود دارفض تا نتواند در الوقت باقي مانده، واحد اقامتي خود را به بيع رساند. بنابراين منطقي است تا مبلغي را به العنوان جريمه ي استرفضاد از مهمان استلام كند. سياست صاحبان اقامتكاه ها در ميزان اين جريمه متفاوت است، از اين رو قوانين كنسلي هر اقامتكاه، در صفحه آن اقامتكاه درج شده است و ممكن است با اقامتكاه ديكر متفاوت باشد. حتي ممكن است اين قوانين در تمام سال يكسان نباشد. اطمينان داشته باشيد ما تلاش مي كنيم در صورت إلغاء از رزرو، كمترين هزينه را ببرفضازيد؛ براي همين از شما مي خواهيم به محض إلغاء ، كيلند ملك را از تصميم خود مطلع كنيد تا جريمه كمتري شويد. وجه مسترفض شده به شماره حسابي كه با آن از كيلند ملك شراء كرفضه ايد، واريز خواهد شد.',
    'هنگامی-که-شما-رزرو-خود-را-کنسل-می‌کنید،-این-ریسک-برای-اقامتگاه-وجود-دارد-تا-نتواند-در-زمان-باقی-مانده،-واحد-اقامتی-خود-را-به-فروش-رساند.-بنابراین-منطقی-است-تا-مبلغی-را-به‌عنوان-جریمه‌ی-استرداد-از-مهمان-دریافت-کند.-سیاست-صاحبان-اقامتگاه‌ها-در-میزان-این-جریمه-متفاوت-است،-از-این‌رو-قوانین-کنسلی-هر-اقامتگاه،-در-صفحه-آن-اقامتگاه-درج-شده-است-و-ممکن-است-با-اقامتگاه-دیگر-متفاوت-باشد.-حتی-ممکن-است-این-قوانین-در-تمام-سال-یکسان-نباشد.-اطمینان-داشته-باشید-ما-تلاش-می‌کنیم-در-صورت-انصراف-از-رزرو،-کمترین-هزینه-را-بپردازید؛-برای-همین-از-شما-می‌خواهیم-به-محض-انصراف-،-گیلند-ملک-را-از-تصمیم-خود-مطلع-کنید-تا-جریمه-کمتری-شوید.-وجه-مسترد-شده-به-شماره-حسابی-که-با-آن-از-گیلند-ملک-خرید-کرده-اید،-واریز-خواهد-شد.' => 'هنكامي-كه-شما-رزرو-خود-را-كنسل-مي كنيد،-اين-ريسك-براي-اقامتكاه-وجود-دارفض-تا-نتواند-در-الوقت-باقي-مانده،-واحد-اقامتي-خود-را-به-بيع-رساند.-بنابراين-منطقي-است-تا-مبلغي-را-به العنوان-جريمه ي-استرفضاد-از-مهمان-استلام-كند.-سياست-صاحبان-اقامتكاه ها-در-ميزان-اين-جريمه-متفاوت-است،-از-اين رو-قوانين-كنسلي-هر-اقامتكاه،-در-صفحه-آن-اقامتكاه-درج-شده-است-و-ممكن-است-با-اقامتكاه-ديكر-متفاوت-باشد.-حتي-ممكن-است-اين-قوانين-در-تمام-سال-يكسان-نباشد.-اطمينان-داشته-باشيد-ما-تلاش-مي كنيم-در-صورت-إلغاء-از-رزرو،-كمترين-هزينه-را-ببرفضازيد؛-براي-همين-از-شما-مي خواهيم-به-محض-إلغاء-،-كيلند-ملك-را-از-تصميم-خود-مطلع-كنيد-تا-جريمه-كمتري-شويد.-وجه-مسترفض-شده-به-شماره-حسابي-كه-با-آن-از-كيلند-ملك-شراء-كرفضه-ايد،-واريز-خواهد-شد.',
    'برای پذیرش بانوان که به‌صورت تنها قصد اقامت دارند قانوناً مشکلی وجود ندارد .‎ و با نامه رسمی شرکت ها و سازمان‌ها مأموریت و یا شرکت در همایش‌ها، اقامت به‌راحتی میسر می‌شود. اگر می‌خواهید مطمئن سفر کنید و خیالتان راحت باشد با ما تماس بگیرید.' => 'براي بذيرش بانوان كه به صورت تنها قصد اقامت دارند قانوناً مشكلي وجود ندارفض .‎ و با الاسمه رسمي شركت ها و ساالوقت ها مأموريت و يا شركت در همايش ها، اقامت به راحتي ميسر مي شود. اكر مي خواهيد مطمئن سفر كنيد و خيالتان راحت باشد با ما تماس بكيريد.',
    'برای-پذیرش-بانوان-که-به‌صورت-تنها-قصد-اقامت-دارند-قانوناً-مشکلی-وجود-ندارد-.‎-و-با-نامه-رسمی-شرکت-ها-و-سازمان‌ها-مأموریت-و-یا-شرکت-در-همایش‌ها،-اقامت-به‌راحتی-میسر-می‌شود.-اگر-می‌خواهید-مطمئن-سفر-کنید-و-خیالتان-راحت-باشد-با-ما-تماس-بگیرید.' => 'براي-بذيرش-بانوان-كه-به صورت-تنها-قصد-اقامت-دارند-قانوناً-مشكلي-وجود-ندارفض-.‎-و-با-الاسمه-رسمي-شركت-ها-و-ساالوقت ها-مأموريت-و-يا-شركت-در-همايش ها،-اقامت-به راحتي-ميسر-مي شود.-اكر-مي خواهيد-مطمئن-سفر-كنيد-و-خيالتان-راحت-باشد-با-ما-تماس-بكيريد.',
    'مهمان می‌پذیرد رزرو هر اقامتگاه یا هتل به معنای تأیید مقررات آن اقامتگاه یا هتل از سوی ایشان است و می بایست به ضوابط آن پایبند باشد.' => 'مهمان مي بذيرفض رزرو هر اقامتكاه يا هتل به معناي تأييد مقررات آن اقامتكاه يا هتل از سوي ايشان است و مي بايست به ضوابط آن بايبند باشد.',
    'مهمان-می‌پذیرد-رزرو-هر-اقامتگاه-یا-هتل-به-معنای-تأیید-مقررات-آن-اقامتگاه-یا-هتل-از-سوی-ایشان-است-و-می-بایست-به-ضوابط-آن-پایبند-باشد.' => 'مهمان-مي بذيرفض-رزرو-هر-اقامتكاه-يا-هتل-به-معناي-تأييد-مقررات-آن-اقامتكاه-يا-هتل-از-سوي-ايشان-است-و-مي-بايست-به-ضوابط-آن-بايبند-باشد.',
    'زمان ورود و خروج هر اقامتگاه در صفحه آن ذکر شده است. میزبان و مهمان متعهد به رعایت این زمانبندی هستند.' => 'الوقت تسجيل الدخول و تسجيل الخروج هر اقامتكاه در صفحه آن ذكر شده است. ميزبان و مهمان متعهد به رعايت اين الوقتبندي هستند.',
    'زمان-ورود-و-خروج-هر-اقامتگاه-در-صفحه-آن-ذکر-شده-است.-میزبان-و-مهمان-متعهد-به-رعایت-این-زمانبندی-هستند.' => 'الوقت-تسجيل الدخول-و-تسجيل الخروج-هر-اقامتكاه-در-صفحه-آن-ذكر-شده-است.-ميزبان-و-مهمان-متعهد-به-رعايت-اين-الوقتبندي-هستند.',
    'مهمان می‌پذیرد چنانچه به واسطه اقامت ایشان، خسارتی به محل اقامت و وسایل آن وارد شود، مسئولیت تأمین هزینه‌های مربوط به آن بر عهده ایشان خواهد بود.' => 'مهمان مي بذيرفض جنانجه به واسطه اقامت ايشان، خسارتي به محل اقامت و وسايل آن وارفض شود، مسئوليت تأمين هزينه هاي مربوط به آن بر عهده ايشان خواهد بود.',
    'مهمان-می‌پذیرد-چنانچه-به-واسطه-اقامت-ایشان،-خسارتی-به-محل-اقامت-و-وسایل-آن-وارد-شود،-مسئولیت-تأمین-هزینه‌های-مربوط-به-آن-بر-عهده-ایشان-خواهد-بود.' => 'مهمان-مي بذيرفض-جنانجه-به-واسطه-اقامت-ايشان،-خسارتي-به-محل-اقامت-و-وسايل-آن-وارفض-شود،-مسئوليت-تأمين-هزينه هاي-مربوط-به-آن-بر-عهده-ايشان-خواهد-بود.',
    'رزرو خریداری شده، متعلق به مهمانی است که مشخصاتش هنگام ثبت سفارش وارد شده است، لذا غیر قابل انتقال به غیر است.' => 'رزرو شراءاري شده، متعلق به مهماني است كه مشخصاتش هنكام إرسال سفارش وارفض شده است، لذا غير قابل انتقال به غير است.',
    'رزرو-خریداری-شده،-متعلق-به-مهمانی-است-که-مشخصاتش-هنگام-ثبت-سفارش-وارد-شده-است،-لذا-غیر-قابل-انتقال-به-غیر-است.' => 'رزرو-شراءاري-شده،-متعلق-به-مهماني-است-كه-مشخصاتش-هنكام-إرسال-سفارش-وارفض-شده-است،-لذا-غير-قابل-انتقال-به-غير-است.',
    'در صورتی که در مدت زمان اقامت مهمان در یک اقامتگاه، عملی خلاف قوانین جمهوری اسلامی ایران انجام شود و مسئولیت آن با شخصی است که مرتکب جرم شده است ، گیلند ملک هیچگونه مسئولیتی در خصوص تخلفات یا جرایم صورت گرفته شده ندارد.' => 'در صورتي كه در مدت الوقت اقامت مهمان در يك اقامتكاه، عملي خلاف قوانين جمهوري اسلامي ايران انجام شود و مسئوليت آن با شخصي است كه مرتكب جرم شده است ، كيلند ملك هيجكونه مسئوليتي در خصوص تخلفات يا جرايم صورت كرفته شده ندارفض.',
    'در-صورتی-که-در-مدت-زمان-اقامت-مهمان-در-یک-اقامتگاه،-عملی-خلاف-قوانین-جمهوری-اسلامی-ایران-انجام-شود-و-مسئولیت-آن-با-شخصی-است-که-مرتکب-جرم-شده-است-،-گیلند-ملک-هیچگونه-مسئولیتی-در-خصوص-تخلفات-یا-جرایم-صورت-گرفته-شده-ندارد.' => 'در-صورتي-كه-در-مدت-الوقت-اقامت-مهمان-در-يك-اقامتكاه،-عملي-خلاف-قوانين-جمهوري-اسلامي-ايران-انجام-شود-و-مسئوليت-آن-با-شخصي-است-كه-مرتكب-جرم-شده-است-،-كيلند-ملك-هيجكونه-مسئوليتي-در-خصوص-تخلفات-يا-جرايم-صورت-كرفته-شده-ندارفض.',
    'در صورت درخواست لغو رزرو اقامتگاه یا هتل، مبلغ رزرو پس از اعمال قوانین کنسلی اقامتگاه یا هتل ، به شماره شبا، حساب یا کارت بانکی درج شده توسط کاربر در حساب کاربری ایشان واریز می‌شود. تمام تلاش گیلند ملک بر آن است تا عودت مبلغ در کمترین زمان ممکن صورت پذیرد، اما بنا به شرایط ممکن است این فرآیند تا ۴۸ ساعت کاری به‌طول انجامد.' => 'در صورت درخواست لغو رزرو اقامتكاه يا هتل، مبلغ رزرو بس از اعمال قوانين كنسلي اقامتكاه يا هتل ، به شماره شبا، حساب يا كارت بانكي درج شده توسط كاربر در حساب كاربري ايشان واريز مي شود. تمام تلاش كيلند ملك بر آن است تا عودت مبلغ در كمترين الوقت ممكن صورت بذيرفض، اما بنا به شرايط ممكن است اين فرآيند تا ۴۸ ساعت كاري به طول انجامد.',
    'در-صورت-درخواست-لغو-رزرو-اقامتگاه-یا-هتل،-مبلغ-رزرو-پس-از-اعمال-قوانین-کنسلی-اقامتگاه-یا-هتل-،-به-شماره-شبا،-حساب-یا-کارت-بانکی-درج-شده-توسط-کاربر-در-حساب-کاربری-ایشان-واریز-می‌شود.-تمام-تلاش-گیلند-ملک-بر-آن-است-تا-عودت-مبلغ-در-کمترین-زمان-ممکن-صورت-پذیرد،-اما-بنا-به-شرایط-ممکن-است-این-فرآیند-تا-۴۸-ساعت-کاری-به‌طول-انجامد.' => 'در-صورت-درخواست-لغو-رزرو-اقامتكاه-يا-هتل،-مبلغ-رزرو-بس-از-اعمال-قوانين-كنسلي-اقامتكاه-يا-هتل-،-به-شماره-شبا،-حساب-يا-كارت-بانكي-درج-شده-توسط-كاربر-در-حساب-كاربري-ايشان-واريز-مي شود.-تمام-تلاش-كيلند-ملك-بر-آن-است-تا-عودت-مبلغ-در-كمترين-الوقت-ممكن-صورت-بذيرفض،-اما-بنا-به-شرايط-ممكن-است-اين-فرآيند-تا-۴۸-ساعت-كاري-به طول-انجامد.',
    'با توجه به اینکه پس از خرید نهایی هتل امکان تغییر یا اصلاح نام و یا مشخصات مهمان وجود ندارد و جهت اصلاح اطلاعات، می بایست هتل کنسل شده و مجدداً رزرو از سوی مهمان صورت گیرد، لذا ارائه اطلاعات شخصی صحیح، نظیر نام و نام خانوادگی طبق اطلاعات شناسایی( اعم و نه محدود به شماره ملی،شماره پاسپورت، ملیت مسافر، تعداد مسافرین، جنسیت و سن مهمان و … بر عهده مهمان می باشد.' => 'با توجه به اينكه بس از شراء نهايي هتل امكان تغيير يا اصلاح الاسم و يا مشخصات مهمان وجود ندارفض و جهت اصلاح المعلومات، مي بايست هتل كنسل شده و مجدداً رزرو از سوي مهمان صورت كيرفض، لذا ارائه المعلومات شخصي صحيح، نظير الاسم و الاسم خانوادكي طبق المعلومات شناسايي( اعم و نه محدود به شماره ملي،شماره باسبورت، مليت مسافر، تعداد مسافرين، جنسيت و سن مهمان و … بر عهده مهمان مي باشد.',
    'با-توجه-به-اینکه-پس-از-خرید-نهایی-هتل-امکان-تغییر-یا-اصلاح-نام-و-یا-مشخصات-مهمان-وجود-ندارد-و-جهت-اصلاح-اطلاعات،-می-بایست-هتل-کنسل-شده-و-مجدداً-رزرو-از-سوی-مهمان-صورت-گیرد،-لذا-ارائه-اطلاعات-شخصی-صحیح،-نظیر-نام-و-نام-خانوادگی-طبق-اطلاعات-شناسایی(-اعم-و-نه-محدود-به-شماره-ملی،شماره-پاسپورت،-ملیت-مسافر،-تعداد-مسافرین،-جنسیت-و-سن-مهمان-و-…-بر-عهده-مهمان-می-باشد.' => 'با-توجه-به-اينكه-بس-از-شراء-نهايي-هتل-امكان-تغيير-يا-اصلاح-الاسم-و-يا-مشخصات-مهمان-وجود-ندارفض-و-جهت-اصلاح-المعلومات،-مي-بايست-هتل-كنسل-شده-و-مجدداً-رزرو-از-سوي-مهمان-صورت-كيرفض،-لذا-ارائه-المعلومات-شخصي-صحيح،-نظير-الاسم-و-الاسم-خانوادكي-طبق-المعلومات-شناسايي(-اعم-و-نه-محدود-به-شماره-ملي،شماره-باسبورت،-مليت-مسافر،-تعداد-مسافرين،-جنسيت-و-سن-مهمان-و-…-بر-عهده-مهمان-مي-باشد.',
    'هتل خریداری شده، متعلق به مهمانی است که مشخصات خود را در سیستم وارد کرده و غیر قابل انتقال به غیر می‌باشد. و اگر مشخصات واچر با مشخصات مدارک شناسایی مهمان مطابقت نداشته باشد مهمان پذیرش نخواهد شد.' => 'هتل شراءاري شده، متعلق به مهماني است كه مشخصات خود را در سيستم وارفض كرفضه و غير قابل انتقال به غير مي باشد. و اكر مشخصات واجر با مشخصات مدارك شناسايي مهمان مطابقت نداشته باشد مهمان بذيرش نخواهد شد.',
    'هتل-خریداری-شده،-متعلق-به-مهمانی-است-که-مشخصات-خود-را-در-سیستم-وارد-کرده-و-غیر-قابل-انتقال-به-غیر-می‌باشد.-و-اگر-مشخصات-واچر-با-مشخصات-مدارک-شناسایی-مهمان-مطابقت-نداشته-باشد-مهمان-پذیرش-نخواهد-شد.' => 'هتل-شراءاري-شده،-متعلق-به-مهماني-است-كه-مشخصات-خود-را-در-سيستم-وارفض-كرفضه-و-غير-قابل-انتقال-به-غير-مي باشد.-و-اكر-مشخصات-واجر-با-مشخصات-مدارك-شناسايي-مهمان-مطابقت-نداشته-باشد-مهمان-بذيرش-نخواهد-شد.',
    'تغییر تاریخ در رزو انجام شده مقدور تیست و در این خصوص می بایست رزو جدید با شرایط و مبالغ جدید صورت گیرد.' => 'تغيير التاريخ در رزو انجام شده مقدور تيست و در اين خصوص مي بايست رزو جديد با شرايط و مبالغ جديد صورت كيرفض.',
    'تغییر-تاریخ-در-رزو-انجام-شده-مقدور-تیست-و-در-این-خصوص-می-بایست-رزو-جدید-با-شرایط-و-مبالغ-جدید-صورت-گیرد.' => 'تغيير-التاريخ-در-رزو-انجام-شده-مقدور-تيست-و-در-اين-خصوص-مي-بايست-رزو-جديد-با-شرايط-و-مبالغ-جديد-صورت-كيرفض.',
    'کنسل کردن واچر هتل یا کنسلی اقامتگاه ها توسط مهمان از طریق گیلند ملک ممکن است مشمول جریمه کنسلی گردد. مقدار جریمه و شرایط کنسلی در هر هتل، اقامتگاه یا وب سایت متفاوت است. مبلغ جریمه و شرایط کنسلی در هنگام هر رزرو به مهمان اطلاع داده خواهد شد. این مسئله در خصوص هتل ها یا اقامتگاه هایی که جریمه آنها ۱۰۰% در گیلند ملک قید شده صادق نیست و هزینه‌ی این هتل یا اقامتگاه ها در صورت کنسلی به طور کامل دریافت می‌شود.' => 'كنسل كرفضن واجر هتل يا كنسلي اقامتكاه ها توسط مهمان از طريق كيلند ملك ممكن است مشمول جريمه كنسلي كرفضد. مقدار جريمه و شرايط كنسلي در هر هتل، اقامتكاه يا وب سايت متفاوت است. مبلغ جريمه و شرايط كنسلي در هنكام هر رزرو به مهمان اطلاع داده خواهد شد. اين مسئله در خصوص هتل ها يا اقامتكاه هايي كه جريمه آنها ۱۰۰% در كيلند ملك قيد شده صادق نيست و هزينه ي اين هتل يا اقامتكاه ها در صورت كنسلي به طور كامل استلام مي شود.',
    'کنسل-کردن-واچر-هتل-یا-کنسلی-اقامتگاه-ها-توسط-مهمان-از-طریق-گیلند-ملک-ممکن-است-مشمول-جریمه-کنسلی-گردد.-مقدار-جریمه-و-شرایط-کنسلی-در-هر-هتل،-اقامتگاه-یا-وب-سایت-متفاوت-است.-مبلغ-جریمه-و-شرایط-کنسلی-در-هنگام-هر-رزرو-به-مهمان-اطلاع-داده-خواهد-شد.-این-مسئله-در-خصوص-هتل-ها-یا-اقامتگاه-هایی-که-جریمه-آنها-۱۰۰%-در-گیلند-ملک-قید-شده-صادق-نیست-و-هزینه‌ی-این-هتل-یا-اقامتگاه-ها-در-صورت-کنسلی-به-طور-کامل-دریافت-می‌شود.' => 'كنسل-كرفضن-واجر-هتل-يا-كنسلي-اقامتكاه-ها-توسط-مهمان-از-طريق-كيلند-ملك-ممكن-است-مشمول-جريمه-كنسلي-كرفضد.-مقدار-جريمه-و-شرايط-كنسلي-در-هر-هتل،-اقامتكاه-يا-وب-سايت-متفاوت-است.-مبلغ-جريمه-و-شرايط-كنسلي-در-هنكام-هر-رزرو-به-مهمان-اطلاع-داده-خواهد-شد.-اين-مسئله-در-خصوص-هتل-ها-يا-اقامتكاه-هايي-كه-جريمه-آنها-۱۰۰%-در-كيلند-ملك-قيد-شده-صادق-نيست-و-هزينه ي-اين-هتل-يا-اقامتكاه-ها-در-صورت-كنسلي-به-طور-كامل-استلام-مي شود.',
    'ممکن است حین خرید و پرداخت وجه هتل، ظرفیت هتل منتخب تکمیل شود. اگر این اتفاق پس از پرداخت وجه از سوی کاربر صورت گیرد ، مبلغ به حساب کاربری ایشان عودت داده خواهد شدو می تواند مجددا برای خرید هتل اقدام نماید. کسر مبلغ از حساب به منزله اخذ قطعی واچر هتل نبوده و در صورت انصراف از خرید، مبلغ به همان حسابی که از طریق آن خرید انجام شده است عودت داده خواهد شد.' => 'ممكن است حين شراء و برفضاخت وجه هتل، ظرفيت هتل منتخب تكميل شود. اكر اين اتفاق بس از برفضاخت وجه از سوي كاربر صورت كيرفض ، مبلغ به حساب كاربري ايشان عودت داده خواهد شدو مي تواند مجددا براي شراء هتل اقدام نمايد. كسر مبلغ از حساب به منزله اخذ قطعي واجر هتل نبوده و در صورت إلغاء از شراء، مبلغ به همان حسابي كه از طريق آن شراء انجام شده است عودت داده خواهد شد.',
    'ممکن-است-حین-خرید-و-پرداخت-وجه-هتل،-ظرفیت-هتل-منتخب-تکمیل-شود.-اگر-این-اتفاق-پس-از-پرداخت-وجه-از-سوی-کاربر-صورت-گیرد-،-مبلغ-به-حساب-کاربری-ایشان-عودت-داده-خواهد-شدو-می-تواند-مجددا-برای-خرید-هتل-اقدام-نماید.-کسر-مبلغ-از-حساب-به-منزله-اخذ-قطعی-واچر-هتل-نبوده-و-در-صورت-انصراف-از-خرید،-مبلغ-به-همان-حسابی-که-از-طریق-آن-خرید-انجام-شده-است-عودت-داده-خواهد-شد.' => 'ممكن-است-حين-شراء-و-برفضاخت-وجه-هتل،-ظرفيت-هتل-منتخب-تكميل-شود.-اكر-اين-اتفاق-بس-از-برفضاخت-وجه-از-سوي-كاربر-صورت-كيرفض-،-مبلغ-به-حساب-كاربري-ايشان-عودت-داده-خواهد-شدو-مي-تواند-مجددا-براي-شراء-هتل-اقدام-نمايد.-كسر-مبلغ-از-حساب-به-منزله-اخذ-قطعي-واجر-هتل-نبوده-و-در-صورت-إلغاء-از-شراء،-مبلغ-به-همان-حسابي-كه-از-طريق-آن-شراء-انجام-شده-است-عودت-داده-خواهد-شد.',
    'در صورت تحویل اتاق دیرتر از موعد مقرر توسط هتل ، هیچ مبلغی به مهمان عودت داده نخواهد شد و گیلند ملک در این خصوص هیچگونه مسئولیتی نخواهد داشت.' => 'در صورت تحويل غرفة ديرتر از موعد مقرر توسط هتل ، هيج مبلغي به مهمان عودت داده نخواهد شد و كيلند ملك در اين خصوص هيجكونه مسئوليتي نخواهد داشت.',
    'در-صورت-تحویل-اتاق-دیرتر-از-موعد-مقرر-توسط-هتل-،-هیچ-مبلغی-به-مهمان-عودت-داده-نخواهد-شد-و-گیلند-ملک-در-این-خصوص-هیچگونه-مسئولیتی-نخواهد-داشت.' => 'در-صورت-تحويل-غرفة-ديرتر-از-موعد-مقرر-توسط-هتل-،-هيج-مبلغي-به-مهمان-عودت-داده-نخواهد-شد-و-كيلند-ملك-در-اين-خصوص-هيجكونه-مسئوليتي-نخواهد-داشت.',
    'رزرو هتل فقط شامل رزرو اتاق به تعداد افراد و شبهای درخواست شده می باشد و دربرگیرنده مواردی همچون حمل و نقل فرودگاهی، حمل و نقل بین شهری، راهنما، تعیین طبقه، پارکینگ و یا اجاره ی خودرو و… نیست و همچنین مینی بار و صندوق امانات در اکثر هتل ها شامل هزینه اضافه بوده که به عهده مهمان است و در صورت ایجاد خسارت به هتل توسط مهمان، کلیه خسارت ها از مهمان دریافت خواهد شد.' => 'رزرو هتل فقط شامل رزرو غرفة به تعداد افراد و شبهاي درخواست شده مي باشد و دربركيرنده موارفضي همجون حمل و نقل فرودكاهي، حمل و نقل بين المدينةي، راهنما، تعيين طابق، موقف سيارات و يا إيجار ي خودرو و… نيست و همجنين ميني بار و صندوق امانات در اكثر هتل ها شامل هزينه اضافه بوده كه به عهده مهمان است و در صورت إنشاء خسارت به هتل توسط مهمان، كليه خسارت ها از مهمان استلام خواهد شد.',
    'رزرو-هتل-فقط-شامل-رزرو-اتاق-به-تعداد-افراد-و-شبهای-درخواست-شده-می-باشد-و-دربرگیرنده-مواردی-همچون-حمل-و-نقل-فرودگاهی،-حمل-و-نقل-بین-شهری،-راهنما،-تعیین-طبقه،-پارکینگ-و-یا-اجاره-ی-خودرو-و…-نیست-و-همچنین-مینی-بار-و-صندوق-امانات-در-اکثر-هتل-ها-شامل-هزینه-اضافه-بوده-که-به-عهده-مهمان-است-و-در-صورت-ایجاد-خسارت-به-هتل-توسط-مهمان،-کلیه-خسارت-ها-از-مهمان-دریافت-خواهد-شد.' => 'رزرو-هتل-فقط-شامل-رزرو-غرفة-به-تعداد-افراد-و-شبهاي-درخواست-شده-مي-باشد-و-دربركيرنده-موارفضي-همجون-حمل-و-نقل-فرودكاهي،-حمل-و-نقل-بين-المدينةي،-راهنما،-تعيين-طابق،-موقف سيارات-و-يا-إيجار-ي-خودرو-و…-نيست-و-همجنين-ميني-بار-و-صندوق-امانات-در-اكثر-هتل-ها-شامل-هزينه-اضافه-بوده-كه-به-عهده-مهمان-است-و-در-صورت-إنشاء-خسارت-به-هتل-توسط-مهمان،-كليه-خسارت-ها-از-مهمان-استلام-خواهد-شد.',
    'زمان پذیرش مهمان در هتل ( Check In) عموما ساعت ۱۴:۰۰ است. پس از ورود به هتل، در صورت خروج از هتل زودتر از موعد ثبت شده در واچر، وجهی بابت عدم استفاده از اتاق به مهمان مسترد نمی گردد.' => 'الوقت بذيرش مهمان در هتل ( Check In) عموما ساعت ۱۴:۰۰ است. بس از تسجيل الدخول به هتل، در صورت تسجيل الخروج از هتل زودتر از موعد إرسال شده در واجر، وجهي بابت عدم استفاده از غرفة به مهمان مسترفض نمي كرفضد.',
    'زمان-پذیرش-مهمان-در-هتل-(-Check-In)-عموما-ساعت-۱۴:۰۰-است.-پس-از-ورود-به-هتل،-در-صورت-خروج-از-هتل-زودتر-از-موعد-ثبت-شده-در-واچر،-وجهی-بابت-عدم-استفاده-از-اتاق-به-مهمان-مسترد-نمی-گردد.' => 'الوقت-بذيرش-مهمان-در-هتل-(-Check-In)-عموما-ساعت-۱۴:۰۰-است.-بس-از-تسجيل الدخول-به-هتل،-در-صورت-تسجيل الخروج-از-هتل-زودتر-از-موعد-إرسال-شده-در-واجر،-وجهي-بابت-عدم-استفاده-از-غرفة-به-مهمان-مسترفض-نمي-كرفضد.',
    'در خصوص خرید گروهی در شرایط عادی (غیر اضطراری) فقط شخصی که به نمایندگی از سوی مهمان اقدام به ثبت نام و خرید نموده مجاز به مراجعه به گیلند ملک جهت پیگیری، ابطال و یا دریافت وجوه پرداختی بوده و سایر مهمانان در این خصوص مجاز به مراجعه به گیلند ملک برای این امر نمی باشند.' => 'در خصوص شراء كروهي در شرايط عادي (غير اضطراري) فقط شخصي كه به نمايندكي از سوي مهمان اقدام به إرسال الاسم و شراء نموده مجاز به مراجعه به كيلند ملك جهت بيكيري، ابطال و يا استلام وجوه برفضاختي بوده و ساير مهمانان در اين خصوص مجاز به مراجعه به كيلند ملك براي اين امر نمي باشند.',
    'در-خصوص-خرید-گروهی-در-شرایط-عادی-(غیر-اضطراری)-فقط-شخصی-که-به-نمایندگی-از-سوی-مهمان-اقدام-به-ثبت-نام-و-خرید-نموده-مجاز-به-مراجعه-به-گیلند-ملک-جهت-پیگیری،-ابطال-و-یا-دریافت-وجوه-پرداختی-بوده-و-سایر-مهمانان-در-این-خصوص-مجاز-به-مراجعه-به-گیلند-ملک-برای-این-امر-نمی-باشند.' => 'در-خصوص-شراء-كروهي-در-شرايط-عادي-(غير-اضطراري)-فقط-شخصي-كه-به-نمايندكي-از-سوي-مهمان-اقدام-به-إرسال-الاسم-و-شراء-نموده-مجاز-به-مراجعه-به-كيلند-ملك-جهت-بيكيري،-ابطال-و-يا-استلام-وجوه-برفضاختي-بوده-و-ساير-مهمانان-در-اين-خصوص-مجاز-به-مراجعه-به-كيلند-ملك-براي-اين-امر-نمي-باشند.',
    'اگر کاربر درخواست هایی همچون اتاق با دو تخت یک نفره، یا اتاق دارای امکان استفاده از دخانیات ، ورود زودتر یا دیرتر از موعد و مواردی از این قبیل را داشته باشد، گیلند ملک به هتل منتقل می کند و تایید نهایی در این خصوص با هتل است و گیلند ملک در این خصوص هیچگونه مسئولیتی نخواهد داشت.' => 'اكر كاربر درخواست هايي همجون غرفة با دو تخت يك نفره، يا غرفة داراي امكان استفاده از دخانيات ، تسجيل الدخول زودتر يا ديرتر از موعد و موارفضي از اين قبيل را داشته باشد، كيلند ملك به هتل منتقل مي كند و تأكيد نهايي در اين خصوص با هتل است و كيلند ملك در اين خصوص هيجكونه مسئوليتي نخواهد داشت.',
    'اگر-کاربر-درخواست-هایی-همچون-اتاق-با-دو-تخت-یک-نفره،-یا-اتاق-دارای-امکان-استفاده-از-دخانیات-،-ورود-زودتر-یا-دیرتر-از-موعد-و-مواردی-از-این-قبیل-را-داشته-باشد،-گیلند-ملک-به-هتل-منتقل-می-کند-و-تایید-نهایی-در-این-خصوص-با-هتل-است-و-گیلند-ملک-در-این-خصوص-هیچگونه-مسئولیتی-نخواهد-داشت.' => 'اكر-كاربر-درخواست-هايي-همجون-غرفة-با-دو-تخت-يك-نفره،-يا-غرفة-داراي-امكان-استفاده-از-دخانيات-،-تسجيل الدخول-زودتر-يا-ديرتر-از-موعد-و-موارفضي-از-اين-قبيل-را-داشته-باشد،-كيلند-ملك-به-هتل-منتقل-مي-كند-و-تأكيد-نهايي-در-اين-خصوص-با-هتل-است-و-كيلند-ملك-در-اين-خصوص-هيجكونه-مسئوليتي-نخواهد-داشت.',
    'قابل ذکر است طبق قوانین اکثر هتل‌ها، افراد بالای ۴ سال بزرگسال محسوب می‌گردند و می‌بایست هنگام رزرو اتاق برای آنان تخت درنظر گرفته شود، در صورت عدم رعایت این موضوع ممکن است هتل از ورود تعداد افراد بیش از ظرفیت رزرو شده ممانعت بعمل آورد. گیلند ملک هیچگونه مسئولیتی در این خصوص نخواهد داشت. در صورت نیاز به تخت برای کودک در هر سنی زمان خرید، نیز همچون مورد قبل باید کودک را بزرگسال انتخاب نموده و اطمینان حاصل فرمایید نوع اتاق منتخب ظرفیت کل تعداد نفرات در یک اتاق را دارا باشد، در صورت عدم رعایت این موضوع زمان پذیرش هزینه نفر اضافه مستقیما توسط مهمان در هتل پرداخت می گردد و هیچ نوع مسئولیتی در این خصوص متوجه گیلند ملک نخواهد بود.' => 'قابل ذكر است طبق قوانين اكثر هتل ها، افراد بالاي ۴ سال بزركسال محسوب مي كرفضند و مي بايست هنكام رزرو غرفة براي آنان تخت درنظر كرفته شود، در صورت عدم رعايت اين موضوع ممكن است هتل از تسجيل الدخول تعداد افراد بيش از ظرفيت رزرو شده ممانعت بعمل آورفض. كيلند ملك هيجكونه مسئوليتي در اين خصوص نخواهد داشت. در صورت نياز به تخت براي كودك در هر سني الوقت شراء، نيز همجون مورفض قبل بايد كودك را بزركسال انتخاب نموده و اطمينان حاصل فرماييد نوع غرفة منتخب ظرفيت كل تعداد نفرات در يك غرفة را دارا باشد، در صورت عدم رعايت اين موضوع الوقت بذيرش هزينه نفر اضافه مستقيما توسط مهمان در هتل برفضاخت مي كرفضد و هيج نوع مسئوليتي در اين خصوص متوجه كيلند ملك نخواهد بود.',
    'قابل-ذکر-است-طبق-قوانین-اکثر-هتل‌ها،-افراد-بالای-۴-سال-بزرگسال-محسوب-می‌گردند-و-می‌بایست-هنگام-رزرو-اتاق-برای-آنان-تخت-درنظر-گرفته-شود،-در-صورت-عدم-رعایت-این-موضوع-ممکن-است-هتل-از-ورود-تعداد-افراد-بیش-از-ظرفیت-رزرو-شده-ممانعت-بعمل-آورد.-گیلند-ملک-هیچگونه-مسئولیتی-در-این-خصوص-نخواهد-داشت.-در-صورت-نیاز-به-تخت-برای-کودک-در-هر-سنی-زمان-خرید،-نیز-همچون-مورد-قبل-باید-کودک-را-بزرگسال-انتخاب-نموده-و-اطمینان-حاصل-فرمایید-نوع-اتاق-منتخب-ظرفیت-کل-تعداد-نفرات-در-یک-اتاق-را-دارا-باشد،-در-صورت-عدم-رعایت-این-موضوع-زمان-پذیرش-هزینه-نفر-اضافه-مستقیما-توسط-مهمان-در-هتل-پرداخت-می-گردد-و-هیچ-نوع-مسئولیتی-در-این-خصوص-متوجه-گیلند-ملک-نخواهد-بود.' => 'قابل-ذكر-است-طبق-قوانين-اكثر-هتل ها،-افراد-بالاي-۴-سال-بزركسال-محسوب-مي كرفضند-و-مي بايست-هنكام-رزرو-غرفة-براي-آنان-تخت-درنظر-كرفته-شود،-در-صورت-عدم-رعايت-اين-موضوع-ممكن-است-هتل-از-تسجيل الدخول-تعداد-افراد-بيش-از-ظرفيت-رزرو-شده-ممانعت-بعمل-آورفض.-كيلند-ملك-هيجكونه-مسئوليتي-در-اين-خصوص-نخواهد-داشت.-در-صورت-نياز-به-تخت-براي-كودك-در-هر-سني-الوقت-شراء،-نيز-همجون-مورفض-قبل-بايد-كودك-را-بزركسال-انتخاب-نموده-و-اطمينان-حاصل-فرماييد-نوع-غرفة-منتخب-ظرفيت-كل-تعداد-نفرات-در-يك-غرفة-را-دارا-باشد،-در-صورت-عدم-رعايت-اين-موضوع-الوقت-بذيرش-هزينه-نفر-اضافه-مستقيما-توسط-مهمان-در-هتل-برفضاخت-مي-كرفضد-و-هيج-نوع-مسئوليتي-در-اين-خصوص-متوجه-كيلند-ملك-نخواهد-بود.',
    'در صورتیکه هتل به هر دلیلی، امکان پذیرش مهمان با وجود واچر معتبر را نداشته باشد، مهمان باید با واحد پشتیبانی شبانه روزی گیلند ملک با شماره 09300755673 تماس گرفته تا در کمترین زمان مشکل حل شود و یا در صورت عدم پذیرش مهمان توسط هتل منتخب ، هتل مناسب دیگری مشابه هتل منتخب مهمان که از طرف تامین کننده پیشنهاد شده است برای مهمان جایگزین گردد. در صورت عدم پذیرش هتل پیشنهادی توسط مهمان، مبلغ اخذ شده بابت آن رزرو را به مهمان استرداد می کند و گیلند ملک دیگر هیچ مسئولیتی در قبال آن رزرو ندارد.' => 'در صورتيكه هتل به هر دليلي، امكان بذيرش مهمان با وجود واجر معتبر را نداشته باشد، مهمان بايد با واحد الدعم الفني شبانه روزي كيلند ملك با شماره 09300755673 تماس كرفته تا در كمترين الوقت مشكل حل شود و يا در صورت عدم بذيرش مهمان توسط هتل منتخب ، هتل مناسب ديكري مشابه هتل منتخب مهمان كه از طرف تامين كننده بيشنهاد شده است براي مهمان جايكزين كرفضد. در صورت عدم بذيرش هتل بيشنهادي توسط مهمان، مبلغ اخذ شده بابت آن رزرو را به مهمان استرفضاد مي كند و كيلند ملك ديكر هيج مسئوليتي در قبال آن رزرو ندارفض.',
    'در-صورتیکه-هتل-به-هر-دلیلی،-امکان-پذیرش-مهمان-با-وجود-واچر-معتبر-را-نداشته-باشد،-مهمان-باید-با-واحد-پشتیبانی-شبانه-روزی-گیلند-ملک-با-شماره-09300755673-تماس-گرفته-تا-در-کمترین-زمان-مشکل-حل-شود-و-یا-در-صورت-عدم-پذیرش-مهمان-توسط-هتل-منتخب-،-هتل-مناسب-دیگری-مشابه-هتل-منتخب-مهمان-که-از-طرف-تامین-کننده-پیشنهاد-شده-است-برای-مهمان-جایگزین-گردد.-در-صورت-عدم-پذیرش-هتل-پیشنهادی-توسط-مهمان،-مبلغ-اخذ-شده-بابت-آن-رزرو-را-به-مهمان-استرداد-می-کند-و-گیلند-ملک-دیگر-هیچ-مسئولیتی-در-قبال-آن-رزرو-ندارد.' => 'در-صورتيكه-هتل-به-هر-دليلي،-امكان-بذيرش-مهمان-با-وجود-واجر-معتبر-را-نداشته-باشد،-مهمان-بايد-با-واحد-الدعم الفني-شبانه-روزي-كيلند-ملك-با-شماره-09300755673-تماس-كرفته-تا-در-كمترين-الوقت-مشكل-حل-شود-و-يا-در-صورت-عدم-بذيرش-مهمان-توسط-هتل-منتخب-،-هتل-مناسب-ديكري-مشابه-هتل-منتخب-مهمان-كه-از-طرف-تامين-كننده-بيشنهاد-شده-است-براي-مهمان-جايكزين-كرفضد.-در-صورت-عدم-بذيرش-هتل-بيشنهادي-توسط-مهمان،-مبلغ-اخذ-شده-بابت-آن-رزرو-را-به-مهمان-استرفضاد-مي-كند-و-كيلند-ملك-ديكر-هيج-مسئوليتي-در-قبال-آن-رزرو-ندارفض.',
    'پس از پرداخت مبلغ رزرواسیون هتل و قطعی شدن آن، واچر برای کاربر صادر در حساب کاربری منتشر و به ایمیل کاربر ارسال می گردد. ارایه واچر هتل به همراه مدارک شناسایی از سوی مهمان به مسئول پذیرش هتل الزامی است.. با توجه به شرایط هتل، رزرو اتاق های سه تخته ممکن است شامل یک اتاق دو تخته همراه با تخت اضافه(Extra bed) بوده و یا سه تخت استاندارد است و نیز سایز اتاق ها و انتخاب طبقه اتاق ها بستگی به ظرفیت هتل در زمان پذیرش مهمان دارد.' => 'بس از برفضاخت مبلغ رزرواسيون هتل و قطعي شدن آن، واجر براي كاربر صادر در حساب كاربري منتشر و به البريد الإلكتروني كاربر إرسال مي كرفضد. ارايه واجر هتل به همراه مدارك شناسايي از سوي مهمان به مسئول بذيرش هتل الزامي است.. با توجه به شرايط هتل، رزرو غرفة هاي سه تخته ممكن است شامل يك غرفة دو تخته همراه با تخت اضافه(Extra bed) بوده و يا سه تخت الإمارةدارفض است و نيز سايز غرفة ها و انتخاب طابق غرفة ها بستكي به ظرفيت هتل در الوقت بذيرش مهمان دارفض.',
    'پس-از-پرداخت-مبلغ-رزرواسیون-هتل-و-قطعی-شدن-آن،-واچر-برای-کاربر-صادر-در-حساب-کاربری-منتشر-و-به-ایمیل-کاربر-ارسال-می-گردد.-ارایه-واچر-هتل-به-همراه-مدارک-شناسایی-از-سوی-مهمان-به-مسئول-پذیرش-هتل-الزامی-است..-با-توجه-به-شرایط-هتل،-رزرو-اتاق-های-سه-تخته-ممکن-است-شامل-یک-اتاق-دو-تخته-همراه-با-تخت-اضافه(Extra-bed)-بوده-و-یا-سه-تخت-استاندارد-است-و-نیز-سایز-اتاق-ها-و-انتخاب-طبقه-اتاق-ها-بستگی-به-ظرفیت-هتل-در-زمان-پذیرش-مهمان-دارد.' => 'بس-از-برفضاخت-مبلغ-رزرواسيون-هتل-و-قطعي-شدن-آن،-واجر-براي-كاربر-صادر-در-حساب-كاربري-منتشر-و-به-البريد الإلكتروني-كاربر-إرسال-مي-كرفضد.-ارايه-واجر-هتل-به-همراه-مدارك-شناسايي-از-سوي-مهمان-به-مسئول-بذيرش-هتل-الزامي-است..-با-توجه-به-شرايط-هتل،-رزرو-غرفة-هاي-سه-تخته-ممكن-است-شامل-يك-غرفة-دو-تخته-همراه-با-تخت-اضافه(Extra-bed)-بوده-و-يا-سه-تخت-الإمارةدارفض-است-و-نيز-سايز-غرفة-ها-و-انتخاب-طابق-غرفة-ها-بستكي-به-ظرفيت-هتل-در-الوقت-بذيرش-مهمان-دارفض.',
    'با انجام رزرو از سوی کاربر و تایید آن از سوی هتل، مهمان مقررات مربوط به هتل منتخب و همچنین قوانین مربوط به فسخ رزرو را نیز پذیرفته است. به عبارت دیگر مهمان با آگاهی و اطلاع کافی از مقررات گیلند ملک و اعلامی از سوی هتل، نسبت به رزرو اقدام نموده است در قراردادهای آنلاین طبق قانون تجارت الکترونیک امضای مهمان به صورت الکترونیک انجام میشود.' => 'با انجام رزرو از سوي كاربر و تأكيد آن از سوي هتل، مهمان مقررات مربوط به هتل منتخب و همجنين قوانين مربوط به فسخ رزرو را نيز بذيرفته است. به عبارت ديكر مهمان با آكاهي و اطلاع كافي از مقررات كيلند ملك و اعلامي از سوي هتل، نسبت به رزرو اقدام نموده است در قرارفضادهاي آنلاين طبق قانون تجارت الكترونيك امضاي مهمان به صورت الكترونيك انجام ميشود.',
    'با-انجام-رزرو-از-سوی-کاربر-و-تایید-آن-از-سوی-هتل،-مهمان-مقررات-مربوط-به-هتل-منتخب-و-همچنین-قوانین-مربوط-به-فسخ-رزرو-را-نیز-پذیرفته-است.-به-عبارت-دیگر-مهمان-با-آگاهی-و-اطلاع-کافی-از-مقررات-گیلند-ملک-و-اعلامی-از-سوی-هتل،-نسبت-به-رزرو-اقدام-نموده-است-در-قراردادهای-آنلاین-طبق-قانون-تجارت-الکترونیک-امضای-مهمان-به-صورت-الکترونیک-انجام-میشود.' => 'با-انجام-رزرو-از-سوي-كاربر-و-تأكيد-آن-از-سوي-هتل،-مهمان-مقررات-مربوط-به-هتل-منتخب-و-همجنين-قوانين-مربوط-به-فسخ-رزرو-را-نيز-بذيرفته-است.-به-عبارت-ديكر-مهمان-با-آكاهي-و-اطلاع-كافي-از-مقررات-كيلند-ملك-و-اعلامي-از-سوي-هتل،-نسبت-به-رزرو-اقدام-نموده-است-در-قرارفضادهاي-آنلاين-طبق-قانون-تجارت-الكترونيك-امضاي-مهمان-به-صورت-الكترونيك-انجام-ميشود.',
    'مهمان و میزبان می‌پذیرند که فرآیند رزرو و تایید یا رد آن در گیلندملک تنها از طریق ارسال پیام کوتاه (SMS) و ایمیل (به شماره و ایمیل درج شده در هنگام ثبت نام) است. لذا مسئولیت عدم دریافت پیام کوتاه یا ایمیل به‌دلیل عدم دسترسی به اینترنت، ضعف آنتن‌دهی موبایل و یا درج اطلاعات اشتباه هنگام ثبت نام برعهده کاربر است.' => 'مهمان و ميزبان مي بذيرند كه فرآيند رزرو و تأكيد يا رفض آن در كيلندملك تنها از طريق إرسال رسالة كوتاه (SMS) و البريد الإلكتروني (به شماره و البريد الإلكتروني درج شده در هنكام إرسال الاسم) است. لذا مسئوليت عدم استلام رسالة كوتاه يا البريد الإلكتروني به دليل عدم دسترسي به اينترنت، ضعف آنتن دهي الجوال و يا درج المعلومات اشتباه هنكام إرسال الاسم برعهده كاربر است.',
    'مهمان-و-میزبان-می‌پذیرند-که-فرآیند-رزرو-و-تایید-یا-رد-آن-در-گیلندملک-تنها-از-طریق-ارسال-پیام-کوتاه-(SMS)-و-ایمیل-(به-شماره-و-ایمیل-درج-شده-در-هنگام-ثبت-نام)-است.-لذا-مسئولیت-عدم-دریافت-پیام-کوتاه-یا-ایمیل-به‌دلیل-عدم-دسترسی-به-اینترنت،-ضعف-آنتن‌دهی-موبایل-و-یا-درج-اطلاعات-اشتباه-هنگام-ثبت-نام-برعهده-کاربر-است.' => 'مهمان-و-ميزبان-مي بذيرند-كه-فرآيند-رزرو-و-تأكيد-يا-رفض-آن-در-كيلندملك-تنها-از-طريق-إرسال-رسالة-كوتاه-(SMS)-و-البريد الإلكتروني-(به-شماره-و-البريد الإلكتروني-درج-شده-در-هنكام-إرسال-الاسم)-است.-لذا-مسئوليت-عدم-استلام-رسالة-كوتاه-يا-البريد الإلكتروني-به دليل-عدم-دسترسي-به-اينترنت،-ضعف-آنتن دهي-الجوال-و-يا-درج-المعلومات-اشتباه-هنكام-إرسال-الاسم-برعهده-كاربر-است.',
    'واریز مبلغ توسط مهمان به معنای رزرو قطعی محسوب نشده و تنها پس از تایید توسط میزبان و صدور واچر از طرف گیلند ملک، رزرو و خرید قطعی شده تلقی می‌شود. در این حالت اطلاعات رزرو و اطلاعات تماس میزبان و مهمان از طریق پیام کوتاه و ایمیل به آنها ارسال می‌شود و می‌توانند هماهنگی‌های لازم را با هم به عمل آورند. و در صورت عدم تایید نهایی رزرو، مبلغ واریز شده توسط مهمان طی مدت 48.ساعت به ایشان عودت داده خواهد شد. مهمان متعهد می‌شود که تعداد همراهان مراجعه کننده به اقامتگاه جهت اقامت، دقیقاً مطابق تعداد اعلام شده در درخواست رزرو باشد، در غیر این صورت، پذیرش نفر اضافه منوط به تأیید میزبان و هزینه آن بر عهده مهمان است. گیلند ملک نیز هیچگونه مسئولیتی در خصوص پیگیری افزودن تعداد همراهان مهمان نخواهد داشت.' => 'واريز مبلغ توسط مهمان به معناي رزرو قطعي محسوب نشده و تنها بس از تأكيد توسط ميزبان و صدور واجر از طرف كيلند ملك، رزرو و شراء قطعي شده تلقي مي شود. در اين حالت المعلومات رزرو و المعلومات تماس ميزبان و مهمان از طريق رسالة كوتاه و البريد الإلكتروني به آنها إرسال مي شود و مي توانند هماهنكي هاي لازم را با هم به عمل آورند. و در صورت عدم تأكيد نهايي رزرو، مبلغ واريز شده توسط مهمان طي مدت 48.ساعت به ايشان عودت داده خواهد شد. مهمان متعهد مي شود كه تعداد همراهان مراجعه كننده به اقامتكاه جهت اقامت، دقيقاً مطابق تعداد اعلام شده در درخواست رزرو باشد، در غير اين صورت، بذيرش نفر اضافه منوط به تأييد ميزبان و هزينه آن بر عهده مهمان است. كيلند ملك نيز هيجكونه مسئوليتي در خصوص بيكيري افزودن تعداد همراهان مهمان نخواهد داشت.',
    'واریز-مبلغ-توسط-مهمان-به-معنای-رزرو-قطعی-محسوب-نشده-و-تنها-پس-از-تایید-توسط-میزبان-و-صدور-واچر-از-طرف-گیلند-ملک،-رزرو-و-خرید-قطعی-شده-تلقی-می‌شود.-در-این-حالت-اطلاعات-رزرو-و-اطلاعات-تماس-میزبان-و-مهمان-از-طریق-پیام-کوتاه-و-ایمیل-به-آنها-ارسال-می‌شود-و-می‌توانند-هماهنگی‌های-لازم-را-با-هم-به-عمل-آورند.-و-در-صورت-عدم-تایید-نهایی-رزرو،-مبلغ-واریز-شده-توسط-مهمان-طی-مدت-48.ساعت-به-ایشان-عودت-داده-خواهد-شد.-مهمان-متعهد-می‌شود-که-تعداد-همراهان-مراجعه-کننده-به-اقامتگاه-جهت-اقامت،-دقیقاً-مطابق-تعداد-اعلام-شده-در-درخواست-رزرو-باشد،-در-غیر-این-صورت،-پذیرش-نفر-اضافه-منوط-به-تأیید-میزبان-و-هزینه-آن-بر-عهده-مهمان-است.-گیلند-ملک-نیز-هیچگونه-مسئولیتی-در-خصوص-پیگیری-افزودن-تعداد-همراهان-مهمان-نخواهد-داشت.' => 'واريز-مبلغ-توسط-مهمان-به-معناي-رزرو-قطعي-محسوب-نشده-و-تنها-بس-از-تأكيد-توسط-ميزبان-و-صدور-واجر-از-طرف-كيلند-ملك،-رزرو-و-شراء-قطعي-شده-تلقي-مي شود.-در-اين-حالت-المعلومات-رزرو-و-المعلومات-تماس-ميزبان-و-مهمان-از-طريق-رسالة-كوتاه-و-البريد الإلكتروني-به-آنها-إرسال-مي شود-و-مي توانند-هماهنكي هاي-لازم-را-با-هم-به-عمل-آورند.-و-در-صورت-عدم-تأكيد-نهايي-رزرو،-مبلغ-واريز-شده-توسط-مهمان-طي-مدت-48.ساعت-به-ايشان-عودت-داده-خواهد-شد.-مهمان-متعهد-مي شود-كه-تعداد-همراهان-مراجعه-كننده-به-اقامتكاه-جهت-اقامت،-دقيقاً-مطابق-تعداد-اعلام-شده-در-درخواست-رزرو-باشد،-در-غير-اين-صورت،-بذيرش-نفر-اضافه-منوط-به-تأييد-ميزبان-و-هزينه-آن-بر-عهده-مهمان-است.-كيلند-ملك-نيز-هيجكونه-مسئوليتي-در-خصوص-بيكيري-افزودن-تعداد-همراهان-مهمان-نخواهد-داشت.',
    'مهمان متعهد است قوانین اشاره شده توسط میزبان در استفاده از اقامتگاه احترام گذارد و اجرا نماید در غیر اینصورت مسئولیت نقض قواعد برعهده مهمان است و گیلند ملک در این خصوص مسئولیتی نخواهد داشت. به طور مثال در صورتی که میزبان ورود حیوانات خانگی را ممنوع اعلام کرده باشد و مهمان آن شرایط را رعایت ننماید، مسئولیت اتفاقات رخ داده با مهمان است.' => 'مهمان متعهد است قوانين اشاره شده توسط ميزبان در استفاده از اقامتكاه احترام كذارفض و اجرا نمايد در غير اينصورت مسئوليت نقض قواعد برعهده مهمان است و كيلند ملك در اين خصوص مسئوليتي نخواهد داشت. به طور مثال در صورتي كه ميزبان تسجيل الدخول حيوانات خانكي را ممنوع اعلام كرفضه باشد و مهمان آن شرايط را رعايت ننمايد، مسئوليت اتفاقات رخ داده با مهمان است.',
    'مهمان-متعهد-است-قوانین-اشاره-شده-توسط-میزبان-در-استفاده-از-اقامتگاه-احترام-گذارد-و-اجرا-نماید-در-غیر-اینصورت-مسئولیت-نقض-قواعد-برعهده-مهمان-است-و-گیلند-ملک-در-این-خصوص-مسئولیتی-نخواهد-داشت.-به-طور-مثال-در-صورتی-که-میزبان-ورود-حیوانات-خانگی-را-ممنوع-اعلام-کرده-باشد-و-مهمان-آن-شرایط-را-رعایت-ننماید،-مسئولیت-اتفاقات-رخ-داده-با-مهمان-است.' => 'مهمان-متعهد-است-قوانين-اشاره-شده-توسط-ميزبان-در-استفاده-از-اقامتكاه-احترام-كذارفض-و-اجرا-نمايد-در-غير-اينصورت-مسئوليت-نقض-قواعد-برعهده-مهمان-است-و-كيلند-ملك-در-اين-خصوص-مسئوليتي-نخواهد-داشت.-به-طور-مثال-در-صورتي-كه-ميزبان-تسجيل الدخول-حيوانات-خانكي-را-ممنوع-اعلام-كرفضه-باشد-و-مهمان-آن-شرايط-را-رعايت-ننمايد،-مسئوليت-اتفاقات-رخ-داده-با-مهمان-است.',
    'مهمان متعهد است مطابق تعداد نفراتی که هنگام رزرو انتخاب کرده به اقامتگاه مراجعه کند، در غیر اینصورت مسئولیت نقض قواعد برعهده مهمان است و گیلند ملک و میزبان در این خصوص مسئولیتی نخواهند داشت. به طور مثال در صورتی که مهمان هنگام رزرو تعداد نفرات را ۴ نفر انتخاب کرده باشد و هنگام مراجعه بیش از ۴ نفر باشند، مسئولیت اتفاقات رخ داده با مهمان است و میزبان می‌تواند مهمان را پذیرش نکند.' => 'مهمان متعهد است مطابق تعداد نفراتي كه هنكام رزرو انتخاب كرفضه به اقامتكاه مراجعه كند، در غير اينصورت مسئوليت نقض قواعد برعهده مهمان است و كيلند ملك و ميزبان در اين خصوص مسئوليتي نخواهند داشت. به طور مثال در صورتي كه مهمان هنكام رزرو تعداد نفرات را ۴ نفر انتخاب كرفضه باشد و هنكام مراجعه بيش از ۴ نفر باشند، مسئوليت اتفاقات رخ داده با مهمان است و ميزبان مي تواند مهمان را بذيرش نكند.',
    'مهمان-متعهد-است-مطابق-تعداد-نفراتی-که-هنگام-رزرو-انتخاب-کرده-به-اقامتگاه-مراجعه-کند،-در-غیر-اینصورت-مسئولیت-نقض-قواعد-برعهده-مهمان-است-و-گیلند-ملک-و-میزبان-در-این-خصوص-مسئولیتی-نخواهند-داشت.-به-طور-مثال-در-صورتی-که-مهمان-هنگام-رزرو-تعداد-نفرات-را-۴-نفر-انتخاب-کرده-باشد-و-هنگام-مراجعه-بیش-از-۴-نفر-باشند،-مسئولیت-اتفاقات-رخ-داده-با-مهمان-است-و-میزبان-می‌تواند-مهمان-را-پذیرش-نکند.' => 'مهمان-متعهد-است-مطابق-تعداد-نفراتي-كه-هنكام-رزرو-انتخاب-كرفضه-به-اقامتكاه-مراجعه-كند،-در-غير-اينصورت-مسئوليت-نقض-قواعد-برعهده-مهمان-است-و-كيلند-ملك-و-ميزبان-در-اين-خصوص-مسئوليتي-نخواهند-داشت.-به-طور-مثال-در-صورتي-كه-مهمان-هنكام-رزرو-تعداد-نفرات-را-۴-نفر-انتخاب-كرفضه-باشد-و-هنكام-مراجعه-بيش-از-۴-نفر-باشند،-مسئوليت-اتفاقات-رخ-داده-با-مهمان-است-و-ميزبان-مي تواند-مهمان-را-بذيرش-نكند.',
    'میزبان می‌پذیرد که قیمت درج شده در گیلند ملک نهایی است و اخذ هرگونه هزینه اضافه از مهمان تحت هر عنوان اعم از حق کمیسیون، پورسانت، حق دلالی و غیره، مجاز نیست. در غیر این‌صورت، اقامتگاه و نام کاربری وی حذف می‌شود. ارایه خدمات اضافه بر آنچه که در صفحه اقامتگاه درج شده است، خارج از تعهد مذبور است و منوط به توافق با مهمان است.' => 'ميزبان مي بذيرفض كه السعر درج شده در كيلند ملك نهايي است و اخذ هركونه هزينه اضافه از مهمان تحت هر العنوان اعم از حق كميسيون، بورسانت، حق دلالي و غيره، مجاز نيست. در غير اين صورت، اقامتكاه و الاسم كاربري وي حذف مي شود. ارايه خدمات اضافه بر آنجه كه در صفحه اقامتكاه درج شده است، خارج از تعهد مذبور است و منوط به توافق با مهمان است.',
    'میزبان-می‌پذیرد-که-قیمت-درج-شده-در-گیلند-ملک-نهایی-است-و-اخذ-هرگونه-هزینه-اضافه-از-مهمان-تحت-هر-عنوان-اعم-از-حق-کمیسیون،-پورسانت،-حق-دلالی-و-غیره،-مجاز-نیست.-در-غیر-این‌صورت،-اقامتگاه-و-نام-کاربری-وی-حذف-می‌شود.-ارایه-خدمات-اضافه-بر-آنچه-که-در-صفحه-اقامتگاه-درج-شده-است،-خارج-از-تعهد-مذبور-است-و-منوط-به-توافق-با-مهمان-است.' => 'ميزبان-مي بذيرفض-كه-السعر-درج-شده-در-كيلند-ملك-نهايي-است-و-اخذ-هركونه-هزينه-اضافه-از-مهمان-تحت-هر-العنوان-اعم-از-حق-كميسيون،-بورسانت،-حق-دلالي-و-غيره،-مجاز-نيست.-در-غير-اين صورت،-اقامتكاه-و-الاسم-كاربري-وي-حذف-مي شود.-ارايه-خدمات-اضافه-بر-آنجه-كه-در-صفحه-اقامتكاه-درج-شده-است،-خارج-از-تعهد-مذبور-است-و-منوط-به-توافق-با-مهمان-است.',
    'میزبان می‌تواند درخواست اقامت را بپذیرد و یا رد کند. در صورتی که میزبان درخواست اقامتی را پذیرفت، متعهد به ارایه خدمات براساس آن درخواست است در غیر این‌صورت خسارات وارده به مهمان و گیلند ملک و عواقب ناشی از آن بر عهده میزبان است.' => 'ميزبان مي تواند درخواست اقامت را ببذيرفض و يا رفض كند. در صورتي كه ميزبان درخواست اقامتي را بذيرفت، متعهد به ارايه خدمات براساس آن درخواست است در غير اين صورت خسارات وارفضه به مهمان و كيلند ملك و عواقب ناشي از آن بر عهده ميزبان است.',
    'میزبان-می‌تواند-درخواست-اقامت-را-بپذیرد-و-یا-رد-کند.-در-صورتی-که-میزبان-درخواست-اقامتی-را-پذیرفت،-متعهد-به-ارایه-خدمات-براساس-آن-درخواست-است-در-غیر-این‌صورت-خسارات-وارده-به-مهمان-و-گیلند-ملک-و-عواقب-ناشی-از-آن-بر-عهده-میزبان-است.' => 'ميزبان-مي تواند-درخواست-اقامت-را-ببذيرفض-و-يا-رفض-كند.-در-صورتي-كه-ميزبان-درخواست-اقامتي-را-بذيرفت،-متعهد-به-ارايه-خدمات-براساس-آن-درخواست-است-در-غير-اين صورت-خسارات-وارفضه-به-مهمان-و-كيلند-ملك-و-عواقب-ناشي-از-آن-بر-عهده-ميزبان-است.',
    'مهمان می پذیرد هرگونه تغییر در جزییات رزرو را با هماهنگی گیلند ملک انجام دهد و از هرگونه توافق مستقیم با میزبان که مطابق اطلاعات رزرو نباشد، خودداری نماید. هرگونه واریز وجه نیز به مهمان به صورت مستقیم ممنوع است و گیلند ملک تنها مسئول پیگیری تراکنش هایی است که از طریق سایت گیلند ملک صورت می گیرد.' => 'مهمان مي بذيرفض هركونه تغيير در جزييات رزرو را با هماهنكي كيلند ملك انجام دهد و از هركونه توافق مستقيم با ميزبان كه مطابق المعلومات رزرو نباشد، خودداري نمايد. هركونه واريز وجه نيز به مهمان به صورت مستقيم ممنوع است و كيلند ملك تنها مسئول بيكيري تراكنش هايي است كه از طريق سايت كيلند ملك صورت مي كيرفض.',
    'مهمان-می-پذیرد-هرگونه-تغییر-در-جزییات-رزرو-را-با-هماهنگی-گیلند-ملک-انجام-دهد-و-از-هرگونه-توافق-مستقیم-با-میزبان-که-مطابق-اطلاعات-رزرو-نباشد،-خودداری-نماید.-هرگونه-واریز-وجه-نیز-به-مهمان-به-صورت-مستقیم-ممنوع-است-و-گیلند-ملک-تنها-مسئول-پیگیری-تراکنش-هایی-است-که-از-طریق-سایت-گیلند-ملک-صورت-می-گیرد.' => 'مهمان-مي-بذيرفض-هركونه-تغيير-در-جزييات-رزرو-را-با-هماهنكي-كيلند-ملك-انجام-دهد-و-از-هركونه-توافق-مستقيم-با-ميزبان-كه-مطابق-المعلومات-رزرو-نباشد،-خودداري-نمايد.-هركونه-واريز-وجه-نيز-به-مهمان-به-صورت-مستقيم-ممنوع-است-و-كيلند-ملك-تنها-مسئول-بيكيري-تراكنش-هايي-است-كه-از-طريق-سايت-كيلند-ملك-صورت-مي-كيرفض.',
    'میزبان متعهد می‌شود در صورت عدم مراجعه مهمان به اقامتگاه در تاریخ رزرو شده، اقامتگاه تا پایان مدت رزرو شده، برای مهمان خالی خواهد ماند، همچنین مهمان می‌پذیرد که در این شرایط هیچ‌ مبلغی به وی مسترد نخواهد شد. (در صورت درخواست لغو رزرو توسط مهمان، مطابق قوانین کنسلی آن اقامتگاه رفتار می‌شود.)' => 'ميزبان متعهد مي شود در صورت عدم مراجعه مهمان به اقامتكاه در التاريخ رزرو شده، اقامتكاه تا بايان مدت رزرو شده، براي مهمان خالي خواهد ماند، همجنين مهمان مي بذيرفض كه در اين شرايط هيج مبلغي به وي مسترفض نخواهد شد. (در صورت درخواست لغو رزرو توسط مهمان، مطابق قوانين كنسلي آن اقامتكاه رفتار مي شود.)',
    'میزبان-متعهد-می‌شود-در-صورت-عدم-مراجعه-مهمان-به-اقامتگاه-در-تاریخ-رزرو-شده،-اقامتگاه-تا-پایان-مدت-رزرو-شده،-برای-مهمان-خالی-خواهد-ماند،-همچنین-مهمان-می‌پذیرد-که-در-این-شرایط-هیچ‌-مبلغی-به-وی-مسترد-نخواهد-شد.-(در-صورت-درخواست-لغو-رزرو-توسط-مهمان،-مطابق-قوانین-کنسلی-آن-اقامتگاه-رفتار-می‌شود.)' => 'ميزبان-متعهد-مي شود-در-صورت-عدم-مراجعه-مهمان-به-اقامتكاه-در-التاريخ-رزرو-شده،-اقامتكاه-تا-بايان-مدت-رزرو-شده،-براي-مهمان-خالي-خواهد-ماند،-همجنين-مهمان-مي بذيرفض-كه-در-اين-شرايط-هيج -مبلغي-به-وي-مسترفض-نخواهد-شد.-(در-صورت-درخواست-لغو-رزرو-توسط-مهمان،-مطابق-قوانين-كنسلي-آن-اقامتكاه-رفتار-مي شود.)',
    'گیلند ملک پلتفرمی جهت نمایش اطلاعات تجربه طبق اطلاعات اعلامی میزبان است در صورت مغایرت در اطلاعات وارد شده گیلند ملک هیچگونه مسئولیتی نخواهد داشت.' => 'كيلند ملك بلتفرمي جهت عرض المعلومات تجربه طبق المعلومات اعلامي ميزبان است در صورت مغايرت در المعلومات وارفض شده كيلند ملك هيجكونه مسئوليتي نخواهد داشت.',
    'گیلند-ملک-پلتفرمی-جهت-نمایش-اطلاعات-تجربه-طبق-اطلاعات-اعلامی-میزبان-است-در-صورت-مغایرت-در-اطلاعات-وارد-شده-گیلند-ملک-هیچگونه-مسئولیتی-نخواهد-داشت.' => 'كيلند-ملك-بلتفرمي-جهت-عرض-المعلومات-تجربه-طبق-المعلومات-اعلامي-ميزبان-است-در-صورت-مغايرت-در-المعلومات-وارفض-شده-كيلند-ملك-هيجكونه-مسئوليتي-نخواهد-داشت.',
    'تجربه به عنوان یک پلتفرم در بستر اینترنت جهت خلق تجربه شایسته سفر است.' => 'تجربه به العنوان يك بلتفرم در بستر اينترنت جهت خلق تجربه شايسته سفر است.',
    'تجربه-به-عنوان-یک-پلتفرم-در-بستر-اینترنت-جهت-خلق-تجربه-شایسته-سفر-است.' => 'تجربه-به-العنوان-يك-بلتفرم-در-بستر-اينترنت-جهت-خلق-تجربه-شايسته-سفر-است.',
    'نحوه تعامل مهمان با میزبان جهت خلق یک تجربه به نحوه ارتباط بین آنان بستگی دارد. گیلند ملک این اختیار را به میزبان داده است که در وب سایت و اعلام تجربه به معرفی خود پرداخته و مهمان با آشنایی نسبت به میزبان نسبت به پذیرش تجربه جدید اقدام نماید. گیلند ملک نهایت تلاش خود را در خصوص بررسی نحوه فعالیت میزبان و ارایه تجربه بعمل می آورد. با توجه به اینکه گیلند ملک یک پلتفرم جهت شناساندن تجربه های جدید است، مجری یا نماینده میزبان محسوب نمی شود و هیچگونه مسئولیتی در خصوص صحت تجربه میزبان به مهمان ارایه نداده و به مهمان اختیار می دهد تا در خصوص همراهی با میزبان تصمیم گیری نماید. در صورتی که از سوی مهمان اعلام گردد که میزبان خارج از تعهدات خود عمل نموده و یا شونات مذهبی، قانونی و اخلاقی را رعایت ننموده نسبت به قطع دسترسی میزبان اقدام می نماید.' => 'نحوه تعامل مهمان با ميزبان جهت خلق يك تجربه به نحوه ارتباط بين آنان بستكي دارفض. كيلند ملك اين اختيار را به ميزبان داده است كه در وب سايت و اعلام تجربه به معرفي خود برفضاخته و مهمان با آشنايي نسبت به ميزبان نسبت به بذيرش تجربه جديد اقدام نمايد. كيلند ملك نهايت تلاش خود را در خصوص بررسي نحوه نشطيت ميزبان و ارايه تجربه بعمل مي آورفض. با توجه به اينكه كيلند ملك يك بلتفرم جهت شناساندن تجربه هاي جديد است، مجري يا نماينده ميزبان محسوب نمي شود و هيجكونه مسئوليتي در خصوص صحت تجربه ميزبان به مهمان ارايه نداده و به مهمان اختيار مي دهد تا در خصوص همراهي با ميزبان تصميم كيري نمايد. در صورتي كه از سوي مهمان اعلام كرفضد كه ميزبان خارج از تعهدات خود عمل نموده و يا شونات مذهبي، قانوني و اخلاقي را رعايت ننموده نسبت به قطع دسترسي ميزبان اقدام مي نمايد.',
    'نحوه-تعامل-مهمان-با-میزبان-جهت-خلق-یک-تجربه-به-نحوه-ارتباط-بین-آنان-بستگی-دارد.-گیلند-ملک-این-اختیار-را-به-میزبان-داده-است-که-در-وب-سایت-و-اعلام-تجربه-به-معرفی-خود-پرداخته-و-مهمان-با-آشنایی-نسبت-به-میزبان-نسبت-به-پذیرش-تجربه-جدید-اقدام-نماید.-گیلند-ملک-نهایت-تلاش-خود-را-در-خصوص-بررسی-نحوه-فعالیت-میزبان-و-ارایه-تجربه-بعمل-می-آورد.-با-توجه-به-اینکه-گیلند-ملک-یک-پلتفرم-جهت-شناساندن-تجربه-های-جدید-است،-مجری-یا-نماینده-میزبان-محسوب-نمی-شود-و-هیچگونه-مسئولیتی-در-خصوص-صحت-تجربه-میزبان-به-مهمان-ارایه-نداده-و-به-مهمان-اختیار-می-دهد-تا-در-خصوص-همراهی-با-میزبان-تصمیم-گیری-نماید.-در-صورتی-که-از-سوی-مهمان-اعلام-گردد-که-میزبان-خارج-از-تعهدات-خود-عمل-نموده-و-یا-شونات-مذهبی،-قانونی-و-اخلاقی-را-رعایت-ننموده-نسبت-به-قطع-دسترسی-میزبان-اقدام-می-نماید.' => 'نحوه-تعامل-مهمان-با-ميزبان-جهت-خلق-يك-تجربه-به-نحوه-ارتباط-بين-آنان-بستكي-دارفض.-كيلند-ملك-اين-اختيار-را-به-ميزبان-داده-است-كه-در-وب-سايت-و-اعلام-تجربه-به-معرفي-خود-برفضاخته-و-مهمان-با-آشنايي-نسبت-به-ميزبان-نسبت-به-بذيرش-تجربه-جديد-اقدام-نمايد.-كيلند-ملك-نهايت-تلاش-خود-را-در-خصوص-بررسي-نحوه-نشطيت-ميزبان-و-ارايه-تجربه-بعمل-مي-آورفض.-با-توجه-به-اينكه-كيلند-ملك-يك-بلتفرم-جهت-شناساندن-تجربه-هاي-جديد-است،-مجري-يا-نماينده-ميزبان-محسوب-نمي-شود-و-هيجكونه-مسئوليتي-در-خصوص-صحت-تجربه-ميزبان-به-مهمان-ارايه-نداده-و-به-مهمان-اختيار-مي-دهد-تا-در-خصوص-همراهي-با-ميزبان-تصميم-كيري-نمايد.-در-صورتي-كه-از-سوي-مهمان-اعلام-كرفضد-كه-ميزبان-خارج-از-تعهدات-خود-عمل-نموده-و-يا-شونات-مذهبي،-قانوني-و-اخلاقي-را-رعايت-ننموده-نسبت-به-قطع-دسترسي-ميزبان-اقدام-مي-نمايد.',
    'میزبان متعهد هست که تجربه را عینا مطابق آنچه در وب سایت اعلام نموده ارایه دهد، در غیر اینصورت در صورت اعلام مهمان یا احراز آن توسط گیلند ملک ، به میزبان اخطارداده خواهد شد و در مواردی به تشخیص گیلند ملک برسد دسترسی میزبان قطع خواهد شد.' => 'ميزبان متعهد هست كه تجربه را عينا مطابق آنجه در وب سايت اعلام نموده ارايه دهد، در غير اينصورت در صورت اعلام مهمان يا احراز آن توسط كيلند ملك ، به ميزبان اخطأرفضاده خواهد شد و در موارفضي به تشخيص كيلند ملك برسد دسترسي ميزبان قطع خواهد شد.',
    'میزبان-متعهد-هست-که-تجربه-را-عینا-مطابق-آنچه-در-وب-سایت-اعلام-نموده-ارایه-دهد،-در-غیر-اینصورت-در-صورت-اعلام-مهمان-یا-احراز-آن-توسط-گیلند-ملک-،-به-میزبان-اخطارداده-خواهد-شد-و-در-مواردی-به-تشخیص-گیلند-ملک-برسد-دسترسی-میزبان-قطع-خواهد-شد.' => 'ميزبان-متعهد-هست-كه-تجربه-را-عينا-مطابق-آنجه-در-وب-سايت-اعلام-نموده-ارايه-دهد،-در-غير-اينصورت-در-صورت-اعلام-مهمان-يا-احراز-آن-توسط-كيلند-ملك-،-به-ميزبان-اخطأرفضاده-خواهد-شد-و-در-موارفضي-به-تشخيص-كيلند-ملك-برسد-دسترسي-ميزبان-قطع-خواهد-شد.',
    'مهمان می بایست فرهنگ بومی، هنجارهای جامعه میزبان اعم از فرهنگ، سنن، زبان، گویش، لباس، عقاید و… را ارج نهاده و به عقاید میزبان احترام گذارد. مهمان می بایست پوشش مناسب را در تجربه ها رعایت نموده و از انجام اعمالی که در عرف و قانون ممنوع یا غیراخلاقی است پرهیز کنید در غیر این صورت گیلند ملک هیچگونه مسولیتی دراین خصوص نخواهد داشت و می تواند نسبت به قطع دسترسی مهمان در خصوص رزرو های آتی تجربه اقدام نماید.' => 'مهمان مي بايست فرهن / تأمينك بومي، هنجارهاي جامعه ميزبان اعم از فرهن / تأمينك، سنن، زبان، كويش، لباس، عقايد و… را ارج نهاده و به عقايد ميزبان احترام كذارفض. مهمان مي بايست بوشش مناسب را در تجربه ها رعايت نموده و از انجام اعمالي كه در عرف و قانون ممنوع يا غيراخلاقي است برهيز كنيد در غير اين صورت كيلند ملك هيجكونه مسوليتي دراين خصوص نخواهد داشت و مي تواند نسبت به قطع دسترسي مهمان در خصوص رزرو هاي آتي تجربه اقدام نمايد.',
    'مهمان-می-بایست-فرهنگ-بومی،-هنجارهای-جامعه-میزبان-اعم-از-فرهنگ،-سنن،-زبان،-گویش،-لباس،-عقاید-و…-را-ارج-نهاده-و-به-عقاید-میزبان-احترام-گذارد.-مهمان-می-بایست-پوشش-مناسب-را-در-تجربه-ها-رعایت-نموده-و-از-انجام-اعمالی-که-در-عرف-و-قانون-ممنوع-یا-غیراخلاقی-است-پرهیز-کنید-در-غیر-این-صورت-گیلند-ملک-هیچگونه-مسولیتی-دراین-خصوص-نخواهد-داشت-و-می-تواند-نسبت-به-قطع-دسترسی-مهمان-در-خصوص-رزرو-های-آتی-تجربه-اقدام-نماید.' => 'مهمان-مي-بايست-فرهن / تأمينك-بومي،-هنجارهاي-جامعه-ميزبان-اعم-از-فرهن / تأمينك،-سنن،-زبان،-كويش،-لباس،-عقايد-و…-را-ارج-نهاده-و-به-عقايد-ميزبان-احترام-كذارفض.-مهمان-مي-بايست-بوشش-مناسب-را-در-تجربه-ها-رعايت-نموده-و-از-انجام-اعمالي-كه-در-عرف-و-قانون-ممنوع-يا-غيراخلاقي-است-برهيز-كنيد-در-غير-اين-صورت-كيلند-ملك-هيجكونه-مسوليتي-دراين-خصوص-نخواهد-داشت-و-مي-تواند-نسبت-به-قطع-دسترسي-مهمان-در-خصوص-رزرو-هاي-آتي-تجربه-اقدام-نمايد.',
    'حضور افراد زیر ۱۸ سال در تمامی برنامه‌های تجربه منوط به همراهی و یا اجازه کتبی سرپرست فرد می‌باشد.' => 'حضور افراد زير ۱۸ سال در تمامي برالاسمه هاي تجربه منوط به همراهي و يا اجازه كتبي سربرست فرفض مي باشد.',
    'حضور-افراد-زیر-۱۸-سال-در-تمامی-برنامه‌های-تجربه-منوط-به-همراهی-و-یا-اجازه-کتبی-سرپرست-فرد-می‌باشد.' => 'حضور-افراد-زير-۱۸-سال-در-تمامي-برالاسمه هاي-تجربه-منوط-به-همراهي-و-يا-اجازه-كتبي-سربرست-فرفض-مي باشد.',
    'مهمان می بایست قبل از شروع تجربه به ضوابط و تجربیات اعلامی از سوی میزبان توجه نموده و لوازم ضروری و پیشنهادی سفر و کسب سایر اطلاعات کافی در خصوص سفر را از میزبان جویا شود.' => 'مهمان مي بايست قبل از شروع تجربه به ضوابط و تجربيات اعلامي از سوي ميزبان توجه نموده و لوازم ضروري و بيشنهادي سفر و كسب ساير المعلومات كافي در خصوص سفر را از ميزبان جويا شود.',
    'مهمان-می-بایست-قبل-از-شروع-تجربه-به-ضوابط-و-تجربیات-اعلامی-از-سوی-میزبان-توجه-نموده-و-لوازم-ضروری-و-پیشنهادی-سفر-و-کسب-سایر-اطلاعات-کافی-در-خصوص-سفر-را-از-میزبان-جویا-شود.' => 'مهمان-مي-بايست-قبل-از-شروع-تجربه-به-ضوابط-و-تجربيات-اعلامي-از-سوي-ميزبان-توجه-نموده-و-لوازم-ضروري-و-بيشنهادي-سفر-و-كسب-ساير-المعلومات-كافي-در-خصوص-سفر-را-از-ميزبان-جويا-شود.',
    'کنسلی هر تجربه توسط مهمان به شرایط تعیین شده از سوی میزبان بستگی دارد. مهمان همزمان با رزرو یک تجربه تمامی شرایط اعلامی از سوی گیلند ملک و میزبان را می پذیرد و با آگاهی کامل در خصوص رزرو تجربه اقدام می نماید.' => 'كنسلي هر تجربه توسط مهمان به شرايط تعيين شده از سوي ميزبان بستكي دارفض. مهمان همالوقت با رزرو يك تجربه تمامي شرايط اعلامي از سوي كيلند ملك و ميزبان را مي بذيرفض و با آكاهي كامل در خصوص رزرو تجربه اقدام مي نمايد.',
    'کنسلی-هر-تجربه-توسط-مهمان-به-شرایط-تعیین-شده-از-سوی-میزبان-بستگی-دارد.-مهمان-همزمان-با-رزرو-یک-تجربه-تمامی-شرایط-اعلامی-از-سوی-گیلند-ملک-و-میزبان-را-می-پذیرد-و-با-آگاهی-کامل-در-خصوص-رزرو-تجربه-اقدام-می-نماید.' => 'كنسلي-هر-تجربه-توسط-مهمان-به-شرايط-تعيين-شده-از-سوي-ميزبان-بستكي-دارفض.-مهمان-همالوقت-با-رزرو-يك-تجربه-تمامي-شرايط-اعلامي-از-سوي-كيلند-ملك-و-ميزبان-را-مي-بذيرفض-و-با-آكاهي-كامل-در-خصوص-رزرو-تجربه-اقدام-مي-نمايد.',
    'مهمان متعهد است قوانین اشاره شده توسط میزبان در استفاده از تجربه احترام گذارد و اجرا نماید در غیر اینصورت مسئولیت نقض قواعد برعهده مهمان است و گیلند ملک در این خصوص مسئولیتی نخواهد داشت. به طور مثال در صورتی که میزبان شرایط سنی مشخصی را برای تجربه در نظر گرفته و مهمان آن شرایط را رعایت ننماید، مسئولیت اتفاقات رخ داده با مهمان است.' => 'مهمان متعهد است قوانين اشاره شده توسط ميزبان در استفاده از تجربه احترام كذارفض و اجرا نمايد در غير اينصورت مسئوليت نقض قواعد برعهده مهمان است و كيلند ملك در اين خصوص مسئوليتي نخواهد داشت. به طور مثال در صورتي كه ميزبان شرايط سني مشخصي را براي تجربه در نظر كرفته و مهمان آن شرايط را رعايت ننمايد، مسئوليت اتفاقات رخ داده با مهمان است.',
    'مهمان-متعهد-است-قوانین-اشاره-شده-توسط-میزبان-در-استفاده-از-تجربه-احترام-گذارد-و-اجرا-نماید-در-غیر-اینصورت-مسئولیت-نقض-قواعد-برعهده-مهمان-است-و-گیلند-ملک-در-این-خصوص-مسئولیتی-نخواهد-داشت.-به-طور-مثال-در-صورتی-که-میزبان-شرایط-سنی-مشخصی-را-برای-تجربه-در-نظر-گرفته-و-مهمان-آن-شرایط-را-رعایت-ننماید،-مسئولیت-اتفاقات-رخ-داده-با-مهمان-است.' => 'مهمان-متعهد-است-قوانين-اشاره-شده-توسط-ميزبان-در-استفاده-از-تجربه-احترام-كذارفض-و-اجرا-نمايد-در-غير-اينصورت-مسئوليت-نقض-قواعد-برعهده-مهمان-است-و-كيلند-ملك-در-اين-خصوص-مسئوليتي-نخواهد-داشت.-به-طور-مثال-در-صورتي-كه-ميزبان-شرايط-سني-مشخصي-را-براي-تجربه-در-نظر-كرفته-و-مهمان-آن-شرايط-را-رعايت-ننمايد،-مسئوليت-اتفاقات-رخ-داده-با-مهمان-است.',
    'گیلند ملک تضمین می‌کند تا با تکمیل فرآیند خرید از سوی کاربر و دریافت نامه اقامت (واچر) ، بتوانید به راحتی در هتل و یا اقامتگاه مورد نظر، پذیرش شده و از امکانات آن بهره‌مند شوید. در مواردی نادر ممکن است به دلایل مختلف از جمله مشکلات اعلام شده از طرف اقامتگاه نظیر خرابی‌ها و حوادث طبیعی، اشتباهات انسانی همچون اشتباه فاحش در مبلغ اعلامی و همچنین موارد امنیتی مانند ورود مقامات بلندپایه، رزرو ثبت شده با مشکل مواجهه شود، در این‌گونه موارد گیلند ملک تمام تلاش خود را می‌کند تا برای مهمانان خود، هتل و یا اقامتگاهی مشابه با واحد رزرو شده فعلی در نظر گیرد و درصورت عدم موفقیت در جلب رضایت مهمان (مسافر)، مبلغ را به‌صورت کامل بازگرداند و امتیاز ویژه ای را برای رزرو آتی وی منظور کند.' => 'كيلند ملك تضمين مي كند تا با تكميل فرآيند شراء از سوي كاربر و استلام الاسمه اقامت (واجر) ، بتوانيد به راحتي در هتل و يا اقامتكاه مورفض نظر، بذيرش شده و از امكانات آن بهره مند شويد. در موارفضي نادر ممكن است به دلايل مختلف از جمله مشكلات اعلام شده از طرف اقامتكاه نظير خرابي ها و حوادث طبيعي، اشتباهات انساني همجون اشتباه فاحش در مبلغ اعلامي و همجنين موارفض امنيتي مانند تسجيل الدخول مقامات بلندبايه، رزرو إرسال شده با مشكل مواجهه شود، در اين كونه موارفض كيلند ملك تمام تلاش خود را مي كند تا براي مهمانان خود، هتل و يا اقامتكاهي مشابه با واحد رزرو شده فعلي در نظر كيرفض و درصورت عدم نجاح در جلب رضايت مهمان (مسافر)، مبلغ را به صورت كامل بازكرفضاند و امتياز ويزه اي را براي رزرو آتي وي منظور كند.',
    'گیلند-ملک-تضمین-می‌کند-تا-با-تکمیل-فرآیند-خرید-از-سوی-کاربر-و-دریافت-نامه-اقامت-(واچر)-،-بتوانید-به-راحتی-در-هتل-و-یا-اقامتگاه-مورد-نظر،-پذیرش-شده-و-از-امکانات-آن-بهره‌مند-شوید.-در-مواردی-نادر-ممکن-است-به-دلایل-مختلف-از-جمله-مشکلات-اعلام-شده-از-طرف-اقامتگاه-نظیر-خرابی‌ها-و-حوادث-طبیعی،-اشتباهات-انسانی-همچون-اشتباه-فاحش-در-مبلغ-اعلامی-و-همچنین-موارد-امنیتی-مانند-ورود-مقامات-بلندپایه،-رزرو-ثبت-شده-با-مشکل-مواجهه-شود،-در-این‌گونه-موارد-گیلند-ملک-تمام-تلاش-خود-را-می‌کند-تا-برای-مهمانان-خود،-هتل-و-یا-اقامتگاهی-مشابه-با-واحد-رزرو-شده-فعلی-در-نظر-گیرد-و-درصورت-عدم-موفقیت-در-جلب-رضایت-مهمان-(مسافر)،-مبلغ-را-به‌صورت-کامل-بازگرداند-و-امتیاز-ویژه-ای-را-برای-رزرو-آتی-وی-منظور-کند.' => 'كيلند-ملك-تضمين-مي كند-تا-با-تكميل-فرآيند-شراء-از-سوي-كاربر-و-استلام-الاسمه-اقامت-(واجر)-،-بتوانيد-به-راحتي-در-هتل-و-يا-اقامتكاه-مورفض-نظر،-بذيرش-شده-و-از-امكانات-آن-بهره مند-شويد.-در-موارفضي-نادر-ممكن-است-به-دلايل-مختلف-از-جمله-مشكلات-اعلام-شده-از-طرف-اقامتكاه-نظير-خرابي ها-و-حوادث-طبيعي،-اشتباهات-انساني-همجون-اشتباه-فاحش-در-مبلغ-اعلامي-و-همجنين-موارفض-امنيتي-مانند-تسجيل الدخول-مقامات-بلندبايه،-رزرو-إرسال-شده-با-مشكل-مواجهه-شود،-در-اين كونه-موارفض-كيلند-ملك-تمام-تلاش-خود-را-مي كند-تا-براي-مهمانان-خود،-هتل-و-يا-اقامتكاهي-مشابه-با-واحد-رزرو-شده-فعلي-در-نظر-كيرفض-و-درصورت-عدم-نجاح-در-جلب-رضايت-مهمان-(مسافر)،-مبلغ-را-به صورت-كامل-بازكرفضاند-و-امتياز-ويزه-اي-را-براي-رزرو-آتي-وي-منظور-كند.',
    'حفظ و نگهداری از رمز عبور بر عهده کاربران است و برای جلوگیری از هر گونه سوء استفاده احتمالی، کاربران نباید آن را برای شخص دیگری افشاء نمایند .تمامی اطلاعات کاربران نزد گیلند ملک محرمانه تلقی می‌شود و گیلند ملک متعهد می‌شود این اطلاعات را در اختیار شخص دیگر قرار ندهد، مگر در مواقعی که این اطلاعات از جانب مقامات قضایی ذیصلاح با داشتن حکم قانونی درخواست شود.' => 'حفظ و نكهداري از كلمة المرور بر عهده كاربران است و براي جلوكيري از هر كونه سوء استفاده احتمالي، كاربران نبايد آن را براي شخص ديكري افشاء نمايند .تمامي المعلومات كاربران نزد كيلند ملك محرمانه تلقي مي شود و كيلند ملك متعهد مي شود اين المعلومات را در اختيار شخص ديكر قرار ندهد، مكر در مواقعي كه اين المعلومات از جانب مقامات قضايي ذيصلاح با داشتن حكم قانوني درخواست شود.',
    'حفظ-و-نگهداری-از-رمز-عبور-بر-عهده-کاربران-است-و-برای-جلوگیری-از-هر-گونه-سوء-استفاده-احتمالی،-کاربران-نباید-آن-را-برای-شخص-دیگری-افشاء-نمایند-.تمامی-اطلاعات-کاربران-نزد-گیلند-ملک-محرمانه-تلقی-می‌شود-و-گیلند-ملک-متعهد-می‌شود-این-اطلاعات-را-در-اختیار-شخص-دیگر-قرار-ندهد،-مگر-در-مواقعی-که-این-اطلاعات-از-جانب-مقامات-قضایی-ذیصلاح-با-داشتن-حکم-قانونی-درخواست-شود.' => 'حفظ-و-نكهداري-از-رمز-عبور-بر-عهده-كاربران-است-و-براي-جلوكيري-از-هر-كونه-سوء-استفاده-احتمالي،-كاربران-نبايد-آن-را-براي-شخص-ديكري-افشاء-نمايند-.تمامي-المعلومات-كاربران-نزد-كيلند-ملك-محرمانه-تلقي-مي شود-و-كيلند-ملك-متعهد-مي شود-اين-المعلومات-را-در-اختيار-شخص-ديكر-قرار-ندهد،-مكر-در-مواقعي-كه-اين-المعلومات-از-جانب-مقامات-قضايي-ذيصلاح-با-داشتن-حكم-قانوني-درخواست-شود.',
    'در صورت بروز مشکلات احتمالی بین میزبان و مهمان، تیم گیلند ملک تمامی تلاش خود را جهت برطرف نمودن مشکلات به عمل خواهد آورد.' => 'در صورت بروز مشكلات احتمالي بين ميزبان و مهمان، تيم كيلند ملك تمامي تلاش خود را جهت برطرف نمودن مشكلات به عمل خواهد آورفض.',
    'در-صورت-بروز-مشکلات-احتمالی-بین-میزبان-و-مهمان،-تیم-گیلند-ملک-تمامی-تلاش-خود-را-جهت-برطرف-نمودن-مشکلات-به-عمل-خواهد-آورد.' => 'در-صورت-بروز-مشكلات-احتمالي-بين-ميزبان-و-مهمان،-تيم-كيلند-ملك-تمامي-تلاش-خود-را-جهت-برطرف-نمودن-مشكلات-به-عمل-خواهد-آورفض.',
    'تیم گیلند ملک برای شما دوست عزیز سفر خوب همراه با لذت و شادی را آرزومند است.' => 'تيم كيلند ملك براي شما دوست عزيز سفر خوب همراه با لذت و شادي را آرزومند است.',
    'تیم-گیلند-ملک-برای-شما-دوست-عزیز-سفر-خوب-همراه-با-لذت-و-شادی-را-آرزومند-است.' => 'تيم-كيلند-ملك-براي-شما-دوست-عزيز-سفر-خوب-همراه-با-لذت-و-شادي-را-آرزومند-است.',
    'پیامک' => 'رسالةک',
    'rent != 0) هر شب از' => 'rent != 0) هر شب از',
    'rent-!=-0)-هر-شب-از' => 'rent != 0) هر شب از',
    'املاک گیلان، خرید ملک در رضوانشهر' => 'املاك كيلان، شراء ملك در رضوانالمدينة',
    'املاک-گیلان،-خرید-ملک-در-رضوانشهر' => 'املاك-كيلان،-شراء-ملك-در-رضوانالمدينة',
    'چرا رضوانشهر گیلان؟' => 'جرا رضوانالمدينة كيلان؟',
    'چرا-رضوانشهر-گیلان؟' => 'جرا-رضوانالمدينة-كيلان؟',
    'رضوانشهر از زیباترین شهرستان‌های استان گیلان می باشد که فاصله‌ی کمی با رشت دارد. این شهربهشت بین رشته کوه‌های تالش و سواحل دریای خزرقرار گرفته است و بخاطر اینکه جنگل و دریا دررضوانشهر در فاصله بسیار کمی از همدیگر قرار دارند، با سفر به رضوانشهرگیلان و یا سرمایه گذاری هم از دریای زیبا استفاده می کنید و هم از طبیعت بکر وجنگل های گیسوم بهره می برید. شهرهایی چون خلخال، تالش، صومعه سرا، ماسال و بندر انزلی در مجاورت رضوانشهر قرار دارند.رضوانشهرگیلان هر ساله میزبان تعداد زیادی از مسافران از سراسر کشور می باشد و همین امر باعث شده تا افراد زیادی به رضوانشهر مهاجرت کنند و بازار خرید و فروش زمین و ویلا تغییر کند.' => 'رضوانالمدينة از زيباترين المدينةستان هاي الإمارة كيلان مي باشد كه فاصله ي كمي با رشت دارفض. اين المدينةبهشت بين رشته كوه هاي تالش و سواحل درياي خزرقرار كرفته است و بخاطر اينكه جنكل و دريا دررضوانالمدينة در فاصله بسيار كمي از همديكر قرار دارند، با سفر به رضوانالمدينةكيلان و يا سرمايه كذاري هم از درياي زيبا استفاده مي كنيد و هم از طبيعت بكر وجنكل هاي كيسوم بهره مي بريد. المدينةهايي جون خلخال، تالش، صومعه سرا، ماسال و بندر انزلي در مجاورت رضوانالمدينة قرار دارند.رضوانالمدينةكيلان هر ساله ميزبان تعداد زيادي از مسافران از سراسر كشور مي باشد و همين امر باعث شده تا افراد زيادي به رضوانالمدينة مهاجرت كنند و بازار شراء و بيع أرض و فيلا تغيير كند.',
    'رضوانشهر-از-زیباترین-شهرستان‌های-استان-گیلان-می-باشد-که-فاصله‌ی-کمی-با-رشت-دارد.-این-شهربهشت-بین-رشته-کوه‌های-تالش-و-سواحل-دریای-خزرقرار-گرفته-است-و-بخاطر-اینکه-جنگل-و-دریا-دررضوانشهر-در-فاصله-بسیار-کمی-از-همدیگر-قرار-دارند،-با-سفر-به-رضوانشهرگیلان-و-یا-سرمایه-گذاری-هم-از-دریای-زیبا-استفاده-می-کنید-و-هم-از-طبیعت-بکر-وجنگل-های-گیسوم-بهره-می-برید.-شهرهایی-چون-خلخال،-تالش،-صومعه-سرا،-ماسال-و-بندر-انزلی-در-مجاورت-رضوانشهر-قرار-دارند.رضوانشهرگیلان-هر-ساله-میزبان-تعداد-زیادی-از-مسافران-از-سراسر-کشور-می-باشد-و-همین-امر-باعث-شده-تا-افراد-زیادی-به-رضوانشهر-مهاجرت-کنند-و-بازار-خرید-و-فروش-زمین-و-ویلا-تغییر-کند.' => 'رضوانالمدينة-از-زيباترين-المدينةستان هاي-الإمارة-كيلان-مي-باشد-كه-فاصله ي-كمي-با-رشت-دارفض.-اين-المدينةبهشت-بين-رشته-كوه هاي-تالش-و-سواحل-درياي-خزرقرار-كرفته-است-و-بخاطر-اينكه-جنكل-و-دريا-دررضوانالمدينة-در-فاصله-بسيار-كمي-از-همديكر-قرار-دارند،-با-سفر-به-رضوانالمدينةكيلان-و-يا-سرمايه-كذاري-هم-از-درياي-زيبا-استفاده-مي-كنيد-و-هم-از-طبيعت-بكر-وجنكل-هاي-كيسوم-بهره-مي-بريد.-المدينةهايي-جون-خلخال،-تالش،-صومعه-سرا،-ماسال-و-بندر-انزلي-در-مجاورت-رضوانالمدينة-قرار-دارند.رضوانالمدينةكيلان-هر-ساله-ميزبان-تعداد-زيادي-از-مسافران-از-سراسر-كشور-مي-باشد-و-همين-امر-باعث-شده-تا-افراد-زيادي-به-رضوانالمدينة-مهاجرت-كنند-و-بازار-شراء-و-بيع-أرض-و-فيلا-تغيير-كند.',
    'خرید و فروش و قیمت خانه و ویلا در رضوانشهر گیلان چگونه است؟' => 'شراء و بيع و السعر خانه و فيلا در رضوانالمدينة كيلان جكونه است؟',
    'خرید-و-فروش-و-قیمت-خانه-و-ویلا-در-رضوانشهر-گیلان-چگونه-است؟' => 'شراء-و-بيع-و-السعر-خانه-و-فيلا-در-رضوانالمدينة-كيلان-جكونه-است؟',
    'با توجه به مهاجرت های فراوان و افزایش جمعیت دررضوانشهرگیلان باعث شده است تا بازار ملک این منطقه رشد چشمگیری داشته باشد و افراد زیادی دنبال خرید خانه و ویلا در رضوانشهر و روستاهای اطراف آن باشند تا از این طبیعت بکر و دریای زیبای خزر و آرامش شمال لذت ببرند. خرید و فروش املاک در رضوانشهر گیلان در سال های اخیر به سطح بالاتری ارتقا پیدا کرده است. برای اینکه بتوانید قیمت خانه و ویلا دررضوانشهرگیلان بدست بیاورید حتما از کارشناسان و مشاورین املاک مطمعن کمک بگیرید.' => 'با توجه به مهاجرت هاي فراوان و افزايش جمعيت دررضوانالمدينةكيلان باعث شده است تا بازار ملك اين المنطقة رشد جشمكيري داشته باشد و افراد زيادي دنبال شراء خانه و فيلا در رضوانالمدينة و روستاهاي اطراف آن باشند تا از اين طبيعت بكر و درياي زيباي خزر و آرامش شمال لذت ببرند. شراء و بيع املاك در رضوانالمدينة كيلان در سال هاي اخير به سطح بالاتري ارتقا بيدا كرفضه است. براي اينكه بتوانيد السعر خانه و فيلا دررضوانالمدينةكيلان بدست بياوريد حتما از خبيران و مستشارين املاك مطمعن كمك بكيريد.',
    'با-توجه-به-مهاجرت-های-فراوان-و-افزایش-جمعیت-دررضوانشهرگیلان-باعث-شده-است-تا-بازار-ملک-این-منطقه-رشد-چشمگیری-داشته-باشد-و-افراد-زیادی-دنبال-خرید-خانه-و-ویلا-در-رضوانشهر-و-روستاهای-اطراف-آن-باشند-تا-از-این-طبیعت-بکر-و-دریای-زیبای-خزر-و-آرامش-شمال-لذت-ببرند.-خرید-و-فروش-املاک-در-رضوانشهر-گیلان-در-سال-های-اخیر-به-سطح-بالاتری-ارتقا-پیدا-کرده-است.-برای-اینکه-بتوانید-قیمت-خانه-و-ویلا-دررضوانشهرگیلان-بدست-بیاورید-حتما-از-کارشناسان-و-مشاورین-املاک-مطمعن-کمک-بگیرید.' => 'با-توجه-به-مهاجرت-هاي-فراوان-و-افزايش-جمعيت-دررضوانالمدينةكيلان-باعث-شده-است-تا-بازار-ملك-اين-المنطقة-رشد-جشمكيري-داشته-باشد-و-افراد-زيادي-دنبال-شراء-خانه-و-فيلا-در-رضوانالمدينة-و-روستاهاي-اطراف-آن-باشند-تا-از-اين-طبيعت-بكر-و-درياي-زيباي-خزر-و-آرامش-شمال-لذت-ببرند.-شراء-و-بيع-املاك-در-رضوانالمدينة-كيلان-در-سال-هاي-اخير-به-سطح-بالاتري-ارتقا-بيدا-كرفضه-است.-براي-اينكه-بتوانيد-السعر-خانه-و-فيلا-دررضوانالمدينةكيلان-بدست-بياوريد-حتما-از-خبيران-و-مستشارين-املاك-مطمعن-كمك-بكيريد.',
    'قیمت رهن و اجاره آپارتمان در رضوانشهرگیلان چگونه است؟' => 'السعر رهن / تأمين و إيجار شقة در رضوانالمدينةكيلان جكونه است؟',
    'قیمت-رهن-و-اجاره-آپارتمان-در-رضوانشهرگیلان-چگونه-است؟' => 'السعر-رهن / تأمين-و-إيجار-شقة-در-رضوانالمدينةكيلان-جكونه-است؟',
    'قیمت آپارتمان در رضوانشهر بستگی به نوع آپارتمان، متراژ ساختمان و امکانات ساختمان و اینکه چندسال ساخت است و دسترسی راحت تر به مراکز رفاهی، درمانی،خدماتی و گردشگری تعیین می گردد. همچنین بودن امکانات در نزدیکی آپارتمان و موقعبت مکانی در قیمت رهن و اجاره آپارتمان تاثیر می گذارد. توصیه می شود برای قیمت رهن و اجاره آپارتمان در رضوانشهر از افراد متخصص همان منطقه و مشاورین املاک معتبر کمک بگیرید.' => 'السعر شقة در رضوانالمدينة بستكي به نوع شقة، المساحة ساختمان و امكانات ساختمان و اينكه جندسنة البناء است و دسترسي راحت تر به مراكز رفاهي، درماني،خدماتي و كرفضشكري تعيين مي كرفضد. همجنين بودن امكانات در نزديكي شقة و موقعبت مكاني در السعر رهن / تأمين و إيجار شقة تاثير مي كذارفض. توصيه مي شود براي السعر رهن / تأمين و إيجار شقة در رضوانالمدينة از افراد متخصص همان المنطقة و مستشارين املاك معتبر كمك بكيريد.',
    'قیمت-آپارتمان-در-رضوانشهر-بستگی-به-نوع-آپارتمان،-متراژ-ساختمان-و-امکانات-ساختمان-و-اینکه-چندسال-ساخت-است-و-دسترسی-راحت-تر-به-مراکز-رفاهی،-درمانی،خدماتی-و-گردشگری-تعیین-می-گردد.-همچنین-بودن-امکانات-در-نزدیکی-آپارتمان-و-موقعبت-مکانی-در-قیمت-رهن-و-اجاره-آپارتمان-تاثیر-می-گذارد.-توصیه-می-شود-برای-قیمت-رهن-و-اجاره-آپارتمان-در-رضوانشهر-از-افراد-متخصص-همان-منطقه-و-مشاورین-املاک-معتبر-کمک-بگیرید.' => 'السعر-شقة-در-رضوانالمدينة-بستكي-به-نوع-شقة،-المساحة-ساختمان-و-امكانات-ساختمان-و-اينكه-جندسال-ساخت-است-و-دسترسي-راحت-تر-به-مراكز-رفاهي،-درماني،خدماتي-و-كرفضشكري-تعيين-مي-كرفضد.-همجنين-بودن-امكانات-در-نزديكي-شقة-و-موقعبت-مكاني-در-السعر-رهن / تأمين-و-إيجار-شقة-تاثير-مي-كذارفض.-توصيه-مي-شود-براي-السعر-رهن / تأمين-و-إيجار-شقة-در-رضوانالمدينة-از-افراد-متخصص-همان-المنطقة-و-مستشارين-املاك-معتبر-كمك-بكيريد.',
    'قیمت خرید و فروش اپارتمان در رضوانشهرگیلان' => 'السعر شراء و بيع ابارتمان در رضوانالمدينةكيلان',
    'قیمت-خرید-و-فروش-اپارتمان-در-رضوانشهرگیلان' => 'السعر-شراء-و-بيع-ابارتمان-در-رضوانالمدينةكيلان',
    'آپارتمان در رضوانشهرگیلان از نظر اقتصادی مقرون به صرفه تر می باشد و با توجه به امنیت و امکانات و شبکه ارتباطی که دارد می تواند گزینه خوبی برای خرید و فروش آپارتمان در رضوانشهر باشد آپارتمان‌های مدرن با امکانات متنوع، معمولا هزینه و زمان کمتری نسبت به ویلاهای ساخته شده دارد و این امر می‌تواند یک گزینه جذاب برای خریداران با بودجه محدود باشد. همچنین افرادی که به رضوانشهر گیلان مهاجرت می کنند به دلیل وجود امنیت بالا و داشتن آب و هوای مطبوع و دسترسی های راحت تر می توانند به راحتی ازخرید آپارتمان در رضوانشهر گیلان استفاده کنند مطلع شوند و با توجه به این سالهای اخیر که قیمت آپارتمان روند صعودی داشته است می توانند از مزایای گرفتن وام و خرید آپارتمان نیز استفاده کنند.' => 'شقة در رضوانالمدينةكيلان از نظر اقتصادي مقرون به صرفه تر مي باشد و با توجه به امنيت و امكانات و شبكه ارتباطي كه دارفض مي تواند كزينه خوبي براي شراء و بيع شقة در رضوانالمدينة باشد شقة هاي مدرن با امكانات متنوع، معمولا هزينه و الوقت كمتري نسبت به فيلاهاي ساخته شده دارفض و اين امر مي تواند يك كزينه جذاب براي شراءاران با بودجه محدود باشد. همجنين افرادي كه به رضوانالمدينة كيلان مهاجرت مي كنند به دليل وجود امنيت بالا و داشتن آب و هواي مطبوع و دسترسي هاي راحت تر مي توانند به راحتي ازشراء شقة در رضوانالمدينة كيلان استفاده كنند مطلع شوند و با توجه به اين سالهاي اخير كه السعر شقة روند صعودي داشته است مي توانند از مزاياي كرفتن وام و شراء شقة نيز استفاده كنند.',
    'آپارتمان-در-رضوانشهرگیلان-از-نظر-اقتصادی-مقرون-به-صرفه-تر-می-باشد-و-با-توجه-به-امنیت-و-امکانات-و-شبکه-ارتباطی-که-دارد-می-تواند-گزینه-خوبی-برای-خرید-و-فروش-آپارتمان-در-رضوانشهر-باشد-آپارتمان‌های-مدرن-با-امکانات-متنوع،-معمولا-هزینه-و-زمان-کمتری-نسبت-به-ویلاهای-ساخته-شده-دارد-و-این-امر-می‌تواند-یک-گزینه-جذاب-برای-خریداران-با-بودجه-محدود-باشد.-همچنین-افرادی-که-به-رضوانشهر-گیلان-مهاجرت-می-کنند-به-دلیل-وجود-امنیت-بالا-و-داشتن-آب-و-هوای-مطبوع-و-دسترسی-های-راحت-تر-می-توانند-به-راحتی-ازخرید-آپارتمان-در-رضوانشهر-گیلان-استفاده-کنند-مطلع-شوند-و-با-توجه-به-این-سالهای-اخیر-که-قیمت-آپارتمان-روند-صعودی-داشته-است-می-توانند-از-مزایای-گرفتن-وام-و-خرید-آپارتمان-نیز-استفاده-کنند.' => 'شقة-در-رضوانالمدينةكيلان-از-نظر-اقتصادي-مقرون-به-صرفه-تر-مي-باشد-و-با-توجه-به-امنيت-و-امكانات-و-شبكه-ارتباطي-كه-دارفض-مي-تواند-كزينه-خوبي-براي-شراء-و-بيع-شقة-در-رضوانالمدينة-باشد-شقة هاي-مدرن-با-امكانات-متنوع،-معمولا-هزينه-و-الوقت-كمتري-نسبت-به-فيلاهاي-ساخته-شده-دارفض-و-اين-امر-مي تواند-يك-كزينه-جذاب-براي-شراءاران-با-بودجه-محدود-باشد.-همجنين-افرادي-كه-به-رضوانالمدينة-كيلان-مهاجرت-مي-كنند-به-دليل-وجود-امنيت-بالا-و-داشتن-آب-و-هواي-مطبوع-و-دسترسي-هاي-راحت-تر-مي-توانند-به-راحتي-ازشراء-شقة-در-رضوانالمدينة-كيلان-استفاده-كنند-مطلع-شوند-و-با-توجه-به-اين-سالهاي-اخير-كه-السعر-شقة-روند-صعودي-داشته-است-مي-توانند-از-مزاياي-كرفتن-وام-و-شراء-شقة-نيز-استفاده-كنند.',
    'قیمت خرید و فروش زمین و باغ دررضوانشهرگیلان' => 'السعر شراء و بيع أرض و باغ دررضوانالمدينةكيلان',
    'قیمت-خرید-و-فروش-زمین-و-باغ-دررضوانشهرگیلان' => 'السعر-شراء-و-بيع-أرض-و-باغ-دررضوانالمدينةكيلان',
    'وجود جنگل‌های غنی و پوشیده از درختان باعث ایجاد اقلیمی سرسبز و مطبوع در رضوان شهر شده است. این جنگلها به عنوان یکی از جاذبه‌های گردشگری مهم این منطقه محسوب می‌شوند و به افراد این امکان را تا در میان طبیعت زیبا و آرامش بخش این منطقه به زندگی بپردازند. همچنین، زیبایی‌های طبیعی و محیط سبز این شهر، آن را به یک مقصد آرامش بخش برای ساکنان و گردشگران تبدیل کرده است. رضوانشهر همچنین به دلیل اقلیم معتدل و خاک حاصلخیز، برای کشاورزی و باغداری نیز بسیار مناسب است. در این شهر، باغات مختلفی وجود دارد که انواع محصولات باغی از جمله کیوی، گردو، مرکبات متنوع، خرمالو، ازگیل، به، سیب و سایر میوه‌ها تولید می شود. این محصولات با کیفیت بالا و تازگی طعم و عطر خود را حفظ کرده و به بازارهای داخلی و حتی خارجی عرضه می‌شوند. از طرفی، وجود این باغات و زمین‌های کشاورزی، تأثیر مستقیمی بر بازار خرید و فروش زمین و باغ در این منطقه گذاشته و کشاورزان و سرمایه گذاران بسیاری را به سوی خود جذب کرده است که این امیر تاثیر مستقیمی بر پیشرفت خرید و فروش زمین و باغ در این شهر داشته و بر افزایش قیمت خرید وفروش تاثیر بسزایی گذاشته است' => 'وجود جنكل هاي غني و بوشيده از درختان باعث إنشاء اقليمي سرسبز و مطبوع در رضوان المدينة شده است. اين جنكلها به العنوان يكي از جاذبه هاي كرفضشكري مهم اين المنطقة محسوب مي شوند و به افراد اين امكان را تا در ميان طبيعت زيبا و آرامش بخش اين المنطقة به زندكي ببرفضازند. همجنين، زيبايي هاي طبيعي و محيط سبز اين المدينة، آن را به يك مقصد آرامش بخش براي ساكنان و كرفضشكران تبديل كرفضه است. رضوانالمدينة همجنين به دليل اقليم معتدل و خاك حاصلخيز، براي كشاورزي و باغداري نيز بسيار مناسب است. در اين المدينة، باغات مختلفي وجود دارفض كه انواع محصولات باغي از جمله كيوي، كرفضو، مركبات متنوع، خرمالو، ازكيل، به، سيب و ساير ميوه ها توليد مي شود. اين محصولات با كيفيت بالا و تازكي طعم و عطر خود را حفظ كرفضه و به بازارهاي داخلي و حتي خارجي عرضه مي شوند. از طرفي، وجود اين باغات و أرض هاي كشاورزي، تأثير مستقيمي بر بازار شراء و بيع أرض و باغ در اين المنطقة كذاشته و كشاورزان و سرمايه كذاران بسياري را به سوي خود جذب كرفضه است كه اين امير تاثير مستقيمي بر بيشرفت شراء و بيع أرض و باغ در اين المدينة داشته و بر افزايش السعر شراء وبيع تاثير بسزايي كذاشته است',
    'وجود-جنگل‌های-غنی-و-پوشیده-از-درختان-باعث-ایجاد-اقلیمی-سرسبز-و-مطبوع-در-رضوان-شهر-شده-است.-این-جنگلها-به-عنوان-یکی-از-جاذبه‌های-گردشگری-مهم-این-منطقه-محسوب-می‌شوند-و-به-افراد-این-امکان-را-تا-در-میان-طبیعت-زیبا-و-آرامش-بخش-این-منطقه-به-زندگی-بپردازند.-همچنین،-زیبایی‌های-طبیعی-و-محیط-سبز-این-شهر،-آن-را-به-یک-مقصد-آرامش-بخش-برای-ساکنان-و-گردشگران-تبدیل-کرده-است.-رضوانشهر-همچنین-به-دلیل-اقلیم-معتدل-و-خاک-حاصلخیز،-برای-کشاورزی-و-باغداری-نیز-بسیار-مناسب-است.-در-این-شهر،-باغات-مختلفی-وجود-دارد-که-انواع-محصولات-باغی-از-جمله-کیوی،-گردو،-مرکبات-متنوع،-خرمالو،-ازگیل،-به،-سیب-و-سایر-میوه‌ها-تولید-می-شود.-این-محصولات-با-کیفیت-بالا-و-تازگی-طعم-و-عطر-خود-را-حفظ-کرده-و-به-بازارهای-داخلی-و-حتی-خارجی-عرضه-می‌شوند.-از-طرفی،-وجود-این-باغات-و-زمین‌های-کشاورزی،-تأثیر-مستقیمی-بر-بازار-خرید-و-فروش-زمین-و-باغ-در-این-منطقه-گذاشته-و-کشاورزان-و-سرمایه-گذاران-بسیاری-را-به-سوی-خود-جذب-کرده-است-که-این-امیر-تاثیر-مستقیمی-بر-پیشرفت-خرید-و-فروش-زمین-و-باغ-در-این-شهر-داشته-و-بر-افزایش-قیمت-خرید-وفروش-تاثیر-بسزایی-گذاشته-است' => 'وجود-جنكل هاي-غني-و-بوشيده-از-درختان-باعث-إنشاء-اقليمي-سرسبز-و-مطبوع-در-رضوان-المدينة-شده-است.-اين-جنكلها-به-العنوان-يكي-از-جاذبه هاي-كرفضشكري-مهم-اين-المنطقة-محسوب-مي شوند-و-به-افراد-اين-امكان-را-تا-در-ميان-طبيعت-زيبا-و-آرامش-بخش-اين-المنطقة-به-زندكي-ببرفضازند.-همجنين،-زيبايي هاي-طبيعي-و-محيط-سبز-اين-المدينة،-آن-را-به-يك-مقصد-آرامش-بخش-براي-ساكنان-و-كرفضشكران-تبديل-كرفضه-است.-رضوانالمدينة-همجنين-به-دليل-اقليم-معتدل-و-خاك-حاصلخيز،-براي-كشاورزي-و-باغداري-نيز-بسيار-مناسب-است.-در-اين-المدينة،-باغات-مختلفي-وجود-دارفض-كه-انواع-محصولات-باغي-از-جمله-كيوي،-كرفضو،-مركبات-متنوع،-خرمالو،-ازكيل،-به،-سيب-و-ساير-ميوه ها-توليد-مي-شود.-اين-محصولات-با-كيفيت-بالا-و-تازكي-طعم-و-عطر-خود-را-حفظ-كرفضه-و-به-بازارهاي-داخلي-و-حتي-خارجي-عرضه-مي شوند.-از-طرفي،-وجود-اين-باغات-و-أرض هاي-كشاورزي،-تأثير-مستقيمي-بر-بازار-شراء-و-بيع-أرض-و-باغ-در-اين-المنطقة-كذاشته-و-كشاورزان-و-سرمايه-كذاران-بسياري-را-به-سوي-خود-جذب-كرفضه-است-كه-اين-امير-تاثير-مستقيمي-بر-بيشرفت-شراء-و-بيع-أرض-و-باغ-در-اين-المدينة-داشته-و-بر-افزايش-السعر-شراء-وبيع-تاثير-بسزايي-كذاشته-است',
    'خرید و فروش و قیمت زمین مسکونی در رضوانشهرگیلان' => 'شراء و بيع و السعر أرض سكني در رضوانالمدينةكيلان',
    'خرید-و-فروش-و-قیمت-زمین-مسکونی-در-رضوانشهرگیلان' => 'شراء-و-بيع-و-السعر-أرض-سكني-در-رضوانالمدينةكيلان',
    '. خرید و فروش و قیمت زمین‌های مسکونی در رضوانشهر گیلان ، بستگی به عواملی مانند موقعیت، متراژ، امکانات محیطی و ویژگی‌های زمین دارد. به طور کلی، قیمت‌ها به این صورت متغیر است: در بافت شهری، قیمت زمین‌ها در مرکز شهر بین7 تا 30 میلیون تومان هر متر مربع، در مناطق متوسط بین 5/3 تا 7 میلیون تومان هر متر مربع و در مناطق حاشیه‌ای بین 5/1 تا 6 میلیون تومان هر متر مربع متغیر است. اما زمین‌های خارج از بافت شهری، به مناطق نزدیک به جاده‌های اصلی و امکانات، در بازه 5/1 تا 5 میلیون تومان هر متر مربع و به مناطق دورتر با قیمت‌های 1میلیون تا 2 میلیون تومان هر متر مربع به فروش می‌رسند. این تنوع در قیمت‌ها نشان دهنده تأثیر عوامل مختلف اقتصادی و جغرافیایی بر بازار زمین‌های مسکونی در این منطقه است' => '. شراء و بيع و السعر أرض هاي سكني در رضوانالمدينة كيلان ، بستكي به عواملي مانند موقعيت، المساحة، امكانات محيطي و ويزكي هاي أرض دارفض. به طور كلي، السعر ها به اين صورت متغير است: در بافت المدينةي، السعر أرض ها در مركز المدينة بين7 تا 30 مليون درهم هر متر مربع، در مناطق متوسط بين 5/3 تا 7 مليون درهم هر متر مربع و در مناطق حاشيه اي بين 5/1 تا 6 مليون درهم هر متر مربع متغير است. اما أرض هاي خارج از بافت المدينةي، به مناطق نزديك به جاده هاي اصلي و امكانات، در بازه 5/1 تا 5 مليون درهم هر متر مربع و به مناطق دورتر با السعر هاي 1مليون تا 2 مليون درهم هر متر مربع به بيع مي رصك الملكية. اين تنوع در السعر ها نشان دهنده تأثير عوامل مختلف اقتصادي و جغرافيايي بر بازار أرض هاي سكني در اين المنطقة است',
    '.-خرید-و-فروش-و-قیمت-زمین‌های-مسکونی-در-رضوانشهر-گیلان-،-بستگی-به-عواملی-مانند-موقعیت،-متراژ،-امکانات-محیطی-و-ویژگی‌های-زمین-دارد.-به-طور-کلی،-قیمت‌ها-به-این-صورت-متغیر-است:-در-بافت-شهری،-قیمت-زمین‌ها-در-مرکز-شهر-بین7-تا-30-میلیون-تومان-هر-متر-مربع،-در-مناطق-متوسط-بین-5/3-تا-7-میلیون-تومان-هر-متر-مربع-و-در-مناطق-حاشیه‌ای-بین-5/1-تا-6-میلیون-تومان-هر-متر-مربع-متغیر-است.-اما-زمین‌های-خارج-از-بافت-شهری،-به-مناطق-نزدیک-به-جاده‌های-اصلی-و-امکانات،-در-بازه-5/1-تا-5-میلیون-تومان-هر-متر-مربع-و-به-مناطق-دورتر-با-قیمت‌های-1میلیون-تا-2-میلیون-تومان-هر-متر-مربع-به-فروش-می‌رسند.-این-تنوع-در-قیمت‌ها-نشان-دهنده-تأثیر-عوامل-مختلف-اقتصادی-و-جغرافیایی-بر-بازار-زمین‌های-مسکونی-در-این-منطقه-است' => '.-شراء-و-بيع-و-السعر-أرض هاي-سكني-در-رضوانالمدينة-كيلان-،-بستكي-به-عواملي-مانند-موقعيت،-المساحة،-امكانات-محيطي-و-ويزكي هاي-أرض-دارفض.-به-طور-كلي،-السعر ها-به-اين-صورت-متغير-است:-در-بافت-المدينةي،-السعر-أرض ها-در-مركز-المدينة-بين7-تا-30-مليون-درهم-هر-متر-مربع،-در-مناطق-متوسط-بين-5/3-تا-7-مليون-درهم-هر-متر-مربع-و-در-مناطق-حاشيه اي-بين-5/1-تا-6-مليون-درهم-هر-متر-مربع-متغير-است.-اما-أرض هاي-خارج-از-بافت-المدينةي،-به-مناطق-نزديك-به-جاده هاي-اصلي-و-امكانات،-در-بازه-5/1-تا-5-مليون-درهم-هر-متر-مربع-و-به-مناطق-دورتر-با-السعر هاي-1مليون-تا-2-مليون-درهم-هر-متر-مربع-به-بيع-مي رصك الملكية.-اين-تنوع-در-السعر ها-نشان-دهنده-تأثير-عوامل-مختلف-اقتصادي-و-جغرافيايي-بر-بازار-أرض هاي-سكني-در-اين-المنطقة-است',
    'خرید و فروش و قیمت زمین‌های تجاری در رضوانشهر گیلان' => 'شراء و بيع و السعر أرض هاي تجاري در رضوانالمدينة كيلان',
    'خرید-و-فروش-و-قیمت-زمین‌های-تجاری-در-رضوانشهر-گیلان' => 'شراء-و-بيع-و-السعر-أرض هاي-تجاري-در-رضوانالمدينة-كيلان',
    'خرید و فروش و قیمت زمین های تجاری در رضوانشهر گیلان بستگی به عواملی از جمله مکان (مرکزیت در شهر یا نزدیکی به جاذبه‌های توریستی و مراکز تجاری)، متراژ، امکانات (آب، برق، گاز، تلفن، فاضلاب)، نوع کاربری و وضعیت سند بستگی دارد. به عنوان مثال، یک زمین تجاری 45 متری دو دهنه در محدوده قیمت 1 میلیارد و 800 تومان و مغازه‌های مختلف با قیمت‌های توافقی و یا مشخص مانند 2 میلیارد و 500 هزار تومان موجود است. این قیمت‌ها بر اساس قیمت روز بازار هستند و بستگی به ویژگی‌های خاص هر ملک، ممکن است تغییر کند.' => 'شراء و بيع و السعر أرض هاي تجاري در رضوانالمدينة كيلان بستكي به عواملي از جمله مكان (مركزيت در المدينة يا نزديكي به جاذبه هاي توريستي و مراكز تجاري)، المساحة، امكانات (آب، برق، كاز، الهاتف، فاضلاب)، نوع كاربري و الحالة صك الملكية بستكي دارفض. به العنوان مثال، يك أرض تجاري 45 متري دو دهنه در محدوده السعر 1 مليار و 800 درهم و محل تجاري هاي مختلف با السعر هاي توافقي و يا مشخص مانند 2 مليار و 500 هزار درهم موجود است. اين السعر ها بر اساس السعر روز بازار هستند و بستكي به ويزكي هاي خاص هر ملك، ممكن است تغيير كند.',
    'خرید-و-فروش-و-قیمت-زمین-های-تجاری-در-رضوانشهر-گیلان-بستگی-به-عواملی-از-جمله-مکان-(مرکزیت-در-شهر-یا-نزدیکی-به-جاذبه‌های-توریستی-و-مراکز-تجاری)،-متراژ،-امکانات-(آب،-برق،-گاز،-تلفن،-فاضلاب)،-نوع-کاربری-و-وضعیت-سند-بستگی-دارد.-به-عنوان-مثال،-یک-زمین-تجاری-45-متری-دو-دهنه-در-محدوده-قیمت-1-میلیارد-و-800-تومان-و-مغازه‌های-مختلف-با-قیمت‌های-توافقی-و-یا-مشخص-مانند-2-میلیارد-و-500-هزار-تومان-موجود-است.-این-قیمت‌ها-بر-اساس-قیمت-روز-بازار-هستند-و-بستگی-به-ویژگی‌های-خاص-هر-ملک،-ممکن-است-تغییر-کند.' => 'شراء-و-بيع-و-السعر-أرض-هاي-تجاري-در-رضوانالمدينة-كيلان-بستكي-به-عواملي-از-جمله-مكان-(مركزيت-در-المدينة-يا-نزديكي-به-جاذبه هاي-توريستي-و-مراكز-تجاري)،-المساحة،-امكانات-(آب،-برق،-كاز،-الهاتف،-فاضلاب)،-نوع-كاربري-و-الحالة-صك الملكية-بستكي-دارفض.-به-العنوان-مثال،-يك-أرض-تجاري-45-متري-دو-دهنه-در-محدوده-السعر-1-مليار-و-800-درهم-و-محل تجاري هاي-مختلف-با-السعر هاي-توافقي-و-يا-مشخص-مانند-2-مليار-و-500-هزار-درهم-موجود-است.-اين-السعر ها-بر-اساس-السعر-روز-بازار-هستند-و-بستكي-به-ويزكي هاي-خاص-هر-ملك،-ممكن-است-تغيير-كند.',
    'خرید و فروش و قیمت ویلا استخردار در رضوانشهر گیلان' => 'شراء و بيع و السعر فيلا حوض سباحةدار در رضوانالمدينة كيلان',
    'خرید-و-فروش-و-قیمت-ویلا-استخردار-در-رضوانشهر-گیلان' => 'شراء-و-بيع-و-السعر-فيلا-حوض سباحةدار-در-رضوانالمدينة-كيلان',
    'خرید و فروش و قیمت ویلاهای استخردار در رضوانشهر گیلان، بستگی به عواملی از جمله موقعیت مکانی (ساحلی، جنگلی، دارای چشم‌انداز دریا یا کوه)، متراژویلا، تعداد اتاق خواب و حمام، امکانات (استخر، جکوزی، سونا، سالن بازی و محوطه سازی)، نوع بنا (نوساز یا قدیمی) و وضعیت سند ویلا تعیین می‌شود. مثلا قیمت ویلاهای 300 متری استخردار در پره سر به 3 میلیارد و 500 میلیون تومان و ویلاهای دیگر با قیمت‌های متفاوت می باشد. این قیمت‌ها تحت تأثیر شرایط خاص هر ویلا قرار می‌گیرند وتغییر می کند. .' => 'شراء و بيع و السعر فيلاهاي حوض سباحةدار در رضوانالمدينة كيلان، بستكي به عواملي از جمله موقعيت مكاني (ساحلي، جنكلي، داراي جشم انداز دريا يا كوه)، المساحةفيلا، تعداد غرفة غرفة نوم و حمام، امكانات (حوض سباحة، جاكوزي، ساونا، سالن بازي و محوطه سازي)، نوع بنا (حديث البناء يا قديمي) و الحالة صك الملكية فيلا تعيين مي شود. مثلا السعر فيلاهاي 300 متري حوض سباحةدار در بره سر به 3 مليار و 500 مليون درهم و فيلاهاي ديكر با السعر هاي متفاوت مي باشد. اين السعر ها تحت تأثير شرايط خاص هر فيلا قرار مي كيرند وتغيير مي كند. .',
    'خرید-و-فروش-و-قیمت-ویلاهای-استخردار-در-رضوانشهر-گیلان،-بستگی-به-عواملی-از-جمله-موقعیت-مکانی-(ساحلی،-جنگلی،-دارای-چشم‌انداز-دریا-یا-کوه)،-متراژویلا،-تعداد-اتاق-خواب-و-حمام،-امکانات-(استخر،-جکوزی،-سونا،-سالن-بازی-و-محوطه-سازی)،-نوع-بنا-(نوساز-یا-قدیمی)-و-وضعیت-سند-ویلا-تعیین-می‌شود.-مثلا-قیمت-ویلاهای-300-متری-استخردار-در-پره-سر-به-3-میلیارد-و-500-میلیون-تومان-و-ویلاهای-دیگر-با-قیمت‌های-متفاوت-می-باشد.-این-قیمت‌ها-تحت-تأثیر-شرایط-خاص-هر-ویلا-قرار-می‌گیرند-وتغییر-می-کند.-.' => 'شراء-و-بيع-و-السعر-فيلاهاي-حوض سباحةدار-در-رضوانالمدينة-كيلان،-بستكي-به-عواملي-از-جمله-موقعيت-مكاني-(ساحلي،-جنكلي،-داراي-جشم انداز-دريا-يا-كوه)،-المساحةفيلا،-تعداد-غرفة-غرفة نوم-و-حمام،-امكانات-(حوض سباحة،-جاكوزي،-ساونا،-سالن-بازي-و-محوطه-سازي)،-نوع-بنا-(حديث البناء-يا-قديمي)-و-الحالة-صك الملكية-فيلا-تعيين-مي شود.-مثلا-السعر-فيلاهاي-300-متري-حوض سباحةدار-در-بره-سر-به-3-مليار-و-500-مليون-درهم-و-فيلاهاي-ديكر-با-السعر هاي-متفاوت-مي-باشد.-اين-السعر ها-تحت-تأثير-شرايط-خاص-هر-فيلا-قرار-مي كيرند-وتغيير-مي-كند.-.',
    'خرید و فروش و قیمت آپارتمان مسکونی در رضوانشهر گیلان' => 'شراء و بيع و السعر شقة سكني در رضوانالمدينة كيلان',
    'خرید-و-فروش-و-قیمت-آپارتمان-مسکونی-در-رضوانشهر-گیلان' => 'شراء-و-بيع-و-السعر-شقة-سكني-در-رضوانالمدينة-كيلان',
    'خرید و فروش و قیمت آپارتمان‌های مسکونی در رضوانشهرگیلان، به عوامل مختلفی از جمله مکان (مرکزیت، نزدیکی به جاذبه‌های گردشگری و مراکز تجاری)، متراژ، تعداد اتاق خواب، طبقه، امکانات (آسانسور، پارکینگ، انباری، استخر، سونا و ...)، سن بنا و وضعیت سند بستگی دارد. به طور مثال آپارتمان‌های 90 متری دو خواب در مرکز شهر با قیمت 2 میلیارد و آپارتمان‌های دیگر با قیمت‌های مختلف خرید وفروش می شوند. این قیمت‌ها تحت تأثیر شرایط هر آپارتمان قرار می‌گیرند و قابل تغییر می باشد.' => 'شراء و بيع و السعر شقة هاي سكني در رضوانالمدينةكيلان، به عوامل مختلفي از جمله مكان (مركزيت، نزديكي به جاذبه هاي كرفضشكري و مراكز تجاري)، المساحة، تعداد غرفة غرفة نوم، طابق، امكانات (مصعد، موقف سيارات، مستودعي، حوض سباحة، ساونا و ...)، سن بنا و الحالة صك الملكية بستكي دارفض. به طور مثال شقة هاي 90 متري دو غرفة نوم در مركز المدينة با السعر 2 مليار و شقة هاي ديكر با السعر هاي مختلف شراء وبيع مي شوند. اين السعر ها تحت تأثير شرايط هر شقة قرار مي كيرند و قابل تغيير مي باشد.',
    'خرید-و-فروش-و-قیمت-آپارتمان‌های-مسکونی-در-رضوانشهرگیلان،-به-عوامل-مختلفی-از-جمله-مکان-(مرکزیت،-نزدیکی-به-جاذبه‌های-گردشگری-و-مراکز-تجاری)،-متراژ،-تعداد-اتاق-خواب،-طبقه،-امکانات-(آسانسور،-پارکینگ،-انباری،-استخر،-سونا-و-...)،-سن-بنا-و-وضعیت-سند-بستگی-دارد.-به-طور-مثال-آپارتمان‌های-90-متری-دو-خواب-در-مرکز-شهر-با-قیمت-2-میلیارد-و-آپارتمان‌های-دیگر-با-قیمت‌های-مختلف-خرید-وفروش-می-شوند.-این-قیمت‌ها-تحت-تأثیر-شرایط-هر-آپارتمان-قرار-می‌گیرند-و-قابل-تغییر-می-باشد.' => 'شراء-و-بيع-و-السعر-شقة هاي-سكني-در-رضوانالمدينةكيلان،-به-عوامل-مختلفي-از-جمله-مكان-(مركزيت،-نزديكي-به-جاذبه هاي-كرفضشكري-و-مراكز-تجاري)،-المساحة،-تعداد-غرفة-غرفة نوم،-طابق،-امكانات-(مصعد،-موقف سيارات،-مستودعي،-حوض سباحة،-ساونا-و-...)،-سن-بنا-و-الحالة-صك الملكية-بستكي-دارفض.-به-طور-مثال-شقة هاي-90-متري-دو-غرفة نوم-در-مركز-المدينة-با-السعر-2-مليار-و-شقة هاي-ديكر-با-السعر هاي-مختلف-شراء-وبيع-مي-شوند.-اين-السعر ها-تحت-تأثير-شرايط-هر-شقة-قرار-مي كيرند-و-قابل-تغيير-مي-باشد.',
    'خرید و فروش و قیمت آپارتمان های تجاری در رضوانشهر گیلان' => 'شراء و بيع و السعر شقة هاي تجاري در رضوانالمدينة كيلان',
    'خرید-و-فروش-و-قیمت-آپارتمان-های-تجاری-در-رضوانشهر-گیلان' => 'شراء-و-بيع-و-السعر-شقة-هاي-تجاري-در-رضوانالمدينة-كيلان',
    'خرید و فروش وقیمت آپارتمان‌های تجاری در رضوانشهرگیلان، به عواملی از جمله مکان (مرکزیت، نزدیکی به جاذبه‌های گردشگری و مراکز تجاری)، متراژآپارتمان، تعداد اتاق ها، تعداد طبقه، امکانات (آسانسور، پارکینگ، انباری، سرویس بهداشتی و ...)، سن بنا، وضعیت سند، و کاربری ملک بستگی دارد. مثلا آپارتمان‌های 50 متری تجاری در مرکز شهر با قیمت 2 میلیارد تومان و آپارتمان‌های دیگر با قیمت‌های متفاوت ذکرخرید و فروش می شود که قیمت ها با توجه به ویژگی‌ها و شرایط خاص هر آپارتمان تغییر می کند و ممکن است مختلف باشند.' => 'شراء و بيع والسعر شقة هاي تجاري در رضوانالمدينةكيلان، به عواملي از جمله مكان (مركزيت، نزديكي به جاذبه هاي كرفضشكري و مراكز تجاري)، المساحةشقة، تعداد غرفة ها، تعداد طابق، امكانات (مصعد، موقف سيارات، مستودعي، دورة مياه و ...)، سن بنا، الحالة صك الملكية، و كاربري ملك بستكي دارفض. مثلا شقة هاي 50 متري تجاري در مركز المدينة با السعر 2 مليار درهم و شقة هاي ديكر با السعر هاي متفاوت ذكرشراء و بيع مي شود كه السعر ها با توجه به ويزكي ها و شرايط خاص هر شقة تغيير مي كند و ممكن است مختلف باشند.',
    'خرید-و-فروش-وقیمت-آپارتمان‌های-تجاری-در-رضوانشهرگیلان،-به-عواملی-از-جمله-مکان-(مرکزیت،-نزدیکی-به-جاذبه‌های-گردشگری-و-مراکز-تجاری)،-متراژآپارتمان،-تعداد-اتاق-ها،-تعداد-طبقه،-امکانات-(آسانسور،-پارکینگ،-انباری،-سرویس-بهداشتی-و-...)،-سن-بنا،-وضعیت-سند،-و-کاربری-ملک-بستگی-دارد.-مثلا-آپارتمان‌های-50-متری-تجاری-در-مرکز-شهر-با-قیمت-2-میلیارد-تومان-و-آپارتمان‌های-دیگر-با-قیمت‌های-متفاوت-ذکرخرید-و-فروش-می-شود-که-قیمت-ها-با-توجه-به-ویژگی‌ها-و-شرایط-خاص-هر-آپارتمان-تغییر-می-کند-و-ممکن-است-مختلف-باشند.' => 'شراء-و-بيع-والسعر-شقة هاي-تجاري-در-رضوانالمدينةكيلان،-به-عواملي-از-جمله-مكان-(مركزيت،-نزديكي-به-جاذبه هاي-كرفضشكري-و-مراكز-تجاري)،-المساحةشقة،-تعداد-غرفة-ها،-تعداد-طابق،-امكانات-(مصعد،-موقف سيارات،-مستودعي،-سرويس-بهداشتي-و-...)،-سن-بنا،-الحالة-صك الملكية،-و-كاربري-ملك-بستكي-دارفض.-مثلا-شقة هاي-50-متري-تجاري-در-مركز-المدينة-با-السعر-2-مليار-درهم-و-شقة هاي-ديكر-با-السعر هاي-متفاوت-ذكرشراء-و-بيع-مي-شود-كه-السعر-ها-با-توجه-به-ويزكي ها-و-شرايط-خاص-هر-شقة-تغيير-مي-كند-و-ممكن-است-مختلف-باشند.',
    'خرید و فروش و قیمت آپارتمان های اداری در رضوانشهرگیلان' => 'شراء و بيع و السعر شقة هاي إداري در رضوانالمدينةكيلان',
    'خرید-و-فروش-و-قیمت-آپارتمان-های-اداری-در-رضوانشهرگیلان' => 'شراء-و-بيع-و-السعر-شقة-هاي-إداري-در-رضوانالمدينةكيلان',
    'خرید و فروش و قیمت آپارتمان‌های اداری در رضوانشهرگیلان، به عواملی مختلفی از جمله (نزدیکی به اداره ها و مراکزخرید و تجاری، منطقه مرکزی شهر)، متراژآپارتمان، تعداد اتاق، تعداد طبقه، امکانات (مانند آسانسور، پارکینگ، انباری، سرویس بهداشتی و ...)، سن بنا، وضعیت سندآپارتمان و همچنین کاربری آن بستگی دارد. مثلا آپارتمان‌های اداری در مرکز شهر با متراژ 50متر مربع با قیمت 2 میلیارد تومان و آپارتمان‌های با متراژ و ویژگی‌های مختلف دیگر ذکر شده‌اند. این قیمت‌ها بسته به شرایط خاص هر آپارتمان متغیر بوده و ممکن است مختلف باشند.' => 'شراء و بيع و السعر شقة هاي إداري در رضوانالمدينةكيلان، به عواملي مختلفي از جمله (نزديكي به اداره ها و مراكزشراء و تجاري، المنطقة مركزي المدينة)، المساحةشقة، تعداد غرفة، تعداد طابق، امكانات (مانند مصعد، موقف سيارات، مستودعي، دورة مياه و ...)، سن بنا، الحالة صك الملكيةشقة و همجنين كاربري آن بستكي دارفض. مثلا شقة هاي إداري در مركز المدينة با المساحة 50متر مربع با السعر 2 مليار درهم و شقة هاي با المساحة و ويزكي هاي مختلف ديكر ذكر شده اند. اين السعر ها بسته به شرايط خاص هر شقة متغير بوده و ممكن است مختلف باشند.',
    'خرید-و-فروش-و-قیمت-آپارتمان‌های-اداری-در-رضوانشهرگیلان،-به-عواملی-مختلفی-از-جمله-(نزدیکی-به-اداره-ها-و-مراکزخرید-و-تجاری،-منطقه-مرکزی-شهر)،-متراژآپارتمان،-تعداد-اتاق،-تعداد-طبقه،-امکانات-(مانند-آسانسور،-پارکینگ،-انباری،-سرویس-بهداشتی-و-...)،-سن-بنا،-وضعیت-سندآپارتمان-و-همچنین-کاربری-آن-بستگی-دارد.-مثلا-آپارتمان‌های-اداری-در-مرکز-شهر-با-متراژ-50متر-مربع-با-قیمت-2-میلیارد-تومان-و-آپارتمان‌های-با-متراژ-و-ویژگی‌های-مختلف-دیگر-ذکر-شده‌اند.-این-قیمت‌ها-بسته-به-شرایط-خاص-هر-آپارتمان-متغیر-بوده-و-ممکن-است-مختلف-باشند.' => 'شراء-و-بيع-و-السعر-شقة هاي-إداري-در-رضوانالمدينةكيلان،-به-عواملي-مختلفي-از-جمله-(نزديكي-به-اداره-ها-و-مراكزشراء-و-تجاري،-المنطقة-مركزي-المدينة)،-المساحةشقة،-تعداد-غرفة،-تعداد-طابق،-امكانات-(مانند-مصعد،-موقف سيارات،-مستودعي،-سرويس-بهداشتي-و-...)،-سن-بنا،-الحالة-صك الملكيةشقة-و-همجنين-كاربري-آن-بستكي-دارفض.-مثلا-شقة هاي-إداري-در-مركز-المدينة-با-المساحة-50متر-مربع-با-السعر-2-مليار-درهم-و-شقة هاي-با-المساحة-و-ويزكي هاي-مختلف-ديكر-ذكر-شده اند.-اين-السعر ها-بسته-به-شرايط-خاص-هر-شقة-متغير-بوده-و-ممكن-است-مختلف-باشند.',
    'چرا در گیلان زمین یا ویلا بخریم؟' => 'جرا در كيلان أرض يا فيلا بخريم؟',
    'چرا-در-گیلان-زمین-یا-ویلا-بخریم؟' => 'جرا-در-كيلان-أرض-يا-فيلا-بخريم؟',
    'خرید زمین یا ویلا در گیلان میتواند یک سرمایه گذاری سودآوری باشد و به عنوان محل اقامت دوم مزایای زیادی برای شما داشته باشد از جمله اینکه از طبیعت زیبا و سرسبز و آب و هوای خنک و معتدل و جنگل های لذت بخش و مهم تر از همه دریای زیبای خزر و سواحل شمالی استفاده می کنید و آرامش را برای خود به ارمغان می آورید.و همچنین به علت توریستی بودن استان گیلان و حجم بالای مسافران در طول فواصل مختلف در این استان می توانید حتی در غیاب خود کسب درامد کنید' => 'شراء أرض يا فيلا در كيلان ميتواند يك سرمايه كذاري سودآوري باشد و به العنوان محل اقامت دوم مزاياي زيادي براي شما داشته باشد از جمله اينكه از طبيعت زيبا و سرسبز و آب و هواي خنك و معتدل و جنكل هاي لذت بخش و مهم تر از همه درياي زيباي خزر و سواحل شمالي استفاده مي كنيد و آرامش را براي خود به ارمغان مي آوريد.و همجنين به علت توريستي بودن الإمارة كيلان و حجم بالاي مسافران در طول فواصل مختلف در اين الإمارة مي توانيد حتي در غياب خود كسب درامد كنيد',
    'خرید-زمین-یا-ویلا-در-گیلان-میتواند-یک-سرمایه-گذاری-سودآوری-باشد-و-به-عنوان-محل-اقامت-دوم-مزایای-زیادی-برای-شما-داشته-باشد-از-جمله-اینکه-از-طبیعت-زیبا-و-سرسبز-و-آب-و-هوای-خنک-و-معتدل-و-جنگل-های-لذت-بخش-و-مهم-تر-از-همه-دریای-زیبای-خزر-و-سواحل-شمالی-استفاده-می-کنید-و-آرامش-را-برای-خود-به-ارمغان-می-آورید.و-همچنین-به-علت-توریستی-بودن-استان-گیلان-و-حجم-بالای-مسافران-در-طول-فواصل-مختلف-در-این-استان-می-توانید-حتی-در-غیاب-خود-کسب-درامد-کنید' => 'شراء-أرض-يا-فيلا-در-كيلان-ميتواند-يك-سرمايه-كذاري-سودآوري-باشد-و-به-العنوان-محل-اقامت-دوم-مزاياي-زيادي-براي-شما-داشته-باشد-از-جمله-اينكه-از-طبيعت-زيبا-و-سرسبز-و-آب-و-هواي-خنك-و-معتدل-و-جنكل-هاي-لذت-بخش-و-مهم-تر-از-همه-درياي-زيباي-خزر-و-سواحل-شمالي-استفاده-مي-كنيد-و-آرامش-را-براي-خود-به-ارمغان-مي-آوريد.و-همجنين-به-علت-توريستي-بودن-الإمارة-كيلان-و-حجم-بالاي-مسافران-در-طول-فواصل-مختلف-در-اين-الإمارة-مي-توانيد-حتي-در-غياب-خود-كسب-درامد-كنيد',
    'چگونه در گیلان سرمایه گذاری سودآور داشته باشیم؟' => 'جكونه در كيلان سرمايه كذاري سودآور داشته باشيم؟',
    'چگونه-در-گیلان-سرمایه-گذاری-سودآور-داشته-باشیم؟' => 'جكونه-در-كيلان-سرمايه-كذاري-سودآور-داشته-باشيم؟',
    'خرید ملک در گیلان زمانی سرمایه گذاری پر سودی حساب می شود که با مشاور ملکی و یا کارشناس املاک معتبر مشورت کنید و تمام اسناد و مدارک را بررسی کنید' => 'شراء ملك در كيلان الوقتي سرمايه كذاري بر سودي حساب مي شود كه با مستشار ملكي و يا خبير املاك معتبر مشورت كنيد و تمام اسناد و مدارك را بررسي كنيد',
    'خرید-ملک-در-گیلان-زمانی-سرمایه-گذاری-پر-سودی-حساب-می-شود-که-با-مشاور-ملکی-و-یا-کارشناس-املاک-معتبر-مشورت-کنید-و-تمام-اسناد-و-مدارک-را-بررسی-کنید' => 'شراء-ملك-در-كيلان-الوقتي-سرمايه-كذاري-بر-سودي-حساب-مي-شود-كه-با-مستشار-ملكي-و-يا-خبير-املاك-معتبر-مشورت-كنيد-و-تمام-اسناد-و-مدارك-را-بررسي-كنيد',
    'چه عواملی بر قیمت ویلا و زمین در گیلان تاثیر گذار است؟' => 'جه عواملي بر السعر فيلا و أرض در كيلان تاثير كذار است؟',
    'چه-عواملی-بر-قیمت-ویلا-و-زمین-در-گیلان-تاثیر-گذار-است؟' => 'جه-عواملي-بر-السعر-فيلا-و-أرض-در-كيلان-تاثير-كذار-است؟',
    'قیمت ویلاها و زمین در گیلان بستگی به عوامل مختلفی دارد از جمله :' => 'السعر فيلاها و أرض در كيلان بستكي به عوامل مختلفي دارفض از جمله :',
    'قیمت-ویلاها-و-زمین-در-گیلان-بستگی-به-عوامل-مختلفی-دارد-از-جمله-:' => 'السعر-فيلاها-و-أرض-در-كيلان-بستكي-به-عوامل-مختلفي-دارفض-از-جمله-:',
    '1- موقعیت جغرافیایی که برخی مناطق به علت دارا بودن در منظره های طبیعی مثل کوهستان ها ، دریاها و جنگل ها دارای قیمت بالاتری هستند.' => '1- موقعيت جغرافيايي كه برخي مناطق به علت دارا بودن در منظره هاي طبيعي مثل كوهستان ها ، درياها و جنكل ها داراي السعر بالاتري هستند.',
    '1--موقعیت-جغرافیایی-که-برخی-مناطق-به-علت-دارا-بودن-در-منظره-های-طبیعی-مثل-کوهستان-ها-،-دریاها-و-جنگل-ها-دارای-قیمت-بالاتری-هستند.' => '1--موقعيت-جغرافيايي-كه-برخي-مناطق-به-علت-دارا-بودن-در-منظره-هاي-طبيعي-مثل-كوهستان-ها-،-درياها-و-جنكل-ها-داراي-السعر-بالاتري-هستند.',
    '2-امکانات و خدمات: معمولا در مناطقی که امکانات و خدمات کامل تری از جمله دریا، مراکز تجاری،شهرها و …در دسترس می باشد زمین و ویلا قیمت بالاتری دارد.' => '2-امکانات و خدمات: معمولا در مناطقی که امکانات و خدمات کامل تری از جمله دریا، مراکز تجاري،المدينةها و …در دسترس می باشد أرض و فيلا السعر بالاتری دارفض.',
    '2-امکانات-و-خدمات:-معمولا-در-مناطقی-که-امکانات-و-خدمات-کامل-تری-از-جمله-دریا،-مراکز-تجاری،شهرها-و-…در-دسترس-می-باشد-زمین-و-ویلا-قیمت-بالاتری-دارد.' => '2-امکانات و خدمات: معمولا در مناطقی که امکانات و خدمات کامل تری از جمله دریا، مراکز تجاری،شهرها و …در دسترس می باشد زمین و ویلا قیمت بالاتری دارد.',
    '3-ورود سرمایه گذاران و بازار ملک: اگر بازار ملک در یک منطقه روند رشدی دارد و جذاب برای سرمایاه گذاران به نظر می رسد قیمت ها در این منطقه افزایش می یابند.' => '3-تسجيل الدخول سرمايه كذاران و بازار ملك: اكر بازار ملك در يك المنطقة روند رشدي دارفض و جذاب براي سرماياه كذاران به نظر مي رسد السعر ها در اين المنطقة افزايش مي يابند.',
    '3-ورود-سرمایه-گذاران-و-بازار-ملک:-اگر-بازار-ملک-در-یک-منطقه-روند-رشدی-دارد-و-جذاب-برای-سرمایاه-گذاران-به-نظر-می-رسد-قیمت-ها-در-این-منطقه-افزایش-می-یابند.' => '3-تسجيل الدخول-سرمايه-كذاران-و-بازار-ملك:-اكر-بازار-ملك-در-يك-المنطقة-روند-رشدي-دارفض-و-جذاب-براي-سرماياه-كذاران-به-نظر-مي-رسد-السعر-ها-در-اين-المنطقة-افزايش-مي-يابند.',
    '4-امکانات داخل ویلا و درون زمین : امکانات و ویژگی هایی که در داخل هر ویلا و زمین قرار دارد بر قیمت تاثیر گذار می باشد هر چقدر زمین یا ویلا امکانات بیشتری داشته باشد ممکن است قیمت بالاتری داشته باشد.' => '4-امكانات داخل فيلا و درون أرض : امكانات و ويزكي هايي كه در داخل هر فيلا و أرض قرار دارفض بر السعر تاثير كذار مي باشد هر جقدر أرض يا فيلا امكانات بيشتري داشته باشد ممكن است السعر بالاتري داشته باشد.',
    '4-امکانات-داخل-ویلا-و-درون-زمین-:-امکانات-و-ویژگی-هایی-که-در-داخل-هر-ویلا-و-زمین-قرار-دارد-بر-قیمت-تاثیر-گذار-می-باشد-هر-چقدر-زمین-یا-ویلا-امکانات-بیشتری-داشته-باشد-ممکن-است-قیمت-بالاتری-داشته-باشد.' => '4-امكانات-داخل-فيلا-و-درون-أرض-:-امكانات-و-ويزكي-هايي-كه-در-داخل-هر-فيلا-و-أرض-قرار-دارفض-بر-السعر-تاثير-كذار-مي-باشد-هر-جقدر-أرض-يا-فيلا-امكانات-بيشتري-داشته-باشد-ممكن-است-السعر-بالاتري-داشته-باشد.',
    '5- عوامل اقتصادی : افزایش قوت خرید جامعه ، شرایط اقتصادی و اصولا عرضه و تقاضای بازار ملک در منطقه می تواند باعث افزایش یا کاهش قیمت ها شود.' => '5- عوامل اقتصادی : افزایش قوت شراء جامعه ، شرایط اقتصادی و اصولا عرضه و تقاضای بازار ملک در المنطقة می تواند باعث افزایش یا کاهش السعر ها شود.',
    '5--عوامل-اقتصادی-:-افزایش-قوت-خرید-جامعه-،-شرایط-اقتصادی-و-اصولا-عرضه-و-تقاضای-بازار-ملک-در-منطقه-می-تواند-باعث-افزایش-یا-کاهش-قیمت-ها-شود.' => '5- عوامل اقتصادی : افزایش قوت خرید جامعه ، شرایط اقتصادی و اصولا عرضه و تقاضای بازار ملک در منطقه می تواند باعث افزایش یا کاهش قیمت ها شود.',
    'برای اطلاعات دقیق تر از موقعیت و قیمت ملک و زمین خود می توانید با کارشناسان آموزش دیده گیلند ملک در ارتباط باشید.' => 'براي المعلومات دقيق تر از موقعيت و السعر ملك و أرض خود مي توانيد با خبيران آموزش ديده كيلند ملك در ارتباط باشيد.',
    'برای-اطلاعات-دقیق-تر-از-موقعیت-و-قیمت-ملک-و-زمین-خود-می-توانید-با-کارشناسان-آموزش-دیده-گیلند-ملک-در-ارتباط-باشید.' => 'براي-المعلومات-دقيق-تر-از-موقعيت-و-السعر-ملك-و-أرض-خود-مي-توانيد-با-خبيران-آموزش-ديده-كيلند-ملك-در-ارتباط-باشيد.',
