    'چطور ویلا رزرو کنم؟' => 'جطور فيلا رزرو كنم؟',
    'چطور-ویلا-رزرو-کنم؟' => 'جطور-فيلا-رزرو-كنم؟',
    'پس از مشخص کردن تاریخ ورود و خروج و تعداد نفرات، درخواست رزرو خود را به‌صورت رایگان با تماس با کارشناس مربوطه ثبت کنید. میزبان در صورت خالی بودن و مهیا بودن اقامتگاه، رزرو را تایید می‌کند. سپس پیامکی مبنی بر تایید رزرو برای شما ارسال می‌شود و شما حداکثر 30 دقیقه فرصت خواهید داشت تا با پرداخت مبلغ صورتحساب، رزرو را قطعی کرده و سند رزرو حاوی صورتحساب، شماره تماس میزبان، آدرس اقامتگاه و سایر اطلاعات رزرو را دریافت کنید. در صورت خالی بودن و مهیا بودن اقامتگاه رزرو تائید می شود. سپس پیامکی مبنی بر تائید ملک برای شما ارسال می شود و شما حداکثر 15 دقیقه فرصت دارید که با پرداخت مبلغ صورتحساب رزرو را قطعی کنید.' => 'بس از مشخص كرفضن التاريخ تسجيل الدخول و تسجيل الخروج و تعداد نفرات، درخواست رزرو خود را به صورت رايكان با تماس با خبير مربوطه إرسال كنيد. ميزبان در صورت خالي بودن و مهيا بودن اقامتكاه، رزرو را تأكيد مي كند. سبس رسالةكي مبني بر تأكيد رزرو براي شما إرسال مي شود و شما حداكثر 30 دقيقه فرصت خواهيد داشت تا با برفضاخت مبلغ صورتحساب، رزرو را قطعي كرفضه و صك الملكية رزرو حاوي صورتحساب، شماره تماس ميزبان، الالعنوان اقامتكاه و ساير المعلومات رزرو را استلام كنيد. در صورت خالي بودن و مهيا بودن اقامتكاه رزرو تائيد مي شود. سبس رسالةكي مبني بر تائيد ملك براي شما إرسال مي شود و شما حداكثر 15 دقيقه فرصت داريد كه با برفضاخت مبلغ صورتحساب رزرو را قطعي كنيد.',
    'پس-از-مشخص-کردن-تاریخ-ورود-و-خروج-و-تعداد-نفرات،-درخواست-رزرو-خود-را-به‌صورت-رایگان-با-تماس-با-کارشناس-مربوطه-ثبت-کنید.-میزبان-در-صورت-خالی-بودن-و-مهیا-بودن-اقامتگاه،-رزرو-را-تایید-می‌کند.-سپس-پیامکی-مبنی-بر-تایید-رزرو-برای-شما-ارسال-می‌شود-و-شما-حداکثر-30-دقیقه-فرصت-خواهید-داشت-تا-با-پرداخت-مبلغ-صورتحساب،-رزرو-را-قطعی-کرده-و-سند-رزرو-حاوی-صورتحساب،-شماره-تماس-میزبان،-آدرس-اقامتگاه-و-سایر-اطلاعات-رزرو-را-دریافت-کنید.-در-صورت-خالی-بودن-و-مهیا-بودن-اقامتگاه-رزرو-تائید-می-شود.-سپس-پیامکی-مبنی-بر-تائید-ملک-برای-شما-ارسال-می-شود-و-شما-حداکثر-15-دقیقه-فرصت-دارید-که-با-پرداخت-مبلغ-صورتحساب-رزرو-را-قطعی-کنید.' => 'بس-از-مشخص-كرفضن-التاريخ-تسجيل الدخول-و-تسجيل الخروج-و-تعداد-نفرات،-درخواست-رزرو-خود-را-به صورت-رايكان-با-تماس-با-خبير-مربوطه-إرسال-كنيد.-ميزبان-در-صورت-خالي-بودن-و-مهيا-بودن-اقامتكاه،-رزرو-را-تأكيد-مي كند.-سبس-رسالةكي-مبني-بر-تأكيد-رزرو-براي-شما-إرسال-مي شود-و-شما-حداكثر-30-دقيقه-فرصت-خواهيد-داشت-تا-با-برفضاخت-مبلغ-صورتحساب،-رزرو-را-قطعي-كرفضه-و-صك الملكية-رزرو-حاوي-صورتحساب،-شماره-تماس-ميزبان،-الالعنوان-اقامتكاه-و-ساير-المعلومات-رزرو-را-استلام-كنيد.-در-صورت-خالي-بودن-و-مهيا-بودن-اقامتكاه-رزرو-تائيد-مي-شود.-سبس-رسالةكي-مبني-بر-تائيد-ملك-براي-شما-إرسال-مي-شود-و-شما-حداكثر-15-دقيقه-فرصت-داريد-كه-با-برفضاخت-مبلغ-صورتحساب-رزرو-را-قطعي-كنيد.',
    'در هنگام ثبت "درخواست رزرو" می‌توانید با کارشناسان گیلند ملک در مورد اقامتگاه صحبت کنید و همچنین پس از پرداخت صورتحساب و قطعی شدن رزرو در یک سند که حاوی مشخصات, شماره تماس میزبان و آدرس اقامتگاه می باشد, برای شما صادر می شود و شما می توانید با میزبان خود تماس بگیرید. همچنین پس از پرداخت صورتحساب و قطعی شدن رزرو، یک سند رزرو حاوی مشخصات، شماره تماس میزبان و آدرس اقامتگاه برای شما صادر می‌شود و میتوانید با میزبان خود تماس بگیرید.' => 'در هنكام إرسال "درخواست رزرو" مي توانيد با خبيران كيلند ملك در مورفض اقامتكاه صحبت كنيد و همجنين بس از برفضاخت صورتحساب و قطعي شدن رزرو در يك صك الملكية كه حاوي مشخصات, شماره تماس ميزبان و الالعنوان اقامتكاه مي باشد, براي شما صادر مي شود و شما مي توانيد با ميزبان خود تماس بكيريد. همجنين بس از برفضاخت صورتحساب و قطعي شدن رزرو، يك صك الملكية رزرو حاوي مشخصات، شماره تماس ميزبان و الالعنوان اقامتكاه براي شما صادر مي شود و ميتوانيد با ميزبان خود تماس بكيريد.',
    'در-هنگام-ثبت-"درخواست-رزرو"-می‌توانید-با-کارشناسان-گیلند-ملک-در-مورد-اقامتگاه-صحبت-کنید-و-همچنین-پس-از-پرداخت-صورتحساب-و-قطعی-شدن-رزرو-در-یک-سند-که-حاوی-مشخصات,-شماره-تماس-میزبان-و-آدرس-اقامتگاه-می-باشد,-برای-شما-صادر-می-شود-و-شما-می-توانید-با-میزبان-خود-تماس-بگیرید.-همچنین-پس-از-پرداخت-صورتحساب-و-قطعی-شدن-رزرو،-یک-سند-رزرو-حاوی-مشخصات،-شماره-تماس-میزبان-و-آدرس-اقامتگاه-برای-شما-صادر-می‌شود-و-میتوانید-با-میزبان-خود-تماس-بگیرید.' => 'در-هنكام-إرسال-"درخواست-رزرو"-مي توانيد-با-خبيران-كيلند-ملك-در-مورفض-اقامتكاه-صحبت-كنيد-و-همجنين-بس-از-برفضاخت-صورتحساب-و-قطعي-شدن-رزرو-در-يك-صك الملكية-كه-حاوي-مشخصات,-شماره-تماس-ميزبان-و-الالعنوان-اقامتكاه-مي-باشد,-براي-شما-صادر-مي-شود-و-شما-مي-توانيد-با-ميزبان-خود-تماس-بكيريد.-همجنين-بس-از-برفضاخت-صورتحساب-و-قطعي-شدن-رزرو،-يك-صك الملكية-رزرو-حاوي-مشخصات،-شماره-تماس-ميزبان-و-الالعنوان-اقامتكاه-براي-شما-صادر-مي شود-و-ميتوانيد-با-ميزبان-خود-تماس-بكيريد.',
    'با رد یا لغو شدن درخواست رزرو چه می‌شود؟' => 'با رفض يا لغو شدن درخواست رزرو جه مي شود؟',
    'با-رد-یا-لغو-شدن-درخواست-رزرو-چه-می‌شود؟' => 'با-رفض-يا-لغو-شدن-درخواست-رزرو-جه-مي شود؟',
    'زمانی که اقامگاه پر باشد بعد از تماس با کارشناس گیلند ملک می توانید برای اقامتگاه دیگری درخواست رزرو ثبت کنید. همچنین شما می توانید همزمان دو یا چند اقامتگاه باهم درخواست رزرو بدهید و تماس بگیرید.' => 'الوقتي كه اقامكاه بر باشد بعد از تماس با خبير كيلند ملك مي توانيد براي اقامتكاه ديكري درخواست رزرو إرسال كنيد. همجنين شما مي توانيد همالوقت دو يا جند اقامتكاه باهم درخواست رزرو بدهيد و تماس بكيريد.',
    'زمانی-که-اقامگاه-پر-باشد-بعد-از-تماس-با-کارشناس-گیلند-ملک-می-توانید-برای-اقامتگاه-دیگری-درخواست-رزرو-ثبت-کنید.-همچنین-شما-می-توانید-همزمان-دو-یا-چند-اقامتگاه-باهم-درخواست-رزرو-بدهید-و-تماس-بگیرید.' => 'الوقتي-كه-اقامكاه-بر-باشد-بعد-از-تماس-با-خبير-كيلند-ملك-مي-توانيد-براي-اقامتكاه-ديكري-درخواست-رزرو-إرسال-كنيد.-همجنين-شما-مي-توانيد-همالوقت-دو-يا-جند-اقامتكاه-باهم-درخواست-رزرو-بدهيد-و-تماس-بكيريد.',
    'تایید یا رد درخواست رزرو چقدر طول می‌کشد؟' => 'تأكيد يا رفض درخواست رزرو جقدر طول مي كشد؟',
    'تایید-یا-رد-درخواست-رزرو-چقدر-طول-می‌کشد؟' => 'تأكيد-يا-رفض-درخواست-رزرو-جقدر-طول-مي كشد؟',
    'به‌طور میانگین در کمتر از 15 دقیقه به درخواست ها پاسخ داده می‌شود. سابقه زمان پاسخگویی هر کارشناس به درخواست میهمان و هماهنگی با میزبان در کمتر از 30 دقیقه انجام می شود. حداکثر مهلت پاسخگویی میزبانان به درخواست رزرو در ساعات کاری 30 دقیقه است و در ساعات نیمه شب مهلت پاسخگویی تا صبح روز بعد تمدید می‌گردد.' => 'به طور ميانكين در كمتر از 15 دقيقه به درخواست ها باسخ داده مي شود. سابقه الوقت باسخكويي هر خبير به درخواست ميهمان و هماهنكي با ميزبان در كمتر از 30 دقيقه انجام مي شود. حداكثر مهلت باسخكويي ميزبانان به درخواست رزرو در ساعات كاري 30 دقيقه است و در ساعات نيمه شب مهلت باسخكويي تا صبح روز بعد تمديد مي كرفضد.',
    'به‌طور-میانگین-در-کمتر-از-15-دقیقه-به-درخواست-ها-پاسخ-داده-می‌شود.-سابقه-زمان-پاسخگویی-هر-کارشناس-به-درخواست-میهمان-و-هماهنگی-با-میزبان-در-کمتر-از-30-دقیقه-انجام-می-شود.-حداکثر-مهلت-پاسخگویی-میزبانان-به-درخواست-رزرو-در-ساعات-کاری-30-دقیقه-است-و-در-ساعات-نیمه-شب-مهلت-پاسخگویی-تا-صبح-روز-بعد-تمدید-می‌گردد.' => 'به طور-ميانكين-در-كمتر-از-15-دقيقه-به-درخواست-ها-باسخ-داده-مي شود.-سابقه-الوقت-باسخكويي-هر-خبير-به-درخواست-ميهمان-و-هماهنكي-با-ميزبان-در-كمتر-از-30-دقيقه-انجام-مي-شود.-حداكثر-مهلت-باسخكويي-ميزبانان-به-درخواست-رزرو-در-ساعات-كاري-30-دقيقه-است-و-در-ساعات-نيمه-شب-مهلت-باسخكويي-تا-صبح-روز-بعد-تمديد-مي كرفضد.',
    'چه ضمانتی برای تحویل اقامتگاه وجود دارد؟' => 'جه ضمانتي براي تحويل اقامتكاه وجود دارفض؟',
    'چه-ضمانتی-برای-تحویل-اقامتگاه-وجود-دارد؟' => 'جه-ضمانتي-براي-تحويل-اقامتكاه-وجود-دارفض؟',
    'بطور خلاصه کل مبلغ رزرو به شماره کارت مجموعه گیلند ملک پرداخت می شود و گیلند ملک مبلغ رزرو را در روز بعد از شروع رزرو به میزبان پرداخت میکند. لذا مهمان فرصت کافی دارد تا مشکلاتی از قبیل عدم تحویل اقامتگاه رزرو شده و یا عدم مطابقت اقامتگاه تحویل داده شده را از طریق سایت به مجموعه گیلند ملک گزارش دهد. همچین مقررات سختگیرانه ای برای میزبان شدن در گیلند ملک وجود دارد که احتمال بروز مشکلات این چنینی را به حداقل کاهش میدهد.' => 'بطور خلاصه كل مبلغ رزرو به شماره كارت مجموعه كيلند ملك برفضاخت مي شود و كيلند ملك مبلغ رزرو را در روز بعد از شروع رزرو به ميزبان برفضاخت ميكند. لذا مهمان فرصت كافي دارفض تا مشكلاتي از قبيل عدم تحويل اقامتكاه رزرو شده و يا عدم مطابقت اقامتكاه تحويل داده شده را از طريق سايت به مجموعه كيلند ملك تقرير دهد. همجين مقررات سختكيرانه اي براي ميزبان شدن در كيلند ملك وجود دارفض كه احتمال بروز مشكلات اين جنيني را به حداقل كاهش ميدهد.',
    'بطور-خلاصه-کل-مبلغ-رزرو-به-شماره-کارت-مجموعه-گیلند-ملک-پرداخت-می-شود-و-گیلند-ملک-مبلغ-رزرو-را-در-روز-بعد-از-شروع-رزرو-به-میزبان-پرداخت-میکند.-لذا-مهمان-فرصت-کافی-دارد-تا-مشکلاتی-از-قبیل-عدم-تحویل-اقامتگاه-رزرو-شده-و-یا-عدم-مطابقت-اقامتگاه-تحویل-داده-شده-را-از-طریق-سایت-به-مجموعه-گیلند-ملک-گزارش-دهد.-همچین-مقررات-سختگیرانه-ای-برای-میزبان-شدن-در-گیلند-ملک-وجود-دارد-که-احتمال-بروز-مشکلات-این-چنینی-را-به-حداقل-کاهش-میدهد.' => 'بطور-خلاصه-كل-مبلغ-رزرو-به-شماره-كارت-مجموعه-كيلند-ملك-برفضاخت-مي-شود-و-كيلند-ملك-مبلغ-رزرو-را-در-روز-بعد-از-شروع-رزرو-به-ميزبان-برفضاخت-ميكند.-لذا-مهمان-فرصت-كافي-دارفض-تا-مشكلاتي-از-قبيل-عدم-تحويل-اقامتكاه-رزرو-شده-و-يا-عدم-مطابقت-اقامتكاه-تحويل-داده-شده-را-از-طريق-سايت-به-مجموعه-كيلند-ملك-تقرير-دهد.-همجين-مقررات-سختكيرانه-اي-براي-ميزبان-شدن-در-كيلند-ملك-وجود-دارفض-كه-احتمال-بروز-مشكلات-اين-جنيني-را-به-حداقل-كاهش-ميدهد.',
    'آیا می‌توانم رزرو را قبل یا بعد از تأیید کنسل کنم؟' => 'آيا مي توانم رزرو را قبل يا بعد از تأييد كنسل كنم؟',
    'آیا-می‌توانم-رزرو-را-قبل-یا-بعد-از-تأیید-کنسل-کنم؟' => 'آیا می‌توانم رزرو را قبل یا بعد از تأیید کنسل کنم؟',
    'بله، شما می‌توانید «یک مرتبه» درخواست رزرو خود را قبل یا پس از تایید میزبان لغو کنید و درخواست دیگری را ثبت کنید ولی در صورت تکرار لغو رزرو برای بار دوم دیگر قادر به ثبت درخواست نخواهید بود. لذا در ثبت درخواست رزرو دقت لازم را به عمل آورید و با لغو رزرو مکرر موجب بی‌اعتمادی میزبان‌ها نشوید.' => 'بله، شما مي توانيد «يك مرتبه» درخواست رزرو خود را قبل يا بس از تأكيد ميزبان لغو كنيد و درخواست ديكري را إرسال كنيد ولي در صورت تكرار لغو رزرو براي بار دوم ديكر قادر به إرسال درخواست نخواهيد بود. لذا در إرسال درخواست رزرو دقت لازم را به عمل آوريد و با لغو رزرو مكرر موجب بي اعتمادي ميزبان ها نشويد.',
    'بله،-شما-می‌توانید-«یک-مرتبه»-درخواست-رزرو-خود-را-قبل-یا-پس-از-تایید-میزبان-لغو-کنید-و-درخواست-دیگری-را-ثبت-کنید-ولی-در-صورت-تکرار-لغو-رزرو-برای-بار-دوم-دیگر-قادر-به-ثبت-درخواست-نخواهید-بود.-لذا-در-ثبت-درخواست-رزرو-دقت-لازم-را-به-عمل-آورید-و-با-لغو-رزرو-مکرر-موجب-بی‌اعتمادی-میزبان‌ها-نشوید.' => 'بله،-شما-مي توانيد-«يك-مرتبه»-درخواست-رزرو-خود-را-قبل-يا-بس-از-تأكيد-ميزبان-لغو-كنيد-و-درخواست-ديكري-را-إرسال-كنيد-ولي-در-صورت-تكرار-لغو-رزرو-براي-بار-دوم-ديكر-قادر-به-إرسال-درخواست-نخواهيد-بود.-لذا-در-إرسال-درخواست-رزرو-دقت-لازم-را-به-عمل-آوريد-و-با-لغو-رزرو-مكرر-موجب-بي اعتمادي-ميزبان ها-نشويد.',
    'وقتی در سفر به شمالی یا حال خوب داری یا به دنبال حال خوب هستی و دنبال اقامتی راحت و لذت بخش در طبیعت زیبای شمال می گردی. اجاره ویلا در گیلان با گیلندملک بهترین گزینه برای تجربه یک سفر شمالی خوشایند و لذت بخش است. اینجا دستت برای اجاره ویلا در هر جای بهشت ایران استان گیلان و با هر امکاناتی بازه ؛ به فکر اجاره ویلا در شمال برای خوشگذرانی لب دریا هستی؟ یک کلبه جنگلی دنج یا ویلا استخردار برای سفر با دوستان می‌خواهی؟ شاید هم یک کلبه سوییسی در دل جنگل می خوای برای سفر خانوادگی؟گیلندملک اینجاست که به شما کمک کند به همراه عزیزانتان لحظاتی شاد و خاطره‌انگیز را در آغوش طبیعت زیبای بهشت ایران استان گیلان سپری کنید و از این سفر به یاد ماندنی لذت ببرید و هم سرمایه گذاری سودآوری تجربه کنید.' => 'وقتي در سفر به شمالي يا حال خوب داري يا به دنبال حال خوب هستي و دنبال اقامتي راحت و لذت بخش در طبيعت زيباي شمال مي كرفضي. إيجار فيلا در كيلان با كيلندملك بهترين كزينه براي تجربه يك سفر شمالي خوشايند و لذت بخش است. اينجا دستت براي إيجار فيلا در هر جاي بهشت ايران الإمارة كيلان و با هر امكاناتي بازه ؛ به فكر إيجار فيلا در شمال براي خوشكذراني لب دريا هستي؟ يك كلبه جنكلي دنج يا فيلا حوض سباحةدار براي سفر با دوستان مي خواهي؟ شايد هم يك كلبه سوييسي در دل جنكل مي خواي براي سفر خانوادكي؟كيلندملك اينجاست كه به شما كمك كند به همراه عزيزانتان لحظاتي شاد و خاطره انكيز را در آغوش طبيعت زيباي بهشت ايران الإمارة كيلان سبري كنيد و از اين سفر به ياد ماندني لذت ببريد و هم سرمايه كذاري سودآوري تجربه كنيد.',
    'وقتی-در-سفر-به-شمالی-یا-حال-خوب-داری-یا-به-دنبال-حال-خوب-هستی-و-دنبال-اقامتی-راحت-و-لذت-بخش-در-طبیعت-زیبای-شمال-می-گردی.-اجاره-ویلا-در-گیلان-با-گیلندملک-بهترین-گزینه-برای-تجربه-یک-سفر-شمالی-خوشایند-و-لذت-بخش-است.-اینجا-دستت-برای-اجاره-ویلا-در-هر-جای-بهشت-ایران-استان-گیلان-و-با-هر-امکاناتی-بازه-؛-به-فکر-اجاره-ویلا-در-شمال-برای-خوشگذرانی-لب-دریا-هستی؟-یک-کلبه-جنگلی-دنج-یا-ویلا-استخردار-برای-سفر-با-دوستان-می‌خواهی؟-شاید-هم-یک-کلبه-سوییسی-در-دل-جنگل-می-خوای-برای-سفر-خانوادگی؟گیلندملک-اینجاست-که-به-شما-کمک-کند-به-همراه-عزیزانتان-لحظاتی-شاد-و-خاطره‌انگیز-را-در-آغوش-طبیعت-زیبای-بهشت-ایران-استان-گیلان-سپری-کنید-و-از-این-سفر-به-یاد-ماندنی-لذت-ببرید-و-هم-سرمایه-گذاری-سودآوری-تجربه-کنید.' => 'وقتي-در-سفر-به-شمالي-يا-حال-خوب-داري-يا-به-دنبال-حال-خوب-هستي-و-دنبال-اقامتي-راحت-و-لذت-بخش-در-طبيعت-زيباي-شمال-مي-كرفضي.-إيجار-فيلا-در-كيلان-با-كيلندملك-بهترين-كزينه-براي-تجربه-يك-سفر-شمالي-خوشايند-و-لذت-بخش-است.-اينجا-دستت-براي-إيجار-فيلا-در-هر-جاي-بهشت-ايران-الإمارة-كيلان-و-با-هر-امكاناتي-بازه-؛-به-فكر-إيجار-فيلا-در-شمال-براي-خوشكذراني-لب-دريا-هستي؟-يك-كلبه-جنكلي-دنج-يا-فيلا-حوض سباحةدار-براي-سفر-با-دوستان-مي خواهي؟-شايد-هم-يك-كلبه-سوييسي-در-دل-جنكل-مي-خواي-براي-سفر-خانوادكي؟كيلندملك-اينجاست-كه-به-شما-كمك-كند-به-همراه-عزيزانتان-لحظاتي-شاد-و-خاطره انكيز-را-در-آغوش-طبيعت-زيباي-بهشت-ايران-الإمارة-كيلان-سبري-كنيد-و-از-اين-سفر-به-ياد-ماندني-لذت-ببريد-و-هم-سرمايه-كذاري-سودآوري-تجربه-كنيد.',
    'در گیلند ملک تلاش کردیم تا با استفاده از متد روز از جمله آموزش تخصصی مشاورین، استفاده از وکلای حقوقی با تجربه و همچنین ایجاد امکانات به روز در سایت، نیازهای ملکی مشتریان را آسان، جذاب و سریع مرتفع نماییم' => 'در كيلند ملك تلاش كرفضيم تا با استفاده از متد روز از جمله آموزش تخصصي مستشارين، استفاده از وكلاي حقوقي با تجربه و همجنين إنشاء امكانات به روز در سايت، نيازهاي ملكي العميلان را آسان، جذاب و سريع مرتفع نماييم',
    'در-گیلند-ملک-تلاش-کردیم-تا-با-استفاده-از-متد-روز-از-جمله-آموزش-تخصصی-مشاورین،-استفاده-از-وکلای-حقوقی-با-تجربه-و-همچنین-ایجاد-امکانات-به-روز-در-سایت،-نیازهای-ملکی-مشتریان-را-آسان،-جذاب-و-سریع-مرتفع-نماییم' => 'در-كيلند-ملك-تلاش-كرفضيم-تا-با-استفاده-از-متد-روز-از-جمله-آموزش-تخصصي-مستشارين،-استفاده-از-وكلاي-حقوقي-با-تجربه-و-همجنين-إنشاء-امكانات-به-روز-در-سايت،-نيازهاي-ملكي-العميلان-را-آسان،-جذاب-و-سريع-مرتفع-نماييم',
