    'function addFavorite(id) { $.get("/estates/favorite/" + id, function(data, status) { if (data.result == 1) { /* toast({ type: \'success\', text: \'ملک مورد نظر به لیست نشان شده های شما افزوده شد.\' });*/ $(".itemFavorite_" + id).addClass("text-blue-500").removeClass("text-gray-200"); //$(".itemFavorite-" + id).addClass("favorited"); } else { /*toast({ type: \'error\', text: \'ملک مورد نظر از لیست نشان شده های شما حذف شد.\' });*/ $(".itemFavorite_" + id).removeClass("text-blue-500").addClass("text-gray-200"); //$(".itemFavorite-" + id).removeClass("favorited"); } }); }' => 'function addFavorite(id) { $.get("/estates/favorite/" + id, function(data, status) { if (data.result == 1) { /* toast({ type: \'success\', text: \'ملک مورفض نظر به قائمة نشان شده های شما افزوده شد.\' });*/ $(".itemFavorite_" + id).addClass("text-blue-500").removeClass("text-gray-200"); //$(".itemFavorite-" + id).addClass("favorited"); } else { /*toast({ type: \'error\', text: \'ملک مورفض نظر از قائمة نشان شده های شما حذف شد.\' });*/ $(".itemFavorite_" + id).removeClass("text-blue-500").addClass("text-gray-200"); //$(".itemFavorite-" + id).removeClass("favorited"); } }); }',
    'function-addFavorite(id)-{-$.get("/estates/favorite/"-+-id,-function(data,-status)-{-if-(data.result-==-1)-{-/*-toast({-type:-\'success\',-text:-\'ملک-مورد-نظر-به-لیست-نشان-شده-های-شما-افزوده-شد.\'-});*/-$(".itemFavorite_"-+-id).addClass("text-blue-500").removeClass("text-gray-200");-//$(".itemFavorite-"-+-id).addClass("favorited");-}-else-{-/*toast({-type:-\'error\',-text:-\'ملک-مورد-نظر-از-لیست-نشان-شده-های-شما-حذف-شد.\'-});*/-$(".itemFavorite_"-+-id).removeClass("text-blue-500").addClass("text-gray-200");-//$(".itemFavorite-"-+-id).removeClass("favorited");-}-});-}' => 'function addFavorite(id) { $.get("/estates/favorite/" + id, function(data, status) { if (data.result == 1) { /* toast({ type: \'success\', text: \'ملک مورد نظر به لیست نشان شده های شما افزوده شد.\' });*/ $(".itemFavorite_" + id).addClass("text-blue-500").removeClass("text-gray-200"); //$(".itemFavorite-" + id).addClass("favorited"); } else { /*toast({ type: \'error\', text: \'ملک مورد نظر از لیست نشان شده های شما حذف شد.\' });*/ $(".itemFavorite_" + id).removeClass("text-blue-500").addClass("text-gray-200"); //$(".itemFavorite-" + id).removeClass("favorited"); } }); }',
    'آدرس اقامتگاه را با جزییات کامل وارد کنید تا میهمان پس از رزرو به راحتی بتوانند اقامتگاه را پیدا کنند.' => 'الالعنوان اقامتكاه را با جزييات كامل وارفض كنيد تا ميهمان بس از رزرو به راحتي بتوانند اقامتكاه را بيدا كنند.',
    'آدرس-اقامتگاه-را-با-جزییات-کامل-وارد-کنید-تا-میهمان-پس-از-رزرو-به-راحتی-بتوانند-اقامتگاه-را-پیدا-کنند.' => 'الالعنوان-اقامتكاه-را-با-جزييات-كامل-وارفض-كنيد-تا-ميهمان-بس-از-رزرو-به-راحتي-بتوانند-اقامتكاه-را-بيدا-كنند.',
    'موقعیت مکانی (لوکیشن) را به دقت مشخص کنید.' => 'موقعيت مكاني (لوكيشن) را به دقت مشخص كنيد.',
    'موقعیت-مکانی-(لوکیشن)-را-به-دقت-مشخص-کنید.' => 'موقعیت مکانی (لوکیشن) را به دقت مشخص کنید.',
    'لوکیشن ثبت شده برای مسیریابی به مهمانان ارسال می‌شود. طبق ضمانت تحویل گیلندملک، هرگونه مغایرت می‌تواند باعث لغو رزرو و عودت وجه به مهمان شود.' => 'لوكيشن إرسال شده براي مسيريابي به مهمانان إرسال مي شود. طبق ضمانت تحويل كيلندملك، هركونه مغايرت مي تواند باعث لغو رزرو و عودت وجه به مهمان شود.',
    'لوکیشن-ثبت-شده-برای-مسیریابی-به-مهمانان-ارسال-می‌شود.-طبق-ضمانت-تحویل-گیلندملک،-هرگونه-مغایرت-می‌تواند-باعث-لغو-رزرو-و-عودت-وجه-به-مهمان-شود.' => 'لوكيشن-إرسال-شده-براي-مسيريابي-به-مهمانان-إرسال-مي شود.-طبق-ضمانت-تحويل-كيلندملك،-هركونه-مغايرت-مي تواند-باعث-لغو-رزرو-و-عودت-وجه-به-مهمان-شود.',
    'سیاست سهلگیرانه: در صورتی که رزرو، بیش از ۲۴ ساعت از تاریخ ورود لغو گردد میزبان دریافتی ندارد. درصورت لغو کمتر از 24 ساعت به تاریخ ورود، اجاره شب اول به میزبان پرداخت می شود.' => 'سياست سهلكيرانه: در صورتي كه رزرو، بيش از ۲۴ ساعت از التاريخ تسجيل الدخول لغو كرفضد ميزبان استلامي ندارفض. درصورت لغو كمتر از 24 ساعت به التاريخ تسجيل الدخول، إيجار شب اول به ميزبان برفضاخت مي شود.',
    'سیاست-سهلگیرانه:-در-صورتی-که-رزرو،-بیش-از-۲۴-ساعت-از-تاریخ-ورود-لغو-گردد-میزبان-دریافتی-ندارد.-درصورت-لغو-کمتر-از-24-ساعت-به-تاریخ-ورود،-اجاره-شب-اول-به-میزبان-پرداخت-می-شود.' => 'سياست-سهلكيرانه:-در-صورتي-كه-رزرو،-بيش-از-۲۴-ساعت-از-التاريخ-تسجيل الدخول-لغو-كرفضد-ميزبان-استلامي-ندارفض.-درصورت-لغو-كمتر-از-24-ساعت-به-التاريخ-تسجيل الدخول،-إيجار-شب-اول-به-ميزبان-برفضاخت-مي-شود.',
    'سیاست متعادل: در صورتی که رزرو, بیش از 3 روز کامل از تاریخ ورود لغو گردد, میزبان دریافتی ندارد. درصورت لغو کمتر از 3 روز به تاریخ ورود، اجاره شب اول به میزبان پرداخت می شود.' => 'سياست متعادل: در صورتي كه رزرو, بيش از 3 روز كامل از التاريخ تسجيل الدخول لغو كرفضد, ميزبان استلامي ندارفض. درصورت لغو كمتر از 3 روز به التاريخ تسجيل الدخول، إيجار شب اول به ميزبان برفضاخت مي شود.',
    'سیاست-متعادل:-در-صورتی-که-رزرو,-بیش-از-3-روز-کامل-از-تاریخ-ورود-لغو-گردد,-میزبان-دریافتی-ندارد.-درصورت-لغو-کمتر-از-3-روز-به-تاریخ-ورود،-اجاره-شب-اول-به-میزبان-پرداخت-می-شود.' => 'سياست-متعادل:-در-صورتي-كه-رزرو,-بيش-از-3-روز-كامل-از-التاريخ-تسجيل الدخول-لغو-كرفضد,-ميزبان-استلامي-ندارفض.-درصورت-لغو-كمتر-از-3-روز-به-التاريخ-تسجيل الدخول،-إيجار-شب-اول-به-ميزبان-برفضاخت-مي-شود.',
    'سیاست سختگیرانه: در صورتی که رزرو, بیش از 5 روز کامل از تاریخ ورود لغو گردد, 10% صورتحساب به میزبان پرداخت می‏شود. درصورت لغو کمتر از 5 روز به تاریخ ورود، اجاره شب اول بعلاوه 40 درصد از شب‌های باقیمانده به میزبان پرداخت می شود.' => 'سياست سختكيرانه: در صورتي كه رزرو, بيش از 5 روز كامل از التاريخ تسجيل الدخول لغو كرفضد, 10% صورتحساب به ميزبان برفضاخت مي‏شود. درصورت لغو كمتر از 5 روز به التاريخ تسجيل الدخول، إيجار شب اول بعلاوه 40 درصد از شب هاي باقيمانده به ميزبان برفضاخت مي شود.',
    'سیاست-سختگیرانه:-در-صورتی-که-رزرو,-بیش-از-5-روز-کامل-از-تاریخ-ورود-لغو-گردد,-10%-صورتحساب-به-میزبان-پرداخت-می‏شود.-درصورت-لغو-کمتر-از-5-روز-به-تاریخ-ورود،-اجاره-شب-اول-بعلاوه-40-درصد-از-شب‌های-باقیمانده-به-میزبان-پرداخت-می-شود.' => 'سياست-سختكيرانه:-در-صورتي-كه-رزرو,-بيش-از-5-روز-كامل-از-التاريخ-تسجيل الدخول-لغو-كرفضد,-10%-صورتحساب-به-ميزبان-برفضاخت-مي‏شود.-درصورت-لغو-كمتر-از-5-روز-به-التاريخ-تسجيل الدخول،-إيجار-شب-اول-بعلاوه-40-درصد-از-شب هاي-باقيمانده-به-ميزبان-برفضاخت-مي-شود.',
    'امکانات و تجهیزات موجود در اقامتگاه خود را مشخص کنید' => 'امكانات و تجهيزات موجود در اقامتكاه خود را مشخص كنيد',
    'امکانات-و-تجهیزات-موجود-در-اقامتگاه-خود-را-مشخص-کنید' => 'امكانات-و-تجهيزات-موجود-در-اقامتكاه-خود-را-مشخص-كنيد',
    'در اینجا نکاتی را که میهمان شما باید بداند بنویسید، از نقاط قوت و ضعف اقامتگاه، بعنوان مثال از تعداد زیاد پله ها که برای سالمندان مناسب نیست و ورودی تنگ پارکینگ، از چشم انداز زیبای منزل یا از جاذبه های گردشگری ‏اطراف همچون ساحل دریا/رودخانه/کوهستان/ اماکن تاریخی/بازار محلی بگویید و فاصله اقامتگاه از هر یک را بنویسید. وجود فروشگاههای مواد غذایی و نانوایی در مجاورت منزل خود را مشخص ‏کنید.‏‎ از حال و هوای محله و رفتار احتمالی همسایه ها بنویسید. هر آنچه میهمان شما لازم است بداند را اینجا بنویسید.‏‎' => 'در اينجا نكاتي را كه ميهمان شما بايد بداند بنويسيد، از نقاط قوت و ضعف اقامتكاه، بالعنوان مثال از تعداد زياد بله ها كه براي سالمندان مناسب نيست و تسجيل الدخولي تنك موقف سيارات، از جشم انداز زيباي منزل يا از جاذبه هاي كرفضشكري ‏اطراف همجون ساحل دريا/رودخانه/كوهستان/ اماكن التاريخي/بازار محلي بكوييد و فاصله اقامتكاه از هر يك را بنويسيد. وجود بيعكاههاي مواد غذايي و نانوايي در مجاورت منزل خود را مشخص ‏كنيد.‏‎ از حال و هواي محله و رفتار احتمالي همسايه ها بنويسيد. هر آنجه ميهمان شما لازم است بداند را اينجا بنويسيد.‏‎',
    'در-اینجا-نکاتی-را-که-میهمان-شما-باید-بداند-بنویسید،-از-نقاط-قوت-و-ضعف-اقامتگاه،-بعنوان-مثال-از-تعداد-زیاد-پله-ها-که-برای-سالمندان-مناسب-نیست-و-ورودی-تنگ-پارکینگ،-از-چشم-انداز-زیبای-منزل-یا-از-جاذبه-های-گردشگری-‏اطراف-همچون-ساحل-دریا/رودخانه/کوهستان/-اماکن-تاریخی/بازار-محلی-بگویید-و-فاصله-اقامتگاه-از-هر-یک-را-بنویسید.-وجود-فروشگاههای-مواد-غذایی-و-نانوایی-در-مجاورت-منزل-خود-را-مشخص-‏کنید.‏‎-از-حال-و-هوای-محله-و-رفتار-احتمالی-همسایه-ها-بنویسید.-هر-آنچه-میهمان-شما-لازم-است-بداند-را-اینجا-بنویسید.‏‎' => 'در-اينجا-نكاتي-را-كه-ميهمان-شما-بايد-بداند-بنويسيد،-از-نقاط-قوت-و-ضعف-اقامتكاه،-بالعنوان-مثال-از-تعداد-زياد-بله-ها-كه-براي-سالمندان-مناسب-نيست-و-تسجيل الدخولي-تنك-موقف سيارات،-از-جشم-انداز-زيباي-منزل-يا-از-جاذبه-هاي-كرفضشكري-‏اطراف-همجون-ساحل-دريا/رودخانه/كوهستان/-اماكن-التاريخي/بازار-محلي-بكوييد-و-فاصله-اقامتكاه-از-هر-يك-را-بنويسيد.-وجود-بيعكاههاي-مواد-غذايي-و-نانوايي-در-مجاورت-منزل-خود-را-مشخص-‏كنيد.‏‎-از-حال-و-هواي-محله-و-رفتار-احتمالي-همسايه-ها-بنويسيد.-هر-آنجه-ميهمان-شما-لازم-است-بداند-را-اينجا-بنويسيد.‏‎',
    'ارائه تصاویر زیبا و واقعی از اقامتگاه شما می تواند نقش بسیار مهمی در جلب نظر میهمانان ایفا نماید.‏‎‏ لذا:' => 'ارائه تصاوير زيبا و واقعي از اقامتكاه شما مي تواند نقش بسيار مهمي در جلب نظر ميهمانان ايفا نمايد.‏‎‏ لذا:',
    'ارائه-تصاویر-زیبا-و-واقعی-از-اقامتگاه-شما-می-تواند-نقش-بسیار-مهمی-در-جلب-نظر-میهمانان-ایفا-نماید.‏‎‏-لذا:' => 'ارائه-تصاوير-زيبا-و-واقعي-از-اقامتكاه-شما-مي-تواند-نقش-بسيار-مهمي-در-جلب-نظر-ميهمانان-ايفا-نمايد.‏‎‏-لذا:',
    'برای سرعت بخشیدن به فرایند ثبت اقامتگاه حتما' => 'براي سرعت بخشيدن به فرايند إرسال اقامتكاه حتما',
    'برای-سرعت-بخشیدن-به-فرایند-ثبت-اقامتگاه-حتما' => 'براي-سرعت-بخشيدن-به-فرايند-إرسال-اقامتكاه-حتما',
    'نام مالک اقامتگاه' => 'الاسم المالك اقامتكاه',
    'نام-مالک-اقامتگاه' => 'الاسم-المالك-اقامتكاه',
    'برای تکمیل اطلاعات مالک به صفحه ویرایش پروفایل منتقل می شوید' => 'براي تكميل المعلومات المالك به صفحه تعديل بروملف منتقل مي شويد',
    'برای-تکمیل-اطلاعات-مالک-به-صفحه-ویرایش-پروفایل-منتقل-می-شوید' => 'براي-تكميل-المعلومات-المالك-به-صفحه-تعديل-بروملف-منتقل-مي-شويد',
    'در صورتی که رزرو, بیش از 5 روز کامل از تاریخ ورود لغو گردد, 10% صورتحساب به میزبان پرداخت می‏شود. درصورت لغو کمتر از 5 روز به تاریخ ورود، اجاره شب اول بعلاوه 40 درصد از شب‌های باقیمانده به میزبان پرداخت می شود.' => 'در صورتي كه رزرو, بيش از 5 روز كامل از التاريخ تسجيل الدخول لغو كرفضد, 10% صورتحساب به ميزبان برفضاخت مي‏شود. درصورت لغو كمتر از 5 روز به التاريخ تسجيل الدخول، إيجار شب اول بعلاوه 40 درصد از شب هاي باقيمانده به ميزبان برفضاخت مي شود.',
    'در-صورتی-که-رزرو,-بیش-از-5-روز-کامل-از-تاریخ-ورود-لغو-گردد,-10%-صورتحساب-به-میزبان-پرداخت-می‏شود.-درصورت-لغو-کمتر-از-5-روز-به-تاریخ-ورود،-اجاره-شب-اول-بعلاوه-40-درصد-از-شب‌های-باقیمانده-به-میزبان-پرداخت-می-شود.' => 'در-صورتي-كه-رزرو,-بيش-از-5-روز-كامل-از-التاريخ-تسجيل الدخول-لغو-كرفضد,-10%-صورتحساب-به-ميزبان-برفضاخت-مي‏شود.-درصورت-لغو-كمتر-از-5-روز-به-التاريخ-تسجيل الدخول،-إيجار-شب-اول-بعلاوه-40-درصد-از-شب هاي-باقيمانده-به-ميزبان-برفضاخت-مي-شود.',
    'در صورتی که رزرو, بیش از 3 روز کامل از تاریخ ورود لغو گردد, میزبان دریافتی ندارد. درصورت لغو کمتر از 3 روز به تاریخ ورود، اجاره شب اول به میزبان پرداخت می شود.' => 'در صورتي كه رزرو, بيش از 3 روز كامل از التاريخ تسجيل الدخول لغو كرفضد, ميزبان استلامي ندارفض. درصورت لغو كمتر از 3 روز به التاريخ تسجيل الدخول، إيجار شب اول به ميزبان برفضاخت مي شود.',
    'در-صورتی-که-رزرو,-بیش-از-3-روز-کامل-از-تاریخ-ورود-لغو-گردد,-میزبان-دریافتی-ندارد.-درصورت-لغو-کمتر-از-3-روز-به-تاریخ-ورود،-اجاره-شب-اول-به-میزبان-پرداخت-می-شود.' => 'در-صورتي-كه-رزرو,-بيش-از-3-روز-كامل-از-التاريخ-تسجيل الدخول-لغو-كرفضد,-ميزبان-استلامي-ندارفض.-درصورت-لغو-كمتر-از-3-روز-به-التاريخ-تسجيل الدخول،-إيجار-شب-اول-به-ميزبان-برفضاخت-مي-شود.',
    'در صورتی که رزرو، بیش از ۲۴ ساعت از تاریخ ورود لغو گردد میزبان دریافتی ندارد. درصورت لغو کمتر از 24 ساعت به تاریخ ورود، اجاره شب اول به میزبان پرداخت می شود.' => 'در صورتي كه رزرو، بيش از ۲۴ ساعت از التاريخ تسجيل الدخول لغو كرفضد ميزبان استلامي ندارفض. درصورت لغو كمتر از 24 ساعت به التاريخ تسجيل الدخول، إيجار شب اول به ميزبان برفضاخت مي شود.',
    'در-صورتی-که-رزرو،-بیش-از-۲۴-ساعت-از-تاریخ-ورود-لغو-گردد-میزبان-دریافتی-ندارد.-درصورت-لغو-کمتر-از-24-ساعت-به-تاریخ-ورود،-اجاره-شب-اول-به-میزبان-پرداخت-می-شود.' => 'در-صورتي-كه-رزرو،-بيش-از-۲۴-ساعت-از-التاريخ-تسجيل الدخول-لغو-كرفضد-ميزبان-استلامي-ندارفض.-درصورت-لغو-كمتر-از-24-ساعت-به-التاريخ-تسجيل الدخول،-إيجار-شب-اول-به-ميزبان-برفضاخت-مي-شود.',
    '4,9 (32 نظر ثبت شده)' => '4,9 (32 نظر إرسال شده)',
