    '(به معنای اتاقک‌ کلبه‌مانندی که در کنار مراتع و مزارع برای استراحت ساخته می شد)، بازمی‌گردد.' => '(به معناي غرفةك كلبه مانندي كه در كنار مراتع و مزارع براي استراحت ساخته مي شد)، بازمي كرفضد.',
    '(به-معنای-اتاقک‌-کلبه‌مانندی-که-در-کنار-مراتع-و-مزارع-برای-استراحت-ساخته-می-شد)،-بازمی‌گردد.' => '(به-معناي-غرفةك -كلبه مانندي-كه-در-كنار-مراتع-و-مزارع-براي-استراحت-ساخته-مي-شد)،-بازمي كرفضد.',
