    'ما در حال ارزیابی مجدد نحوه خرید ، فروش و اجاره هستیم. اکنون ورود به مکانی که دوست دارید راحت تر است. بیایید با هم این کار را انجام دهیم.' => 'ما در حال ارزیابی مجدد نحوه شراء ، بيع و إيجار هستیم. اکنون تسجيل الدخول به مکانی که دوست دارید راحت تر است. بیایید با هم این کار را انجام دهیم.',
    'ما-در-حال-ارزیابی-مجدد-نحوه-خرید-،-فروش-و-اجاره-هستیم.-اکنون-ورود-به-مکانی-که-دوست-دارید-راحت-تر-است.-بیایید-با-هم-این-کار-را-انجام-دهیم.' => 'ما در حال ارزیابی مجدد نحوه خرید ، فروش و اجاره هستیم. اکنون ورود به مکانی که دوست دارید راحت تر است. بیایید با هم این کار را انجام دهیم.',
