    'گیلند ملک مجوعه ای آموزش دیده از کارشناسان و مشاوران املاک با تجربه هستند که با هدف خدمت رسانی درست و اصولی فعالیت خود را در سال های اخیر به صورت گسترده و در فضای مجازی آغاز کرده است .' => 'كيلند ملك مجوعه اي آموزش ديده از خبيران و مستشاران املاك با تجربه هستند كه با هدف خدمت رساني درست و اصولي نشطيت خود را در سال هاي اخير به صورت كسترفضه و در فضاي مجازي آغاز كرفضه است .',
    'گیلند-ملک-مجوعه-ای-آموزش-دیده-از-کارشناسان-و-مشاوران-املاک-با-تجربه-هستند-که-با-هدف-خدمت-رسانی-درست-و-اصولی-فعالیت-خود-را-در-سال-های-اخیر-به-صورت-گسترده-و-در-فضای-مجازی-آغاز-کرده-است-.' => 'كيلند-ملك-مجوعه-اي-آموزش-ديده-از-خبيران-و-مستشاران-املاك-با-تجربه-هستند-كه-با-هدف-خدمت-رساني-درست-و-اصولي-نشطيت-خود-را-در-سال-هاي-اخير-به-صورت-كسترفضه-و-در-فضاي-مجازي-آغاز-كرفضه-است-.',
    'از دیگر اهداف گیلند ملک به عنوان یک مجموعه در زمینه املاک و مستغلات در منطقه گیلان ، ارایه خدماتی حرفه ای و کارآمد در زمینه معاملات ملکی در استان گیلان می باشد و تمام تلاش خود را می کند تا با صداقت تمام به سرمایه گذاران و مشتریان بهترین خدمات را ارایه دهد و شما بتوانید خرید امن و مطمعن در کنار آرامش داشته باشید.' => 'از ديكر اهداف كيلند ملك به العنوان يك مجموعه در أرضه املاك و عقارات در المنطقة كيلان ، ارايه خدماتي حرفه اي و كارآمد در أرضه معاملات ملكي در الإمارة كيلان مي باشد و تمام تلاش خود را مي كند تا با صداقت تمام به سرمايه كذاران و العميلان بهترين خدمات را ارايه دهد و شما بتوانيد شراء امن و مطمعن در كنار آرامش داشته باشيد.',
    'از-دیگر-اهداف-گیلند-ملک-به-عنوان-یک-مجموعه-در-زمینه-املاک-و-مستغلات-در-منطقه-گیلان-،-ارایه-خدماتی-حرفه-ای-و-کارآمد-در-زمینه-معاملات-ملکی-در-استان-گیلان-می-باشد-و-تمام-تلاش-خود-را-می-کند-تا-با-صداقت-تمام-به-سرمایه-گذاران-و-مشتریان-بهترین-خدمات-را-ارایه-دهد-و-شما-بتوانید-خرید-امن-و-مطمعن-در-کنار-آرامش-داشته-باشید.' => 'از-ديكر-اهداف-كيلند-ملك-به-العنوان-يك-مجموعه-در-أرضه-املاك-و-عقارات-در-المنطقة-كيلان-،-ارايه-خدماتي-حرفه-اي-و-كارآمد-در-أرضه-معاملات-ملكي-در-الإمارة-كيلان-مي-باشد-و-تمام-تلاش-خود-را-مي-كند-تا-با-صداقت-تمام-به-سرمايه-كذاران-و-العميلان-بهترين-خدمات-را-ارايه-دهد-و-شما-بتوانيد-شراء-امن-و-مطمعن-در-كنار-آرامش-داشته-باشيد.',
