    'برخی از ملک ها و زمین ها در گیلان پر سودتر می باشد از جمله :' => 'برخي از ملك ها و أرض ها در كيلان بر سودتر مي باشد از جمله :',
    'برخی-از-ملک-ها-و-زمین-ها-در-گیلان-پر-سودتر-می-باشد-از-جمله-:' => 'برخي-از-ملك-ها-و-أرض-ها-در-كيلان-بر-سودتر-مي-باشد-از-جمله-:',
    'ویلاهای دریاچه ای و زمین های جنگلی و ساحلی که به توجه به حجم بالای مسافران و گردشگری در این مناطق می تواند به طور طبیعی سودهای زیادی هم بر ارزش ملک و هم کسب درآمد داشته باشد.' => 'فيلاهاي درياجه اي و أرض هاي جنكلي و ساحلي كه به توجه به حجم بالاي مسافران و كرفضشكري در اين مناطق مي تواند به طور طبيعي سودهاي زيادي هم بر ارزش ملك و هم كسب درآمد داشته باشد.',
    'ویلاهای-دریاچه-ای-و-زمین-های-جنگلی-و-ساحلی-که-به-توجه-به-حجم-بالای-مسافران-و-گردشگری-در-این-مناطق-می-تواند-به-طور-طبیعی-سودهای-زیادی-هم-بر-ارزش-ملک-و-هم-کسب-درآمد-داشته-باشد.' => 'فيلاهاي-درياجه-اي-و-أرض-هاي-جنكلي-و-ساحلي-كه-به-توجه-به-حجم-بالاي-مسافران-و-كرفضشكري-در-اين-مناطق-مي-تواند-به-طور-طبيعي-سودهاي-زيادي-هم-بر-ارزش-ملك-و-هم-كسب-درآمد-داشته-باشد.',
    'همچنین ملک های تجاری و خدماتی در شهرهایی مثل رشت، لاهیجان، منطقه آزاد بندر انزلی به عنوان مراکز اقتصادی و تجاری ارایه دهنده انواعفرصت های سرمایه گذاری و کسب و کار می باشد.' => 'همجنين ملك هاي تجاري و خدماتي در المدينةهايي مثل رشت، لاهيجان، المنطقة آزاد بندر انزلي به العنوان مراكز اقتصادي و تجاري ارايه دهنده انواعفرصت هاي سرمايه كذاري و كسب و كار مي باشد.',
    'همچنین-ملک-های-تجاری-و-خدماتی-در-شهرهایی-مثل-رشت،-لاهیجان،-منطقه-آزاد-بندر-انزلی-به-عنوان-مراکز-اقتصادی-و-تجاری-ارایه-دهنده-انواعفرصت-های-سرمایه-گذاری-و-کسب-و-کار-می-باشد.' => 'همجنين-ملك-هاي-تجاري-و-خدماتي-در-المدينةهايي-مثل-رشت،-لاهيجان،-المنطقة-آزاد-بندر-انزلي-به-العنوان-مراكز-اقتصادي-و-تجاري-ارايه-دهنده-انواعفرصت-هاي-سرمايه-كذاري-و-كسب-و-كار-مي-باشد.',
    'در کل برای بهره برداری حداکثری و داشتن ملک سودآور در گیلان باید تحقیقات دقیقی انجام دهید و بازار ملک را ب ه خوبی بررسی کنید و نیاز بازار و تقاضا و همچنین شرایط اقتصادی را در نظر بگیرید و از مشاورین املاک با تجربه و آموزش دیده کمک بگیرید. جهت ارتباط با کارشناسان ما در این زمینه می توانید به قسمت کارشناسان در سایت مراجعه نمایید یا با دفتر گیلند ملک به شماره 01344624078 تماس حاصل فرمایید.' => 'در كل براي بهره برفضاري حداكثري و داشتن ملك سودآور در كيلان بايد تحقيقات دقيقي انجام دهيد و بازار ملك را ب ه خوبي بررسي كنيد و نياز بازار و تقاضا و همجنين شرايط اقتصادي را در نظر بكيريد و از مستشارين املاك با تجربه و آموزش ديده كمك بكيريد. جهت ارتباط با خبيران ما در اين أرضه مي توانيد به قسمت خبيران در سايت مراجعه نماييد يا با دفتر كيلند ملك به شماره 01344624078 تماس حاصل فرماييد.',
    'در-کل-برای-بهره-برداری-حداکثری-و-داشتن-ملک-سودآور-در-گیلان-باید-تحقیقات-دقیقی-انجام-دهید-و-بازار-ملک-را-ب-ه-خوبی-بررسی-کنید-و-نیاز-بازار-و-تقاضا-و-همچنین-شرایط-اقتصادی-را-در-نظر-بگیرید-و-از-مشاورین-املاک-با-تجربه-و-آموزش-دیده-کمک-بگیرید.-جهت-ارتباط-با-کارشناسان-ما-در-این-زمینه-می-توانید-به-قسمت-کارشناسان-در-سایت-مراجعه-نمایید-یا-با-دفتر-گیلند-ملک-به-شماره-01344624078-تماس-حاصل-فرمایید.' => 'در-كل-براي-بهره-برفضاري-حداكثري-و-داشتن-ملك-سودآور-در-كيلان-بايد-تحقيقات-دقيقي-انجام-دهيد-و-بازار-ملك-را-ب-ه-خوبي-بررسي-كنيد-و-نياز-بازار-و-تقاضا-و-همجنين-شرايط-اقتصادي-را-در-نظر-بكيريد-و-از-مستشارين-املاك-با-تجربه-و-آموزش-ديده-كمك-بكيريد.-جهت-ارتباط-با-خبيران-ما-در-اين-أرضه-مي-توانيد-به-قسمت-خبيران-در-سايت-مراجعه-نماييد-يا-با-دفتر-كيلند-ملك-به-شماره-01344624078-تماس-حاصل-فرماييد.',
    'من مشاور املاک هستم چگونه می توانم با گیلند ملک همکاری کنم و ملک های خود را ثبت کنم ؟' => 'من مستشار املاك هستم جكونه مي توانم با كيلند ملك همكاري كنم و ملك هاي خود را إرسال كنم ؟',
    'من-مشاور-املاک-هستم-چگونه-می-توانم-با-گیلند-ملک-همکاری-کنم-و-ملک-های-خود-را-ثبت-کنم-؟' => 'من-مستشار-املاك-هستم-جكونه-مي-توانم-با-كيلند-ملك-همكاري-كنم-و-ملك-هاي-خود-را-إرسال-كنم-؟',
    'از قسمت ثبت رایگان ملک می توانید ملک های خود را با شماره همراه خود قرار دهید تا مشتریان به شما ارتباط بگیرند . حتی می توانید با مدیر مجموعه گیلندملک ارتباط بگیرید و بعد از گذراندن مراحلی در سایت به عنوان کارشناس فروش فعالیت خود را گسترده تر کنید.' => 'از قسمت إرسال رايكان ملك مي توانيد ملك هاي خود را با شماره همراه خود قرار دهيد تا العميلان به شما ارتباط بكيرند . حتي مي توانيد با مدير مجموعه كيلندملك ارتباط بكيريد و بعد از كذراندن مراحلي در سايت به العنوان خبير بيع نشطيت خود را كسترفضه تر كنيد.',
    'از-قسمت-ثبت-رایگان-ملک-می-توانید-ملک-های-خود-را-با-شماره-همراه-خود-قرار-دهید-تا-مشتریان-به-شما-ارتباط-بگیرند-.-حتی-می-توانید-با-مدیر-مجموعه-گیلندملک-ارتباط-بگیرید-و-بعد-از-گذراندن-مراحلی-در-سایت-به-عنوان-کارشناس-فروش-فعالیت-خود-را-گسترده-تر-کنید.' => 'از-قسمت-إرسال-رايكان-ملك-مي-توانيد-ملك-هاي-خود-را-با-شماره-همراه-خود-قرار-دهيد-تا-العميلان-به-شما-ارتباط-بكيرند-.-حتي-مي-توانيد-با-مدير-مجموعه-كيلندملك-ارتباط-بكيريد-و-بعد-از-كذراندن-مراحلي-در-سايت-به-العنوان-خبير-بيع-نشطيت-خود-را-كسترفضه-تر-كنيد.',
    'اگر ملکی که مد نظر من هست در سایت موجود نبود آیا راهکار دیگری برای پیدا کردن ملک دارید ؟' => 'اكر ملكي كه مد نظر من هست در سايت موجود نبود آيا راهكار ديكري براي بيدا كرفضن ملك داريد ؟',
    'اگر-ملکی-که-مد-نظر-من-هست-در-سایت-موجود-نبود-آیا-راهکار-دیگری-برای-پیدا-کردن-ملک-دارید-؟' => 'اكر-ملكي-كه-مد-نظر-من-هست-در-سايت-موجود-نبود-آيا-راهكار-ديكري-براي-بيدا-كرفضن-ملك-داريد-؟',
    'با توجه به نیاز شما در صورتی که ملک مورد نظرتان در سایت موجود نبود می توانید با کارشناسان گیلند ملک ارتباط بگیرید و تمام جزییات و مشخصات ملک مورد نظر را ذکر کنید تا یادداشت شود و به محض موجود شدن ملک شما در سایت یا ملک های مشابه آن پیامک برای شما ارسال می شود و شما مطلع می شوید.' => 'با توجه به نياز شما در صورتي كه ملك مورفض نظرتان در سايت موجود نبود مي توانيد با خبيران كيلند ملك ارتباط بكيريد و تمام جزييات و مشخصات ملك مورفض نظر را ذكر كنيد تا يادداشت شود و به محض موجود شدن ملك شما در سايت يا ملك هاي مشابه آن رسالةك براي شما إرسال مي شود و شما مطلع مي شويد.',
    'با-توجه-به-نیاز-شما-در-صورتی-که-ملک-مورد-نظرتان-در-سایت-موجود-نبود-می-توانید-با-کارشناسان-گیلند-ملک-ارتباط-بگیرید-و-تمام-جزییات-و-مشخصات-ملک-مورد-نظر-را-ذکر-کنید-تا-یادداشت-شود-و-به-محض-موجود-شدن-ملک-شما-در-سایت-یا-ملک-های-مشابه-آن-پیامک-برای-شما-ارسال-می-شود-و-شما-مطلع-می-شوید.' => 'با-توجه-به-نياز-شما-در-صورتي-كه-ملك-مورفض-نظرتان-در-سايت-موجود-نبود-مي-توانيد-با-خبيران-كيلند-ملك-ارتباط-بكيريد-و-تمام-جزييات-و-مشخصات-ملك-مورفض-نظر-را-ذكر-كنيد-تا-يادداشت-شود-و-به-محض-موجود-شدن-ملك-شما-در-سايت-يا-ملك-هاي-مشابه-آن-رسالةك-براي-شما-إرسال-مي-شود-و-شما-مطلع-مي-شويد.',
    'آیا گیلند ملک در شهرهای دیگر نیز نمایندگی دارد؟' => 'آيا كيلند ملك در المدينةهاي ديكر نيز نمايندكي دارفض؟',
    'آیا-گیلند-ملک-در-شهرهای-دیگر-نیز-نمایندگی-دارد؟' => 'آيا-كيلند-ملك-در-المدينةهاي-ديكر-نيز-نمايندكي-دارفض؟',
    'در حال حاضر دفتر گیلند ملک در رضوانشهر می باشد و نمایندگی هایی در استان های مختلف به صورت دورکاری در حال فعالیت و همکاری با مجموعه هستند در صورتی که شما هم تمایل به همکاری با مجموعه را دارید می توانید با دفتر تماس بگیرید تا راهنمایی های لازم انجام شود.' => 'در حال حاضر دفتر كيلند ملك در رضوانالمدينة مي باشد و نمايندكي هايي در الإمارة هاي مختلف به صورت دوركاري در حال نشطيت و همكاري با مجموعه هستند در صورتي كه شما هم تمايل به همكاري با مجموعه را داريد مي توانيد با دفتر تماس بكيريد تا راهنمايي هاي لازم انجام شود.',
    'در-حال-حاضر-دفتر-گیلند-ملک-در-رضوانشهر-می-باشد-و-نمایندگی-هایی-در-استان-های-مختلف-به-صورت-دورکاری-در-حال-فعالیت-و-همکاری-با-مجموعه-هستند-در-صورتی-که-شما-هم-تمایل-به-همکاری-با-مجموعه-را-دارید-می-توانید-با-دفتر-تماس-بگیرید-تا-راهنمایی-های-لازم-انجام-شود.' => 'در-حال-حاضر-دفتر-كيلند-ملك-در-رضوانالمدينة-مي-باشد-و-نمايندكي-هايي-در-الإمارة-هاي-مختلف-به-صورت-دوركاري-در-حال-نشطيت-و-همكاري-با-مجموعه-هستند-در-صورتي-كه-شما-هم-تمايل-به-همكاري-با-مجموعه-را-داريد-مي-توانيد-با-دفتر-تماس-بكيريد-تا-راهنمايي-هاي-لازم-انجام-شود.',
    'آیا گیلند ملک مشاوره برای سرمایه گذاری پرسود به من می دهد؟' => 'آيا كيلند ملك مستشاره براي سرمايه كذاري برسود به من مي دهد؟',
    'آیا-گیلند-ملک-مشاوره-برای-سرمایه-گذاری-پرسود-به-من-می-دهد؟' => 'آيا-كيلند-ملك-مستشاره-براي-سرمايه-كذاري-برسود-به-من-مي-دهد؟',
    'بله گیلند ملک با توجه به تجربه و دانش خود در زمینه بازار ملک گیلان و با تحلیل و بررسی موثر روند بازار می تواند پیشنهادات قابل اعتمادی در زمینه سرمایه گذاری به شما بدهد.' => 'بله كيلند ملك با توجه به تجربه و دانش خود در أرضه بازار ملك كيلان و با تحليل و بررسي موثر روند بازار مي تواند بيشنهادات قابل اعتمادي در أرضه سرمايه كذاري به شما بدهد.',
    'بله-گیلند-ملک-با-توجه-به-تجربه-و-دانش-خود-در-زمینه-بازار-ملک-گیلان-و-با-تحلیل-و-بررسی-موثر-روند-بازار-می-تواند-پیشنهادات-قابل-اعتمادی-در-زمینه-سرمایه-گذاری-به-شما-بدهد.' => 'بله-كيلند-ملك-با-توجه-به-تجربه-و-دانش-خود-در-أرضه-بازار-ملك-كيلان-و-با-تحليل-و-بررسي-موثر-روند-بازار-مي-تواند-بيشنهادات-قابل-اعتمادي-در-أرضه-سرمايه-كذاري-به-شما-بدهد.',
    'همچنین گیلند ملک می تواند به شما در ارزیابی سودآوری و ریسک ها ، درک قوانین مربوط به سرمایه گذاری در ملک ها در گیلان ، راهنمایی در معاملات و مراحل قانونی، و تامین اطلاعات کامل و معتبر در مورد بازار ملک گیلان به شما کمک کند.' => 'همجنين كيلند ملك مي تواند به شما در ارزيابي سودآوري و ريسك ها ، درك قوانين مربوط به سرمايه كذاري در ملك ها در كيلان ، راهنمايي در معاملات و مراحل قانوني، و تامين المعلومات كامل و معتبر در مورفض بازار ملك كيلان به شما كمك كند.',
    'همچنین-گیلند-ملک-می-تواند-به-شما-در-ارزیابی-سودآوری-و-ریسک-ها-،-درک-قوانین-مربوط-به-سرمایه-گذاری-در-ملک-ها-در-گیلان-،-راهنمایی-در-معاملات-و-مراحل-قانونی،-و-تامین-اطلاعات-کامل-و-معتبر-در-مورد-بازار-ملک-گیلان-به-شما-کمک-کند.' => 'همجنين-كيلند-ملك-مي-تواند-به-شما-در-ارزيابي-سودآوري-و-ريسك-ها-،-درك-قوانين-مربوط-به-سرمايه-كذاري-در-ملك-ها-در-كيلان-،-راهنمايي-در-معاملات-و-مراحل-قانوني،-و-تامين-المعلومات-كامل-و-معتبر-در-مورفض-بازار-ملك-كيلان-به-شما-كمك-كند.',
    'آیا گیلند ملک مشاوره برای ساخت و ساز و مشارکت در ساخت هم دارد؟' => 'آيا كيلند ملك مستشاره براي ساخت و ساز و مشاركت در ساخت هم دارفض؟',
    'آیا-گیلند-ملک-مشاوره-برای-ساخت-و-ساز-و-مشارکت-در-ساخت-هم-دارد؟' => 'آيا-كيلند-ملك-مستشاره-براي-ساخت-و-ساز-و-مشاركت-در-ساخت-هم-دارفض؟',
    'بله گیلند ملک می تواند در ساخت و ساز و مشارکت در پروژه های ساختمانی همکاری کند. مشارکت در ساخت معمولا به معنی همکاری با سرمایه گذاران به منظور ساخت یا توسعه پروژه های ساختمانی است. این همکاری می تواند شامل مشارکت در ساخت و توسعه ویلا، آپارتمان ، هتل ، مجتمع تجاری و … باشد.' => 'بله كيلند ملك مي تواند در ساخت و ساز و مشاركت در مشروع هاي ساختماني همكاري كند. مشاركت در ساخت معمولا به معني همكاري با سرمايه كذاران به منظور ساخت يا توسعه مشروع هاي ساختماني است. اين همكاري مي تواند شامل مشاركت در ساخت و توسعه فيلا، شقة ، هتل ، مجمع تجاري و … باشد.',
    'بله-گیلند-ملک-می-تواند-در-ساخت-و-ساز-و-مشارکت-در-پروژه-های-ساختمانی-همکاری-کند.-مشارکت-در-ساخت-معمولا-به-معنی-همکاری-با-سرمایه-گذاران-به-منظور-ساخت-یا-توسعه-پروژه-های-ساختمانی-است.-این-همکاری-می-تواند-شامل-مشارکت-در-ساخت-و-توسعه-ویلا،-آپارتمان-،-هتل-،-مجتمع-تجاری-و-…-باشد.' => 'بله-كيلند-ملك-مي-تواند-در-ساخت-و-ساز-و-مشاركت-در-مشروع-هاي-ساختماني-همكاري-كند.-مشاركت-در-ساخت-معمولا-به-معني-همكاري-با-سرمايه-كذاران-به-منظور-ساخت-يا-توسعه-مشروع-هاي-ساختماني-است.-اين-همكاري-مي-تواند-شامل-مشاركت-در-ساخت-و-توسعه-فيلا،-شقة-،-هتل-،-مجمع-تجاري-و-…-باشد.',
    'با همکاری گیلند ملک شما می توانید به عنوان سرمایه گذار در پروژه های ساختمانی شرکت کرده و به منظور احداث یک واحد مسکونی یا تجاری از تجربه و دانش این مجموعه بهره برداری کنید.' => 'با همكاري كيلند ملك شما مي توانيد به العنوان سرمايه كذار در مشروع هاي ساختماني شركت كرفضه و به منظور احداث يك واحد سكني يا تجاري از تجربه و دانش اين مجموعه بهره برفضاري كنيد.',
    'با-همکاری-گیلند-ملک-شما-می-توانید-به-عنوان-سرمایه-گذار-در-پروژه-های-ساختمانی-شرکت-کرده-و-به-منظور-احداث-یک-واحد-مسکونی-یا-تجاری-از-تجربه-و-دانش-این-مجموعه-بهره-برداری-کنید.' => 'با-همكاري-كيلند-ملك-شما-مي-توانيد-به-العنوان-سرمايه-كذار-در-مشروع-هاي-ساختماني-شركت-كرفضه-و-به-منظور-احداث-يك-واحد-سكني-يا-تجاري-از-تجربه-و-دانش-اين-مجموعه-بهره-برفضاري-كنيد.',
    'آیا گیلند ملک اجاره روزانه و اقامتگاه هم دارد؟' => 'آيا كيلند ملك إيجار روزانه و اقامتكاه هم دارفض؟',
    'آیا-گیلند-ملک-اجاره-روزانه-و-اقامتگاه-هم-دارد؟' => 'آيا-كيلند-ملك-إيجار-روزانه-و-اقامتكاه-هم-دارفض؟',
    'بله گیلند ملک امکانات اجاره روزانه و اقامتگاه را نیز در گیلان در اختیار دارد. این مجموعه می تواند به شما در اجاره و مدیریت ویلاها ، آپارتمان ها ، سوییت ها و کلبه ها و دیگر اقامتگاه های تعطیلاتی در مناطق گیلان به شما کمک کند.' => 'بله كيلند ملك امكانات إيجار روزانه و اقامتكاه را نيز در كيلان در اختيار دارفض. اين مجموعه مي تواند به شما در إيجار و مديريت فيلاها ، شقة ها ، سوييت ها و كلبه ها و ديكر اقامتكاه هاي تعطيلاتي در مناطق كيلان به شما كمك كند.',
    'بله-گیلند-ملک-امکانات-اجاره-روزانه-و-اقامتگاه-را-نیز-در-گیلان-در-اختیار-دارد.-این-مجموعه-می-تواند-به-شما-در-اجاره-و-مدیریت-ویلاها-،-آپارتمان-ها-،-سوییت-ها-و-کلبه-ها-و-دیگر-اقامتگاه-های-تعطیلاتی-در-مناطق-گیلان-به-شما-کمک-کند.' => 'بله-كيلند-ملك-امكانات-إيجار-روزانه-و-اقامتكاه-را-نيز-در-كيلان-در-اختيار-دارفض.-اين-مجموعه-مي-تواند-به-شما-در-إيجار-و-مديريت-فيلاها-،-شقة-ها-،-سوييت-ها-و-كلبه-ها-و-ديكر-اقامتكاه-هاي-تعطيلاتي-در-مناطق-كيلان-به-شما-كمك-كند.',
    'علاوه بر اجاره روزانه ،گیلند ملک می تواند به شما در کشف ، مدیریت و بهره برداری از اقامتگاه ها بر حسب نیازها و بودجه مشتریان به شما کمک کند تا از اقامت مطلوب و راحتی در گیلان برخوردار شوید.' => 'علاوه بر إيجار روزانه ،كيلند ملك مي تواند به شما در كشف ، مديريت و بهره برفضاري از اقامتكاه ها بر حسب نيازها و بودجه العميلان به شما كمك كند تا از اقامت مطلوب و راحتي در كيلان برخورفضار شويد.',
    'علاوه-بر-اجاره-روزانه-،گیلند-ملک-می-تواند-به-شما-در-کشف-،-مدیریت-و-بهره-برداری-از-اقامتگاه-ها-بر-حسب-نیازها-و-بودجه-مشتریان-به-شما-کمک-کند-تا-از-اقامت-مطلوب-و-راحتی-در-گیلان-برخوردار-شوید.' => 'علاوه-بر-إيجار-روزانه-،كيلند-ملك-مي-تواند-به-شما-در-كشف-،-مديريت-و-بهره-برفضاري-از-اقامتكاه-ها-بر-حسب-نيازها-و-بودجه-العميلان-به-شما-كمك-كند-تا-از-اقامت-مطلوب-و-راحتي-در-كيلان-برخورفضار-شويد.',
