    'ما تلاش کرده‌ایم نیازهای ملکی مشتریان خود را با استفاده از روش‌های پیشرفته، از جمله آموزش‌های تخصصی برای مشاوران، بهره‌گیری از کارشناسان حقوقی باتجربه و ارائه امکانات به‌روز در وب‌سایت خود، آسان، لذت‌بخش و سریع برآورده کنیم.' => 'ما تلاش كرفضه ايم نيازهاي ملكي العميلان خود را با استفاده از روش هاي بيشرفته، از جمله آموزش هاي تخصصي براي مستشاران، بهره كيري از خبيران حقوقي باتجربه و ارائه امكانات به روز در وب سايت خود، آسان، لذت بخش و سريع برآورفضه كنيم.',
    'ما-تلاش-کرده‌ایم-نیازهای-ملکی-مشتریان-خود-را-با-استفاده-از-روش‌های-پیشرفته،-از-جمله-آموزش‌های-تخصصی-برای-مشاوران،-بهره‌گیری-از-کارشناسان-حقوقی-باتجربه-و-ارائه-امکانات-به‌روز-در-وب‌سایت-خود،-آسان،-لذت‌بخش-و-سریع-برآورده-کنیم.' => 'ما-تلاش-كرفضه ايم-نيازهاي-ملكي-العميلان-خود-را-با-استفاده-از-روش هاي-بيشرفته،-از-جمله-آموزش هاي-تخصصي-براي-مستشاران،-بهره كيري-از-خبيران-حقوقي-باتجربه-و-ارائه-امكانات-به روز-در-وب سايت-خود،-آسان،-لذت بخش-و-سريع-برآورفضه-كنيم.',
